 const safeName = String(`${printablePay.employeeName}-${start}-to-${end}`).replace(/[^a-z0-9\-_]+/gi, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'payslip'

 const doc = new jsPDF({ orientation:'portrait', unit:'mm', format:'a4' })
