function getDateOffsetString(days) {
 const d = new Date()
 d.setDate(d.getDate() + days)
 d.setMinutes(d.getMinutes() - d.getTimezoneOffset())
 return d.toISOString().slice(0, 10)
}
function roundPayableOvertimeMinutes(minutes = 0) {
 const rawMinutes = Math.max(0, Math.round(safeNum(minutes, 0)))
 return Math.floor(rawMinutes / OVERTIME_BLOCK_MINUTES) * OVERTIME_BLOCK_MINUTES
}

function roundChargeableUndertimeMinutes(minutes = 0) {
 const rawMinutes = Math.max(0, Math.round(safeNum(minutes, 0)))
 if (rawMinutes <= 0) return 0
 return Math.ceil(rawMinutes / UNDERTIME_BLOCK_MINUTES) * UNDERTIME_BLOCK_MINUTES
}

function roundPenaltyMinutes(min, gracePeriodMinutes = DEFAULT_LATE_GRACE_MINUTES) {
 const rawMinutes = Math.max(0, Math.round(safeNum(min, 0)))
 const graceMinutes = Math.max(0, Math.round(safeNum(gracePeriodMinutes, DEFAULT_LATE_GRACE_MINUTES)))
 // Roma's Donuts late policy:
 // Within the employee's grace period = no late penalty;
 // after grace through 30 minutes = 30-minute penalty;
 // 31 minutes or more = 60-minute penalty.
 if (rawMinutes <= graceMinutes) return 0
 if (rawMinutes <= 30) return 30
 return 60
}

function getPayrollAttendanceDeductionSplit(metrics = {}) {
 // Payroll must show late and undertime as separate deductions without charging
 // the same late-arrival shortage twice. Late uses the company penalty bracket,
 // while undertime covers only the remaining non-break paid-work shortage,
 // early Time Out, or another genuine non-late shortage. Overbreak remains a
 // separate DTR classification and is never rounded again into UT.
 const lateMinutes = Math.max(0, Math.round(safeNum(metrics?.lateMinutes, 0)))
 const paidWorkShortageMinutes = Math.max(0, Math.round(safeNum(
  metrics?.utEligiblePaidWorkShortageMinutes,
  metrics?.paidWorkShortageMinutes
 )))
 const earlyOutMinutes = Math.max(0, Math.round(safeNum(metrics?.earlyOutMinutes, 0)))
 const rawLateArrivalMinutes = Math.max(0, Math.round(safeNum(metrics?.rawLateMinutes, 0)))
 const lateShortageCoveredMinutes = lateMinutes > 0
  ? Math.min(
     paidWorkShortageMinutes,
     metrics?.hasSchedule
      ? rawLateArrivalMinutes
      : Math.min(lateMinutes, paidWorkShortageMinutes)
    )
  : 0
 const nonLatePaidWorkShortageMinutes = Math.max(0, paidWorkShortageMinutes - lateShortageCoveredMinutes)
 const rawUndertimeMinutes = Math.max(nonLatePaidWorkShortageMinutes, earlyOutMinutes)
 const undertimeMinutes = roundChargeableUndertimeMinutes(rawUndertimeMinutes)
 return {
  lateMinutes,
  undertimeMinutes,
  rawUndertimeMinutes,
  paidWorkShortageMinutes,
  lateShortageCoveredMinutes,
  nonLatePaidWorkShortageMinutes,
  earlyOutMinutes
 }
}
function safeNum(value, fallback = 0) {
 const n = Number(value)
 return Number.isFinite(n)? n: fallback
}
function positiveNum(value, fallback = 1) {
 const n = safeNum(value, fallback)
 return n > 0? n: fallback
}
function php(a) { return `\u20B1${safeNum(a).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }
function moneyRound(value) { return Math.round((safeNum(value, 0) + Number.EPSILON) * 100) / 100 }
function isMoneySettled(balance) { return moneyRound(balance) <= 0.01 }
function genSerial(start, idx) { return `PS-${start.slice(0,7).replace('-','')}-${String(idx+1).padStart(3,'0')}` }
function getDistanceMeters(la1,lo1,la2,lo2) {
 const R=6371000,dL=(la2-la1)*Math.PI/180,dO=(lo2-lo1)*Math.PI/180
 const a=Math.sin(dL/2)**2+Math.cos(la1*Math.PI/180)*Math.cos(la2*Math.PI/180)*Math.sin(dO/2)**2
 return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))
}

function parseLocalDate(value) {
 if (!value) return null
 const clean = String(value).slice(0, 10)
 const [y, m, d] = clean.split('-').map(Number)
 if (!y ||!m ||!d) return null
 const date = new Date(y, m - 1, d)
 date.setHours(0, 0, 0, 0)
 return Number.isNaN(date.getTime())? null: date
}

function formatDateLocal(date) {
 const d = new Date(date)
 d.setHours(0, 0, 0, 0)
 d.setMinutes(d.getMinutes() - d.getTimezoneOffset())
 return d.toISOString().slice(0, 10)
}

function addMonthsClampedDateString(dateStr, monthOffset = 0) {
 const start = parseLocalDate(dateStr)
 if (!start) return ''
 const targetYear = start.getFullYear()
 const targetMonth = start.getMonth() + Number(monthOffset || 0)
 const dueDay = start.getDate()
 const lastDayOfTargetMonth = new Date(targetYear, targetMonth + 1, 0).getDate()
 const out = new Date(targetYear, targetMonth, Math.min(dueDay, lastDayOfTargetMonth))
 out.setHours(0, 0, 0, 0)
 return formatDateLocal(out)
}

function getMonthlyPayableDueDates(startDueDate, repeatUntilDate, maxMonths = 60) {
 const start = parseLocalDate(startDueDate)
 const end = parseLocalDate(repeatUntilDate)
 if (!start ||!end || end < start) return []

 const dates = []
 for (let i = 0; i < maxMonths; i++) {
 const dueDate = addMonthsClampedDateString(startDueDate, i)
 const due = parseLocalDate(dueDate)
 if (!due || due > end) break
 dates.push(dueDate)
 }
 return dates
}

function addYearsLocal(date, years) {
 const d = new Date(date)
 const originalMonth = d.getMonth()
 d.setFullYear(d.getFullYear() + years)
 // Keep leap-day hires stable by moving overflowed dates to the last day of the target month.
 if (d.getMonth()!== originalMonth) d.setDate(0)
 d.setHours(0, 0, 0, 0)
 return d
}

function addMonthsLocal(date, months) {
 const d = new Date(date)
 const originalDate = d.getDate()
 d.setDate(1)
 d.setMonth(d.getMonth() + safeNum(months, 0))
 const lastDay = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()
 d.setDate(Math.min(originalDate, lastDay))
 d.setHours(0, 0, 0, 0)
 return d
}

function daysInclusive(startDate, endDate) {
 const start = parseLocalDate(startDate)
 const end = parseLocalDate(endDate)
 if (!start ||!end || end < start) return 0
 return Math.floor((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1
}


function addDaysToDateString(dateStr, days = 0) {
 const date = parseLocalDate(dateStr)
 if (!date) return ''
 date.setDate(date.getDate() + safeNum(days, 0))
 return formatDateLocal(date)
}

function normalizeComputedPayrollPeriods(rows = []) {
 const periods = {}
 ;(rows || []).forEach(row => {
  const start = String(row?.payroll_start || '').slice(0, 10)
  const end = String(row?.payroll_end || '').slice(0, 10)
  if (!parseLocalDate(start) || !parseLocalDate(end) || end < start) return
  periods[`${start}|${end}`] = { payroll_start:start, payroll_end:end }
 })
 return Object.values(periods).sort((a, b) => a.payroll_start.localeCompare(b.payroll_start) || a.payroll_end.localeCompare(b.payroll_end))
}

function getFirstUncomputedPayrollDate(candidateDate = '', computedPeriods = []) {
 let candidate = String(candidateDate || '').slice(0, 10)
 if (!parseLocalDate(candidate)) return ''
 const periods = normalizeComputedPayrollPeriods(computedPeriods)
 for (let pass = 0; pass <= periods.length; pass += 1) {
  const coveringPeriod = periods.find(period => period.payroll_start <= candidate && period.payroll_end >= candidate)
  if (!coveringPeriod) return candidate
  candidate = addDaysToDateString(coveringPeriod.payroll_end, 1)
  if (!candidate) return ''
 }
 return candidate
}

function isAbsentAttendanceLog(log = {}) {
 return String(log?.status || '').trim().toLowerCase() === 'absent'
}

function isAttendanceLogEligibleForActiveShift(log = {}) {
 const logId = String(log?.id || '')
 return !!logId && !logId.startsWith('offline_') && !!log?.time_in && !log?.time_out && !isAbsentAttendanceLog(log)
}

function isPaidLeaveCoveringDate(leaves = [], dateStr = '') {
 if (!dateStr) return false
 return (leaves || []).some(leave => {
  if (!isPaidLeaveRecord(leave)) return false
  const start = String(leave?.leave_start || '').slice(0, 10)
  const end = String(leave?.leave_end || '').slice(0, 10)
  return start && end && start <= dateStr && end >= dateStr
 })
}

function dateStringDiffDays(a = '', b = '') {
 const da = parseLocalDate(String(a || '').slice(0, 10))
 const db = parseLocalDate(String(b || '').slice(0, 10))
 if (!da || !db) return null
 return Math.round((db.getTime() - da.getTime()) / (1000 * 60 * 60 * 24))
}

function getHolidayAbsenceGuardDates(holidayDate = '') {
 const dateStr = String(holidayDate || '').slice(0, 10)
 if (!dateStr) return []
 return HOLIDAY_ABSENCE_GUARD_DAY_OFFSETS
  .map(offset => addDaysToDateString(dateStr, offset))
  .filter(Boolean)
}

function getHolidayAbsenceGuardFailure(holidayDate = '', attendanceByDate = {}, paidLeaves = []) {
 const guardDates = getHolidayAbsenceGuardDates(holidayDate)
 const absentDates = guardDates.filter(dateStr => {
  const log = attendanceByDate?.[dateStr]
  return isAbsentAttendanceLog(log) && !isPaidLeaveCoveringDate(paidLeaves, dateStr)
 })
 return {
  eligible: absentDates.length === 0,
  absentDates,
  guardDates
 }
}

function buildDateRangeRows(startDate, endDate, mapper = null) {
 const totalDays = daysInclusive(startDate, endDate)
 return Array.from({ length: totalDays }, (_, i) => {
  const dateStr = addDaysToDateString(startDate, i)
  const date = parseLocalDate(dateStr)
  const row = {
   dateStr,
   day: date? date.getDate(): i + 1,
   dayName: date? date.toLocaleDateString('en-US', { weekday:'short' }): '',
   index:i
  }
  return typeof mapper === 'function'? mapper(row, i): row
 })
}

function pad2(value) {
 return String(value).padStart(2, '0')
}

function yearMonthFromParts(year, month) {
 return `${year}-${pad2(month)}`
}

function shiftYearMonth(yearMonth, monthOffset = 0) {
 const [y, m] = String(yearMonth || '').split('-').map(Number)
 if (!y || !m) return ''
 const date = new Date(y, m - 1 + safeNum(monthOffset, 0), 1)
 return yearMonthFromParts(date.getFullYear(), date.getMonth() + 1)
}

function getPayrollCutoffPeriodFromParts(yearMonth, cutoffType = '11-25') {
 const [y, m] = String(yearMonth || '').split('-').map(Number)
 if (!y || !m) return null
 const ymDate = (year, month, day) => `${year}-${pad2(month)}-${pad2(day)}`
 if (cutoffType === '26-10') {
  const nextYear = m === 12? y + 1: y
  const nextMonth = m === 12? 1: m + 1
  return {
   key:`${yearMonth}|26-10`,
   type:'26-10',
   start:ymDate(y, m, 26),
   end:ymDate(nextYear, nextMonth, 10),
   label:`${formatDateForDisplay(ymDate(y, m, 26))} – ${formatDateForDisplay(ymDate(nextYear, nextMonth, 10))} (26th–10th)`
  }
 }
 return {
  key:`${yearMonth}|11-25`,
  type:'11-25',
  start:ymDate(y, m, 11),
  end:ymDate(y, m, 25),
  label:`${formatDateForDisplay(ymDate(y, m, 11))} – ${formatDateForDisplay(ymDate(y, m, 25))} (11th–25th)`
 }
}

function getDTRCutoffPeriodFromKey(key) {
 const [yearMonth, type] = String(key || '').split('|')
 return getPayrollCutoffPeriodFromParts(yearMonth, type || '11-25')
}

function getCurrentDTRCutoffKey(todayDate = getTodayDate()) {
 const date = parseLocalDate(todayDate)
 if (!date) return `${String(todayDate).slice(0, 7)}|11-25`
 const y = date.getFullYear()
 const m = date.getMonth() + 1
 const d = date.getDate()
 if (d >= 11 && d <= 25) return `${yearMonthFromParts(y, m)}|11-25`
 if (d >= 26) return `${yearMonthFromParts(y, m)}|26-10`
 return `${shiftYearMonth(yearMonthFromParts(y, m), -1)}|26-10`
}

function getPreviousDTRCutoffKey(key) {
 const [yearMonth, type] = String(key || '').split('|')
 if (type === '11-25') return `${shiftYearMonth(yearMonth, -1)}|26-10`
 return `${yearMonth}|11-25`
}

function getPayrollAttendanceReconMarker(startDate = '', endDate = '', employeeId = '') {
 return `HIST-ATTENDANCE-RECON|${String(startDate || '').slice(0,10)}|${String(endDate || '').slice(0,10)}|EMP:${String(employeeId || '')}`
}

function getDTRCutoffKeyFromPeriod(startDate = '', endDate = '') {
 const start = String(startDate || '').slice(0, 10)
 const end = String(endDate || '').slice(0, 10)
 if (!start || !end) return ''
 if (start.slice(8, 10) === '11' && end.slice(8, 10) === '25' && start.slice(0, 7) === end.slice(0, 7)) return `${start.slice(0, 7)}|11-25`
 if (start.slice(8, 10) === '26' && end.slice(8, 10) === '10') return `${start.slice(0, 7)}|26-10`
 const match = getDTRCutoffOptions(60, end).find(period => period.start === start && period.end === end)
 return match?.key || ''
}

function serializeAttendanceReconDayDetails(dayDetails = []) {
 return (dayDetails || []).filter(day => safeNum(day?.undertimeMinutes, 0) > 0 || safeNum(day?.lateMinutes, 0) > 0).map(day => [
  day.date || '', day.timeIn || '', day.timeOut || '', safeNum(day.deductedBreakMinutes, 0), safeNum(day.paidWorkedMinutes, 0),
  safeNum(day.lateMinutes, 0), safeNum(day.undertimeMinutes, 0), moneyRound(day.deductionAmount || 0), day.deductionType || 'Automatic undertime deduction'
 ].map(value => encodeURIComponent(String(value ?? ''))).join('~')).join(';')
}

function parseAttendanceReconDayDetails(serialized = '') {
 if (!serialized) return []
 return String(serialized).split(';').map(chunk => {
  const values = chunk.split('~').map(value => {
   try { return decodeURIComponent(value) } catch(e) { return value }
  })
  if (!values[0]) return null
  return {
   date:values[0], timeIn:values[1] || '', timeOut:values[2] || '', deductedBreakMinutes:safeNum(values[3], 0),
   paidWorkedMinutes:safeNum(values[4], 0), lateMinutes:safeNum(values[5], 0), undertimeMinutes:safeNum(values[6], 0),
   deductionAmount:moneyRound(values[7]), deductionType:values[8] || 'Automatic undertime deduction'
  }
 }).filter(Boolean)
}

function parsePayrollAttendanceReconMetadata(notes = '') {
 const text = String(notes || '')
 const markerMatch = text.match(/HIST-ATTENDANCE-RECON\|(\d{4}-\d{2}-\d{2})\|(\d{4}-\d{2}-\d{2})\|EMP:([^|\s]+)/)
 const sourceStart = markerMatch?.[1] || ''
 const sourceEnd = markerMatch?.[2] || ''
 const employeeId = markerMatch?.[3] || ''
 const sourceStartIndex = text.indexOf(PAYROLL_ATTENDANCE_RECON_SOURCE_OPEN)
 const sourceEndIndex = sourceStartIndex >= 0 ? text.indexOf(PAYROLL_ATTENDANCE_RECON_SOURCE_CLOSE, sourceStartIndex) : -1
 const serializedDays = sourceStartIndex >= 0 && sourceEndIndex > sourceStartIndex
  ? text.slice(sourceStartIndex + PAYROLL_ATTENDANCE_RECON_SOURCE_OPEN.length, sourceEndIndex)
  : ''
 const appliedMatch = text.match(/CORRECTION-APPLIED:(\d{4}-\d{2}-\d{2})/)
 return {
  isHistoricalAttendanceRecon:!!markerMatch,
  sourceStart,
  sourceEnd,
  employeeId,
  correctionAppliedDate:appliedMatch?.[1] || '',
  days:parseAttendanceReconDayDetails(serializedDays)
 }
}

function getDTRCutoffOptions(count = 36, todayDate = getTodayDate()) {
 const options = []
 let key = getCurrentDTRCutoffKey(todayDate)
 for (let i = 0; i < count; i++) {
  const period = getDTRCutoffPeriodFromKey(key)
  if (period) options.push(period)
  key = getPreviousDTRCutoffKey(key)
 }
 return options
}

function formatDateForDisplay(dateStr) {
 const date = parseLocalDate(dateStr)
 if (!date) return dateStr || ''
 return date.toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' })
}

function mergeDTRDayLogs(dayLogs = []) {
 const logs = (dayLogs || []).filter(Boolean)
 if (!logs.length) return null
 const hasAbsent = logs.some(l => l.status === 'Absent')
 const timeInLogs = logs.filter(l => l.time_in)
 const timeOutLogs = logs.filter(l => l.time_out)
 const earliestIn = timeInLogs.map(l => l.time_in).sort()[0] || ''
 const latestOut = timeOutLogs.map(l => l.time_out).sort().slice(-1)[0] || ''
 const approvedOT = roundPayableOvertimeMinutes(logs.filter(l => l.overtime_approved === true).reduce((sum,l)=>sum+safeNum(l.overtime_minutes,0),0))
 const lateMinutes = logs.reduce((sum,l)=>sum+safeNum(l.late_minutes,0),0)
 const breakMinutes = logs.reduce((sum,l)=>sum+safeNum(l.total_break_minutes,0),0)
 const status = hasAbsent? 'Absent': lateMinutes > 0? 'Late': earliestIn? 'Present': (logs[0]?.status || '')
 return {
  ...logs[0],
  time_in:earliestIn,
  time_out:latestOut,
  late_minutes:lateMinutes,
  total_break_minutes:breakMinutes,
  overtime_minutes:approvedOT,
  overtime_approved:approvedOT > 0,
  status,
  _logs:logs,
  duplicateCount:logs.length
 }
}

function groupDTRLogsByDate(logs = []) {
 const grouped = {}
 ;(logs || []).forEach(log => {
  const key = String(log.attendance_date || '').slice(0, 10)
  if (!key) return
  if (!grouped[key]) grouped[key] = []
  grouped[key].push(log)
 })
 return grouped
}

function getLeaveOverlapDays(leave, periodStart, periodEnd) {
 const start = parseLocalDate(leave?.leave_start)
 const end = parseLocalDate(leave?.leave_end)
 const pStart = parseLocalDate(periodStart)
 const pEnd = parseLocalDate(periodEnd)
 if (!start ||!end ||!pStart ||!pEnd) return 0
 const overlapStart = start > pStart? start: pStart
 const overlapEnd = end < pEnd? end: pEnd
 if (overlapEnd < overlapStart) return 0
 return daysInclusive(formatDateLocal(overlapStart), formatDateLocal(overlapEnd))
}


function getAttendanceDateTime(attendanceDate, timeValue, addDay = false) {
 const base = parseLocalDate(attendanceDate)
 if (!base ||!timeValue) return null
 const [h, m, s] = String(timeValue).split(':').map(Number)
 base.setHours(Number(h) || 0, Number(m) || 0, Number(s) || 0, 0)
 if (addDay) base.setDate(base.getDate() + 1)
 return base
}

function getOpenShiftHours(log, asOf = new Date()) {
 if (!log?.attendance_date ||!log?.time_in) return 0
 const start = getAttendanceDateTime(log.attendance_date, log.time_in)
 if (!start) return 0
 return Math.max(0, (asOf.getTime() - start.getTime()) / (1000 * 60 * 60))
}

function isOpenAttendanceLogInDutyWindow(log, asOf = new Date(), maxHours = 36) {
 if (!log?.time_in || log?.time_out) return false
 const hours = getOpenShiftHours(log, asOf)
 return hours >= 0 && hours <= maxHours
}

function isTimedOutOnDate(log, targetDate) {
 if (!log?.time_in ||!log?.time_out ||!targetDate) return false

 // Normal same-day logs use the attendance date.
 if (String(log.attendance_date || '').slice(0, 10) === targetDate) return true

 // Overnight logs are saved under the shift start date, so a 10PM-6AM shift
 // that timed out after midnight should count as timed out on the next day.
 const inM = minutesFromTime(log.time_in)
 const outM = minutesFromTime(log.time_out)
 const crossedMidnight = outM < inM
 if (!crossedMidnight) return false

 const outDate = parseLocalDate(log.attendance_date)
 if (!outDate) return false
 outDate.setDate(outDate.getDate() + 1)
 return formatDateLocal(outDate) === targetDate
}

function getCurrentSILCycle(hireDate, asOf = new Date()) {
 const hire = parseLocalDate(hireDate)
 const todayDate = parseLocalDate(formatDateLocal(asOf))
 if (!hire ||!todayDate) return null

 let years = todayDate.getFullYear() - hire.getFullYear()
 let anniversary = addYearsLocal(hire, years)

 if (anniversary > todayDate) {
 years -= 1
 anniversary = addYearsLocal(hire, years)
 }

 if (years < 1) return null

 const cycleEnd = addYearsLocal(anniversary, 1)
 cycleEnd.setDate(cycleEnd.getDate() - 1)

 return {
 years,
 start: formatDateLocal(anniversary),
 end: formatDateLocal(cycleEnd)
 }
}

function getPreviousSILCycle(cycle) {
 if (!cycle || safeNum(cycle.years, 0) <= 1) return null
 const currentStart = parseLocalDate(cycle.start)
 if (!currentStart) return null

 const previousStart = addYearsLocal(currentStart, -1)
 const previousEnd = new Date(currentStart)
 previousEnd.setDate(previousEnd.getDate() - 1)

 return {
 years: safeNum(cycle.years, 0) - 1,
 start: formatDateLocal(previousStart),
 end: formatDateLocal(previousEnd)
 }
}

function hasOneYearService(hireDate, asOf = new Date()) {
 return!!getCurrentSILCycle(hireDate, asOf)
}

function normalizeLeaveType(type) {
 const t = String(type || '').trim().toLowerCase()
 if (t === 'sil' || t.includes('service incentive')) return 'SIL'
 if (t.includes('unpaid') || t.includes('without pay') || t.includes('lwop')) return 'Unpaid Leave'
 return type || 'Unpaid Leave'
}

function isPaidLeaveRecord(leave) {
 return leave?.is_paid === true || normalizeLeaveType(leave?.leave_type) === 'SIL'
}

function getLeaveDisplayName(type) {
 return normalizeLeaveType(type) === 'SIL'? 'Service Incentive Leave (SIL)': 'Unpaid Leave / Leave Without Pay'
}

function getEmployeeLeaveInfo(emp) {
 const eligible = hasOneYearService(emp?.hire_date)
 const silBalance = safeNum(emp?.sil_balance, 0)
 const canFileSIL = eligible && silBalance > 0

 return {
 eligible,
 silBalance,
 type: canFileSIL? 'SIL': 'Unpaid Leave',
 isPaid: canFileSIL,
 buttonLabel: canFileSIL? 'File SIL': 'File Leave',
 title: canFileSIL? 'File SIL Request': 'File Leave Request',
 label: canFileSIL? 'Service Incentive Leave (SIL) Paid': 'Unpaid Leave / Leave Without Pay',
 note: canFileSIL
? `Remaining SIL: ${silBalance} day(s). Approved SIL is paid.`
: eligible
? 'You are SIL-qualified, but you have no SIL balance left. This request will be unpaid.'
: 'SIL becomes available after 1 year of service. This request will be unpaid.'
 }
}

const LEAVE_FILING_TYPE_OPTIONS = [
 { value:'planned', label:'Planned Leave', note:'Must be filed at least 3 days before the leave date.' },
 { value:'emergency_sick', label:'Emergency Sick Leave', note:'For sudden illness or medical emergency. 3-day advance filing is bypassed and subject to admin approval.' },
 { value:'emergency_personal', label:'Emergency Personal Leave', note:'For urgent family or personal emergency. 3-day advance filing is bypassed and subject to admin approval.' }
]

function getLeaveFilingTypeInfo(value) {
 return LEAVE_FILING_TYPE_OPTIONS.find(option => option.value === value) || LEAVE_FILING_TYPE_OPTIONS[0]
}

function isEmergencyLeaveFiling(value) {
 return value === 'emergency_sick' || value === 'emergency_personal'
}


