 function getBatchItem(batch = {}) {
  return (inventoryItems || []).find(i => String(i.id) === String(batch.item_id)) || null
 }
 function getBatchesForItem(itemId, includeEmpty = false) {
  return (inventoryBatches || [])
   .filter(b => String(b.item_id || '') === String(itemId || ''))
   .filter(b => includeEmpty || safeNum(b.quantity_remaining, 0) > 0)
   .sort((a,b)=>{
    const ea = String(a.expiry_date || '9999-12-31')
    const eb = String(b.expiry_date || '9999-12-31')
    if (ea !== eb) return ea.localeCompare(eb)
    return String(a.received_date || '').localeCompare(String(b.received_date || ''))
   })
 }
 function getBatchDaysLeft(batch = {}) {
  if (!batch.expiry_date) return null
  const expiry = parseLocalDate(batch.expiry_date)
  const base = parseLocalDate(today)
  if (!expiry || !base) return null
  return Math.ceil((expiry.getTime() - base.getTime()) / (1000 * 60 * 60 * 24))
 }
 function getBatchStatusInfo(batch = {}) {
  const qty = safeNum(batch.quantity_remaining, 0)
  if (qty <= 0) return { label:'Consumed', color:'#777', bg:'#f7f7f7', priority:9 }
  const daysLeft = getBatchDaysLeft(batch)
  if (daysLeft === null) return { label:'No expiry set', color:'#777', bg:'#f7f7f7', priority:8 }
  if (daysLeft < 0) return { label:'EXPIRED', color:'#ca1b1b', bg:'#fff5f5', priority:0 }
  if (daysLeft === 0) return { label:'Expires today', color:'#ca1b1b', bg:'#fff5f5', priority:1 }
  if (daysLeft <= 7) return { label:`Expires in ${daysLeft} day(s)`, color:'#f57c00', bg:'#fff8e1', priority:2 }
  if (daysLeft <= 30) return { label:`Expires in ${daysLeft} days`, color:'#f5a623', bg:'#fffaf0', priority:3 }
  return { label:`Expires ${batch.expiry_date}`, color:'#2d8a4e', bg:'#f0fff4', priority:4 }
 }
 function getBatchSummaryForItem(item = {}) {
  const batches = getBatchesForItem(item.id, false)
  const totalBatchQty = batches.reduce((sum,b)=>sum + safeNum(b.quantity_remaining, 0), 0)
  const nearest = batches.find(b => b.expiry_date) || null
  const expiredQty = batches.filter(b => getBatchDaysLeft(b)!==null && getBatchDaysLeft(b) < 0).reduce((sum,b)=>sum + safeNum(b.quantity_remaining, 0), 0)
  const nearQty = batches.filter(b => { const d = getBatchDaysLeft(b); return d!==null && d >= 0 && d <= 7 }).reduce((sum,b)=>sum + safeNum(b.quantity_remaining, 0), 0)
  return { batches, batchCount:batches.length, totalBatchQty:moneyRound(totalBatchQty), nearest, nearestInfo:nearest?getBatchStatusInfo(nearest):null, expiredQty:moneyRound(expiredQty), nearQty:moneyRound(nearQty), unbatchedQty:moneyRound(Math.max(0, safeNum(item.current_stock,0) - totalBatchQty)) }
 }
 function getFilteredInventoryBatches() {
  const term = String(batchSearch || '').trim().toLowerCase()
  return (inventoryBatches || []).filter(batch => {
   if (batchItemFilter && String(batch.item_id || '') !== String(batchItemFilter)) return false
   const item = getBatchItem(batch)
   const haystack = [batch.batch_code, batch.item_name, item?.name, batch.category, item?.category, batch.supplier_name, batch.expiry_date, batch.received_date, batch.notes].filter(Boolean).join(' ').toLowerCase()
   return !term || haystack.includes(term)
  }).sort((a,b)=>{
   const ia = getBatchStatusInfo(a).priority - getBatchStatusInfo(b).priority
   if (ia) return ia
   return String(a.expiry_date || '9999-12-31').localeCompare(String(b.expiry_date || '9999-12-31'))
  })
 }
 async function createInventoryBatchRecord(item, qty, options = {}) {
  if (!item?.id || safeNum(qty, 0) <= 0) return null
  const supplier = suppliers.find(s => String(s.id) === String(options.supplier_id || item.supplier_id || '')) || null
  const batchCode = String(options.batch_code || '').trim() || `LOT-${String(item.name || 'ITEM').replace(/[^A-Z0-9]+/gi,'').slice(0,8).toUpperCase()}-${Date.now().toString().slice(-6)}`
  const payload = {
   item_id:item.id,
   item_name:item.name,
   category:getInventoryCategoryLabel(item),
   batch_code:batchCode,
   received_date:options.received_date || today,
   expiry_date:options.expiry_date || null,
   quantity_received:moneyRound(qty),
   quantity_remaining:moneyRound(options.quantity_remaining !== undefined && options.quantity_remaining !== '' ? safeNum(options.quantity_remaining, qty) : qty),
   unit:item.unit || options.unit || 'pcs',
   cost_per_unit:safeNum(options.cost_per_unit, safeNum(item.cost_per_unit, 0)),
   supplier_id:options.supplier_id || item.supplier_id || null,
   supplier_name:options.supplier_name || supplier?.name || null,
   status:'active',
   notes:options.notes || null,
   created_by:currentAdminLabel
  }
  const { data, error } = await supabase.from('inventory_item_batches').insert(payload).select().single()
  if (error) throw error
  return data
 }
 async function saveManualInventoryBatch() {
  if (!batchForm.item_id) { showToast('Select an item for this batch.', 'red'); return }
  if (!batchForm.quantity_received || safeNum(batchForm.quantity_received, 0) <= 0) { showToast('Enter a valid batch quantity.', 'red'); return }
  const item = inventoryItems.find(i => String(i.id) === String(batchForm.item_id))
  if (!item) { showToast('Item not found.', 'red'); return }
  setSavingBatch(true)
  try {
   const qty = safeNum(batchForm.quantity_received, 0)
   const remaining = batchForm.quantity_remaining !== '' ? safeNum(batchForm.quantity_remaining, qty) : qty
   const stockBefore = safeNum(item.current_stock, 0)
   const shouldAddToStock = window.confirm(`Add this batch quantity to current inventory stock?

OK = add ${qty} ${item.unit} to stock.
Cancel = create batch record only for existing stock.`)
   const batch = await createInventoryBatchRecord(item, qty, { ...batchForm, quantity_remaining:remaining, supplier_id:batchForm.supplier_id || item.supplier_id || null })
   if (shouldAddToStock) {
    const stockAfter = moneyRound(stockBefore + qty)
    await supabase.from('inventory_items').update({ current_stock:stockAfter, expiry_date:batchForm.expiry_date || item.expiry_date || null }).eq('id', item.id)
    await supabase.from('inventory_transactions').insert({ item_id:item.id, item_name:item.name, category:item.category, transaction_type:'in', quantity:qty, unit:item.unit, stock_before:stockBefore, stock_after:stockAfter, reference:`BATCH-${String(batch?.batch_code || '').slice(0,18)}`, notes:`Batch/Lot stock-in${batchForm.expiry_date?` | Expiry: ${batchForm.expiry_date}`:''}`, performed_by:`Admin (${adminRole})` })
   }
   await logAudit('INVENTORY BATCH CREATED','Admin',item.name,`Batch ${batch.batch_code} | ${qty} ${item.unit} | Expiry ${batchForm.expiry_date || 'N/A'}`)
   setBatchForm({ item_id:'', batch_code:'', received_date:today, expiry_date:'', quantity_received:'', quantity_remaining:'', supplier_id:'', cost_per_unit:'', notes:'' })
   setBatchItemSearch('')
   setShowBatchForm(false)
   await loadInventoryItems(); await loadInventoryBatches(); await loadInventoryTransactions()
   showToast('Batch / expiry lot saved successfully.')
  } catch(err) { showToast('Failed to save batch: ' + err.message, 'red') }
  finally { setSavingBatch(false) }
 }
 async function deductInventoryBatchesFEFO(itemId, qty, options = {}) {
  const amount = safeNum(qty, 0)
  if (!itemId || amount <= 0) return []
  let batches = getBatchesForItem(itemId, false)
  if (!batches.length) return []
  let remaining = amount
  const consumed = []
  for (const batch of batches) {
   if (remaining <= 0) break
   const before = safeNum(batch.quantity_remaining, 0)
   if (before <= 0) continue
   const take = Math.min(before, remaining)
   const after = moneyRound(before - take)
   const status = after <= 0 ? 'consumed' : 'active'
   const { error } = await supabase.from('inventory_item_batches').update({ quantity_remaining:after, status, last_movement_type:options.movement_type || 'out', last_movement_date:options.movement_date || today, updated_at:new Date().toISOString() }).eq('id', batch.id)
   if (error) throw error
   consumed.push({ ...batch, quantity_used:moneyRound(take), quantity_before:before, quantity_after:after })
   remaining = moneyRound(remaining - take)
  }
  if (consumed.length) await loadInventoryBatches()
  return consumed
 }
 async function deductSpecificInventoryBatch(batchId, qty, options = {}) {
  const batch = (inventoryBatches || []).find(b => String(b.id) === String(batchId))
  if (!batch || safeNum(qty,0) <= 0) return null
  const before = safeNum(batch.quantity_remaining, 0)
  if (safeNum(qty,0) > before) throw new Error(`Selected batch has only ${before} ${batch.unit || ''} remaining.`)
  const after = moneyRound(before - safeNum(qty,0))
  const { error } = await supabase.from('inventory_item_batches').update({ quantity_remaining:after, status:after<=0?'consumed':'active', last_movement_type:options.movement_type || 'out', last_movement_date:options.movement_date || today, updated_at:new Date().toISOString() }).eq('id', batchId)
  if (error) throw error
  await loadInventoryBatches()
  return { ...batch, quantity_used:moneyRound(qty), quantity_before:before, quantity_after:after }
 }
 function startExpiredBatchWastage(batch) {
  if (!batch?.id) return
  setWastageItemId(batch.item_id)
  setWastageBatchId(batch.id)
  setWastageQty(String(safeNum(batch.quantity_remaining, 0) > 0 ? safeNum(batch.quantity_remaining, 0) : ''))
  setWastageReason('Expired / Spoiled')
  setWastageReasonOther('')
  setWastageDate(today)
  setWastageNotes(`FEFO batch expiry action: ${batch.item_name || 'Item'} | Batch ${batch.batch_code || batch.id} | Expired on ${batch.expiry_date || 'no date'}.`)
  setWastageChargeEmployee(false)
  setWastageEmployeeId('')
  setShowWastageForm(true)
  setShowStockForm(false)
  setInventorySubView('items')
  showToast('Expired batch loaded into Wastage form. Review quantity, then confirm.')
 }

 function getCrateMovementSignedQty(movement) {
 const qty = safeNum(movement?.quantity, 0)
 const direction = String(movement?.direction || '').toLowerCase()
 const type = String(movement?.movement_type || '').toLowerCase()

 // Positive means crates are with the reseller. Negative means crates returned/reduced.
 if (direction === 'out' || direction === 'increase_balance') return qty
 if (direction === 'in' || direction === 'reduce_balance') return -qty
 if (type === 'dispatch' || type === 'released') return qty
 if (type === 'collection' || type === 'returned' || type === 'return') return -qty
 if (type === 'lost' || type === 'damaged') return -qty
 return qty
 }

 function getResellerRecordById(resellerId) {
 return (resellers || []).find(r => String(r.id) === String(resellerId)) || null
 }

 function getInvoiceRecordById(invoiceId) {
 return (deliveryInvoices || []).find(inv => String(inv.id) === String(invoiceId)) || null
 }

 function getCrateAssetType(movement) {
 const raw = String(movement?.asset_type || movement?.item_type || movement?.crate_item || '').trim().toLowerCase()
 const type = String(movement?.movement_type || '').trim().toLowerCase()
 const notes = String(movement?.notes || '').trim().toLowerCase()
 if (raw.includes('cover') || type.includes('cover') || notes.startsWith('[cover]')) return 'cover'
 return 'crate'
 }

 function getCrateAssetLabel(assetType, plural = true) {
 return String(assetType || 'crate') === 'cover' ? (plural ? 'crate covers' : 'crate cover') : (plural ? 'crates' : 'crate')
 }

 function isCompanyCrateStockMovement(movement) {
 const type = String(movement?.movement_type || '').toLowerCase()
 const resellerName = String(movement?.reseller_name || '').trim().toLowerCase()
 return type.startsWith('company_') || resellerName === 'company inventory'
 }

 function getCompanyCrateSignedQty(movement) {
 if (!isCompanyCrateStockMovement(movement)) return 0
 const qty = safeNum(movement?.quantity, 0)
 const direction = String(movement?.direction || '').toLowerCase()
 const type = String(movement?.movement_type || '').toLowerCase()

 // Positive means crates owned by the company increased. Negative means damaged/lost/deducted.
 if (direction === 'in' || direction === 'increase_stock') return qty
 if (direction === 'out' || direction === 'reduce_stock') return -qty
 if (type.includes('add') || type.includes('purchase') || type.includes('initial') || type.includes('increase')) return qty
 if (type.includes('deduct') || type.includes('damage') || type.includes('lost') || type.includes('writeoff') || type.includes('decrease')) return -qty
 return qty
 }

 function getCrateBalanceRows(ignoreSearch = false) {
 const map = {}
 ;(resellers || []).forEach(r => {
 map[String(r.id)] = {
 reseller_id:String(r.id),
 reseller_name:r.name || 'Unnamed Reseller',
 area:r.area || '',
 cratesReleased:0,
 cratesCollected:0,
 crateAdjustments:0,
 crateBalance:0,
 coversReleased:0,
 coversCollected:0,
 coverAdjustments:0,
 coverBalance:0,
 last_movement:null
 }
 })

 ;(crateMovements || []).forEach(m => {
 if (isCompanyCrateStockMovement(m)) return
 const key = String(m.reseller_id || m.reseller_name || 'unknown')
 if (!map[key]) {
 map[key] = {
 reseller_id:m.reseller_id || key,
 reseller_name:m.reseller_name || 'Unknown Reseller',
 area:'',
 cratesReleased:0,
 cratesCollected:0,
 crateAdjustments:0,
 crateBalance:0,
 coversReleased:0,
 coversCollected:0,
 coverAdjustments:0,
 coverBalance:0,
 last_movement:null
 }
 }
 const signed = getCrateMovementSignedQty(m)
 const qty = safeNum(m.quantity, 0)
 const type = String(m.movement_type || '').toLowerCase()
 const assetType = getCrateAssetType(m)
 const bucket = assetType === 'cover' ? 'cover' : 'crate'
 if (bucket === 'cover') {
 if (type === 'dispatch' || type === 'released' || type === 'settlement_dispatch') map[key].coversReleased += qty
 else if (type === 'collection' || type === 'returned' || type === 'return' || type === 'settlement_collection') map[key].coversCollected += qty
 else map[key].coverAdjustments += signed
 map[key].coverBalance += signed
 } else {
 if (type === 'dispatch' || type === 'released' || type === 'settlement_dispatch') map[key].cratesReleased += qty
 else if (type === 'collection' || type === 'returned' || type === 'return' || type === 'settlement_collection') map[key].cratesCollected += qty
 else map[key].crateAdjustments += signed
 map[key].crateBalance += signed
 }
 if (!map[key].last_movement || new Date(m.created_at || m.movement_date || 0) > new Date(map[key].last_movement.created_at || map[key].last_movement.movement_date || 0)) {
 map[key].last_movement = m
 }
 })

 return Object.values(map).map(row => ({
 ...row,
 // Backward-compatible aliases used by older parts of the crates module.
 dispatched:row.cratesReleased,
 collected:row.cratesCollected,
 adjustments:row.crateAdjustments,
 balance:row.crateBalance,
 hasAnyCrateRecord:!!(row.cratesReleased || row.cratesCollected || row.crateAdjustments || row.crateBalance || row.coversReleased || row.coversCollected || row.coverAdjustments || row.coverBalance)
 }))
 .filter(row => row.hasAnyCrateRecord || !crateSearch)
 .filter(row => {
 const q = ignoreSearch ? '' : String(crateSearch || '').trim().toLowerCase()
 if (!q) return true
 return String(row.reseller_name || '').toLowerCase().includes(q) || String(row.area || '').toLowerCase().includes(q)
 })
 .sort((a,b) => (safeNum(b.crateBalance, 0) + safeNum(b.coverBalance, 0)) - (safeNum(a.crateBalance, 0) + safeNum(a.coverBalance, 0)) || String(a.reseller_name).localeCompare(String(b.reseller_name)))
 }

 function getCrateDashboardData() {
 const rows = getCrateBalanceRows()
 const allRows = getCrateBalanceRows(true)
 const activeMovements = (crateMovements || []).filter(m => !isCompanyCrateStockMovement(m))
 const companyMovements = (crateMovements || []).filter(isCompanyCrateStockMovement)
 const movementAsset = assetType => activeMovements.filter(m => getCrateAssetType(m) === assetType)
 const companyAsset = assetType => companyMovements.filter(m => getCrateAssetType(m) === assetType)
 const releasedTypes = ['dispatch','released','settlement_dispatch']
 const collectedTypes = ['collection','returned','return','settlement_collection']
 const totalReleased = movementAsset('crate').filter(m => releasedTypes.includes(String(m.movement_type || '').toLowerCase())).reduce((s,m)=>s+safeNum(m.quantity,0),0)
 const totalCollected = movementAsset('crate').filter(m => collectedTypes.includes(String(m.movement_type || '').toLowerCase())).reduce((s,m)=>s+safeNum(m.quantity,0),0)
 const totalCoversReleased = movementAsset('cover').filter(m => releasedTypes.includes(String(m.movement_type || '').toLowerCase())).reduce((s,m)=>s+safeNum(m.quantity,0),0)
 const totalCoversCollected = movementAsset('cover').filter(m => collectedTypes.includes(String(m.movement_type || '').toLowerCase())).reduce((s,m)=>s+safeNum(m.quantity,0),0)
 const totalWithResellers = allRows.reduce((s,r)=>s+Math.max(0, safeNum(r.crateBalance,0)),0)
 const totalCoversWithResellers = allRows.reduce((s,r)=>s+Math.max(0, safeNum(r.coverBalance,0)),0)
 const resellersWithBalance = allRows.filter(r => safeNum(r.crateBalance,0) > 0 || safeNum(r.coverBalance,0) > 0).length
 const totalCompanyCrates = companyAsset('crate').reduce((s,m)=>s+getCompanyCrateSignedQty(m),0)
 const totalCompanyCovers = companyAsset('cover').reduce((s,m)=>s+getCompanyCrateSignedQty(m),0)
 const totalCompanyAdded = companyMovements.reduce((s,m)=>s+Math.max(0, getCompanyCrateSignedQty(m)),0)
 const totalCompanyDeducted = companyMovements.reduce((s,m)=>s+Math.abs(Math.min(0, getCompanyCrateSignedQty(m))),0)
 const availableCrates = totalCompanyCrates - totalWithResellers
 const availableCovers = totalCompanyCovers - totalCoversWithResellers
 return { rows, allRows, totalReleased, totalCollected, totalCoversReleased, totalCoversCollected, totalWithResellers, totalCoversWithResellers, resellersWithBalance, totalCompanyCrates, totalCompanyCovers, totalCompanyAdded, totalCompanyDeducted, availableCrates, availableCovers }
 }

 async function loadCrateMovements() {
 setCratesLoading(true)
 setCratesLoadError('')
 try {
 const { data, error } = await supabase
 .from('crate_movements')
 .select('*')
 .eq('is_deleted', false)
 .order('movement_date', { ascending:false })
 .order('created_at', { ascending:false })
 .limit(1000)
 if (error) throw error
 setCrateMovements(data || [])
 } catch (err) {
 console.warn('loadCrateMovements:', err)
 setCrateMovements([])
 setCratesLoadError('Crates table is not ready yet. Please run the Supabase setup SQL once.')
 } finally {
 setCratesLoading(false)
 }
 }

 async function saveCompanyCrateStockAdjustment() {
 const qtyInput = safeNum(companyCrateQty, 0)
 if (!companyCrateDate) { showToast('Please select crate stock date.','red'); return }
 if (qtyInput < 0) { showToast('Please enter a valid crate quantity.','red'); return }
 if (qtyInput <= 0) { showToast('Please enter crate quantity.','red'); return }

 const crateData = getCrateDashboardData()
 const assetType = companyCrateAssetType === 'cover' ? 'cover' : 'crate'
 const assetLabel = getCrateAssetLabel(assetType)
 const currentTotal = assetType === 'cover' ? safeNum(crateData.totalCompanyCovers, 0) : safeNum(crateData.totalCompanyCrates, 0)
 const action = String(companyCrateAction || 'add_purchased')
 const actionMap = {
 set_exact:`Set exact company ${assetLabel} count`,
 add_purchased:`Add newly purchased ${assetLabel}`,
 correction_increase:'Correction increase',
 deduct_damaged:`Deduct damaged ${assetLabel}`,
 deduct_lost:`Deduct lost ${assetLabel}`,
 correction_decrease:'Correction decrease'
 }

 let movementType = `company_${action}`
 let direction = ['deduct_damaged','deduct_lost','correction_decrease'].includes(action) ? 'out' : 'in'
 let quantity = qtyInput
 let stockNote = `${actionMap[action] || 'Company asset stock adjustment'}: ${qtyInput} ${assetLabel}.`

 if (action === 'set_exact') {
 const diff = qtyInput - currentTotal
 if (Math.abs(diff) < 0.0001) {
 showToast(`Company ${assetLabel} count is already set to this number.`,'green')
 return
 }
 quantity = Math.abs(diff)
 direction = diff > 0 ? 'in' : 'out'
 movementType = 'company_set_exact_adjustment'
 stockNote = `Set exact company ${assetLabel} count to ${qtyInput}. Previous count: ${currentTotal}. Adjustment difference: ${diff > 0 ? '+' : ''}${diff}.`
 }

 try {
 const payload = {
 movement_date:companyCrateDate,
 related_delivery_date:null,
 reseller_id:null,
 reseller_name:'Company Inventory',
 invoice_id:null,
 invoice_number:'',
 movement_type:movementType,
 direction,
 quantity,
 asset_type:assetType,
 dispatcher_name:'',
 driver_name:'',
 recorded_by:adminEmployee?.full_name || adminRole || 'Admin',
 notes:[stockNote, String(companyCrateNotes || '').trim()].filter(Boolean).join(' '),
 is_deleted:false
 }
 const { error } = await supabase.from('crate_movements').insert(payload)
 if (error) throw error
 await logAudit('COMPANY CRATE STOCK UPDATED', adminRole || 'Admin', 'Company Inventory', `${stockNote}${companyCrateNotes ? ' '+companyCrateNotes : ''}`)
 showToast(` Company ${assetLabel} stock updated!`)
 setCompanyCrateQty(''); setCompanyCrateNotes('')
 loadCrateMovements()
 } catch (err) {
 console.warn('saveCompanyCrateStockAdjustment:', err)
 showToast('Company crate stock update failed. Run the crate_movements SQL setup first.','red')
 }
 }

