 // Reseller Credit Warning / Admin Approval Guard
 // Rule: if a reseller has an unpaid/partial invoice after the 7-day grace period,
 // the app no longer blocks new orders/invoices. Instead, affected orders/invoices
 // flash red continually so admin can review the account before approval.
 function getInvoiceBalance(inv) {
 const balance = moneyRound(safeNum(inv?.total_amount, 0) - safeNum(inv?.paid_amount, 0))
 return isMoneySettled(balance)? 0: Math.max(0, balance)
 }

function getNormalizedInvoiceStatus(inv) {
const status = String(inv?.status || 'unpaid').toLowerCase()
if (['cancelled','voided'].includes(status)) return status
 const balance = getInvoiceBalance(inv)
 const paid = moneyRound(inv?.paid_amount || 0)
 if (paid > 0 && balance <= 0) return 'paid'
 if (paid > 0 && balance > 0) return 'partial'
 return status || 'unpaid'
 }


function getInvoicePaymentStatus(inv) {
const status = String(inv?.status || 'unpaid').toLowerCase()
if (['cancelled','voided'].includes(status)) return status
 const total = moneyRound(inv?.total_amount || 0)
 const paid = moneyRound(inv?.paid_amount || 0)
 const balance = getInvoiceBalance(inv)

 // Payment classification must be based on money, not only the saved status label.
 // This prevents fully paid invoices from staying in Partial and prevents unpaid/partial
 // invoices from appearing inside the Paid tab.
 if (total > 0 && balance <= 0) return 'paid'
 if (paid > 0 && balance > 0) return 'partial'
 if (balance > 0) return 'unpaid'
 return status === 'paid'? 'paid': 'unpaid'
 }

function invoiceMatchesFilter(inv, filter) {
const paymentStatus = getInvoicePaymentStatus(inv)
const savedStatus = String(inv?.status || 'unpaid').toLowerCase()
 const t2 = new Date(); t2.setDate(t2.getDate() + 1); const tS = t2.toISOString().slice(0, 10)

 if (filter === 'today') return inv.delivery_date === today
 if (filter === 'tomorrow') return inv.delivery_date === tS
 if (filter === 'upcoming') return inv.delivery_date > tS
if (filter === 'all') return savedStatus !== 'voided'

 if (filter === 'paid') return paymentStatus === 'paid'
 if (filter === 'partial') return paymentStatus === 'partial'
 if (filter === 'unpaid') return paymentStatus === 'unpaid'

 // Delivered tab remains a logistics/delivery view, but excludes fully paid invoices
 // so paid invoices only live in the Paid tab for collection review.
 if (filter === 'delivered') return savedStatus === 'delivered' && paymentStatus!== 'paid'

 // Active means invoices still needing action/collection.
if (filter === 'active') return paymentStatus!== 'paid' && !['cancelled','voided'].includes(savedStatus)

return paymentStatus!== 'paid' && !['cancelled','voided'].includes(savedStatus)
 }

 function getInvoiceDeliveryDate(inv) {
 return String(inv?.delivery_date || '').slice(0, 10)
 }

 function invoiceMatchesDayFilter(inv, dayFilter = invoiceDayFilter) {
 if (!dayFilter || dayFilter === 'all') return true
 return getInvoiceDeliveryDate(inv) === dayFilter
 }

 function normalizeInvoiceSearchValue(value) {
 return String(value || '')
 .toLowerCase()
 .normalize('NFKD')
 .replace(/[\u0300-\u036f]/g, '')
 .replace(/[.,]/g, ' ')
 .replace(/\s+/g, ' ')
 .trim()
 }

 function getInvoiceDateSearchAliases(value) {
 const dateKey = String(value || '').slice(0, 10)
 const parsed = parseLocalDate(dateKey)
 if (!parsed) return dateKey

 const year = parsed.getFullYear()
 const month = parsed.getMonth() + 1
 const day = parsed.getDate()
 const month2 = pad2(month)
 const day2 = pad2(day)
 const longMonth = parsed.toLocaleDateString('en-US', { month:'long' })
 const shortMonth = parsed.toLocaleDateString('en-US', { month:'short' })
 const weekday = parsed.toLocaleDateString('en-US', { weekday:'long' })

 return [
 dateKey,
 `${month2}/${day2}/${year}`,
 `${month}/${day}/${year}`,
 `${year}/${month2}/${day2}`,
 `${month2}-${day2}-${year}`,
 `${month}-${day}-${year}`,
 `${longMonth} ${day}, ${year}`,
 `${longMonth} ${day} ${year}`,
 `${shortMonth} ${day}, ${year}`,
 `${shortMonth} ${day} ${year}`,
 `${day} ${longMonth} ${year}`,
 `${day} ${shortMonth} ${year}`,
 `${longMonth} ${day}`,
 `${shortMonth} ${day}`,
 `${day} ${longMonth}`,
 `${day} ${shortMonth}`,
 `${weekday} ${longMonth} ${day} ${year}`,
 `${year}${month2}${day2}`
 ]
 .filter(Boolean)
 .join(' ')
 }

 function getInvoiceSearchHaystack(inv) {
 const reseller = resellers.find(r => String(r.id) === String(inv?.reseller_id)) || {}
 const deliveryDate = getInvoiceDeliveryDate(inv)
 const dueDate = String(inv?.due_date || '').slice(0, 10)

 return normalizeInvoiceSearchValue([
 inv?.invoice_number,
 inv?.reseller_name,
 inv?.customer_name,
 inv?.customer_address,
 inv?.customer_contact,
 inv?.customer_type,
 deliveryDate,
 getInvoiceDateSearchAliases(deliveryDate),
 dueDate,
 getInvoiceDateSearchAliases(dueDate),
 inv?.status,
 inv?.address,
 inv?.delivery_address,
 inv?.reseller_address,
 inv?.area,
 inv?.location,
 reseller?.name,
 reseller?.area,
 reseller?.address,
 reseller?.delivery_address,
 reseller?.location,
 reseller?.contact_person,
 reseller?.phone,
...(inv?.delivery_invoice_items || []).map(item => item?.variant_name)
 ]
.filter(Boolean)
.join(' '))
 }

 function invoiceMatchesSearch(inv, searchTerm = invoiceSearchTerm) {
 const term = normalizeInvoiceSearchValue(searchTerm)
 if (!term) return true
 return getInvoiceSearchHaystack(inv).includes(term)
 }

 function renderInvoiceSearchBox(title = 'Search All Invoices', note = 'Search by customer/reseller, invoice number, date, area, address, contact, or product.') {
 const active = !!normalizeInvoiceSearchValue(invoiceSearchTerm)
 const resultCount = deliveryInvoices.filter(inv => invoiceMatchesSearch(inv)).length
 return (
 <div style={{ background:'white', border:'1px solid #e8e8e8', borderRadius:'14px', padding:'12px', marginBottom:'12px', boxShadow:'0 1px 6px rgba(0,0,0,0.06)' }}>
 <label style={{...lblS, marginBottom:'6px' }}>{title}</label>
 <div style={{ display:'flex', gap:'8px', flexWrap:'wrap', alignItems:'center' }}>
 <input
 type="text"
 value={invoiceSearchTerm}
 onChange={e=>setInvoiceSearchTerm(e.target.value)}
 placeholder="Search invoice no., customer/reseller, date, address, contact, product..."
 style={{...inputStyle, marginBottom:0, flex:'1 1 260px', fontSize:'13px', border:'2px solid #f0f0f0' }}
 />
 {active && (
 <button
 type="button"
 onClick={()=>setInvoiceSearchTerm('')}
 style={{ background:'#fff5f5', color:'#ca1b1b', border:'1px solid #ca1b1b', borderRadius:'10px', padding:'10px 14px', cursor:'pointer', fontWeight:'800', fontSize:'12px' }}
 >
 CLEAR
 </button>
 )}
 </div>
 <p style={{ color:'#777', fontSize:'11px', margin:'8px 0 0', lineHeight:1.45 }}>
 {active ? `Showing ${resultCount} matching invoice(s) from all loaded invoices. Status/date filters may still narrow the list.` : note}
 </p>
 </div>
 )
 }

 function sortDeliveryInvoicesNewestFirst(a, b) {
 const dateCompare = getInvoiceDeliveryDate(b).localeCompare(getInvoiceDeliveryDate(a))
 if (dateCompare!== 0) return dateCompare

 const createdA = Date.parse(a?.created_at || a?.updated_at || '') || 0
 const createdB = Date.parse(b?.created_at || b?.updated_at || '') || 0
 if (createdA!== createdB) return createdB - createdA

 return String(b?.invoice_number || '').localeCompare(String(a?.invoice_number || ''))
 }

 function getDayFilteredInvoices(dayFilter = invoiceDayFilter) {
 return [...deliveryInvoices]
.filter(inv => invoiceMatchesDayFilter(inv, dayFilter))
.sort(sortDeliveryInvoicesNewestFirst)
 }

 function getVisibleDeliveryInvoices(filter = invoiceFilter, dayFilter = invoiceDayFilter) {
 const searchActive =!!normalizeInvoiceSearchValue(invoiceSearchTerm)
 const sourceInvoices = searchActive
? [...deliveryInvoices]
: getDayFilteredInvoices(dayFilter)

 return sourceInvoices
.filter(inv => invoiceMatchesFilter(inv, filter))
.filter(inv => invoiceMatchesSearch(inv))
.sort(sortDeliveryInvoicesNewestFirst)
 }

 function getInvoiceDayOptions() {
 // Include every delivery date loaded from Supabase. Historical invoices must
 // never disappear from the dropdown just because they are older than 31 days.
 const dates = new Set([today, getDateOffsetString(1)])

 deliveryInvoices.forEach(inv => {
 const dateKey = getInvoiceDeliveryDate(inv)
 if (dateKey && parseLocalDate(dateKey)) dates.add(dateKey)
 })

 getApprovedInvoiceDeletionRequests().forEach(request => {
  const dateKey = getInvoiceDeletionDeliveryDate(request)
  if (dateKey && parseLocalDate(dateKey)) dates.add(dateKey)
 })

 return Array.from(dates).sort((a, b) => b.localeCompare(a))
 }

 function formatInvoiceDayOption(dateKey) {
 if (dateKey === 'all') return 'All loaded dates'
 if (dateKey === today) return `Today ${dateKey}`
 if (dateKey === getDateOffsetString(1)) return `Tomorrow ${dateKey}`
 const parsed = parseLocalDate(dateKey)
 if (!parsed) return dateKey
 return `${parsed.toLocaleDateString('en-PH', { weekday:'short', month:'short', day:'2-digit', year:'numeric' })} ${dateKey}`
 }

 async function normalizePaidInvoiceRows(rows = []) {
 const normalized = (rows || []).map(inv => {
 const status = getNormalizedInvoiceStatus(inv)
 const paidDate = status === 'paid'? (inv.paid_date || today): inv.paid_date
 return status!== inv.status || paidDate!== inv.paid_date? {...inv, status, paid_date:paidDate }: inv
 })

 const stalePaid = normalized.filter(inv => String(inv.status || '').toLowerCase() === 'paid' && getInvoiceBalance(inv) <= 0)
 for (const inv of stalePaid) {
 const original = (rows || []).find(r => r.id === inv.id)
 if (!original || (String(original.status || '').toLowerCase() === 'paid' && original.paid_date)) continue
 const { error } = await supabase
.from('delivery_invoices')
.update({ status:'paid', paid_date:inv.paid_date || today, paid_amount:moneyRound(inv.paid_amount || inv.total_amount || 0) })
.eq('id', inv.id)
 if (error) console.warn('normalizePaidInvoiceRows:', error)
 }

 return normalized
 }

 function getInvoiceCreditHoldDate(inv) {
 if (inv?.due_date) return String(inv.due_date).slice(0, 10)
 const deliveryDate = parseLocalDate(inv?.delivery_date)
 if (!deliveryDate) return ''
 deliveryDate.setDate(deliveryDate.getDate() + RESELLER_CREDIT_GRACE_DAYS)
 return formatDateLocal(deliveryDate)
 }

 function getInvoiceCreditAgeDays(inv, asOfDate = today) {
 const delivered = parseLocalDate(inv?.delivery_date)
 const asOf = parseLocalDate(asOfDate)
 if (!delivered ||!asOf) return 0
 return Math.max(0, Math.floor((asOf.getTime() - delivered.getTime()) / (1000 * 60 * 60 * 24)))
 }

function isInvoiceCreditBlocked(inv, asOfDate = today) {
const status = String(inv?.status || '').toLowerCase()
if (!inv || ['paid','cancelled','voided'].includes(status)) return false
 if (getInvoiceBalance(inv) <= 0) return false
 const holdDate = getInvoiceCreditHoldDate(inv)
 if (!holdDate) return false
 return holdDate <= asOfDate
 }

 function buildResellerCreditStatus(resellerId, invoiceRows = deliveryInvoices, asOfDate = today) {
 const relatedIds = getResellerBranchIds(resellerId).map(String)
 const related = (invoiceRows || []).filter(inv => relatedIds.includes(String(inv.reseller_id || '')))
const outstanding = related
.filter(inv => getInvoiceBalance(inv) > 0 &&!['paid','cancelled','voided'].includes(String(inv.status || '').toLowerCase()))
.map(inv => ({
...inv,
 balance_amount: getInvoiceBalance(inv),
 hold_date: getInvoiceCreditHoldDate(inv),
 credit_age_days: getInvoiceCreditAgeDays(inv, asOfDate),
 is_credit_blocked: isInvoiceCreditBlocked(inv, asOfDate)
 }))
.sort((a, b) => String(a.delivery_date || '').localeCompare(String(b.delivery_date || '')))

 const blockedInvoices = outstanding.filter(inv => inv.is_credit_blocked)
 const totalBalance = outstanding.reduce((sum, inv) => sum + safeNum(inv.balance_amount, 0), 0)
 const blockedBalance = blockedInvoices.reduce((sum, inv) => sum + safeNum(inv.balance_amount, 0), 0)
 const oldest = blockedInvoices[0] || outstanding[0] || null

 return {
 resellerId,
 blocked: blockedInvoices.length > 0,
 outstanding,
 blockedInvoices,
 totalBalance,
 blockedBalance,
 oldest,
 message: blockedInvoices.length > 0
? `Credit warning: ${blockedInvoices.length} invoice(s) unpaid beyond the ${RESELLER_CREDIT_GRACE_DAYS}-day grace period. Orders/invoices are still allowed, but admin should collect or review ${php(blockedBalance)} before approval.`
: outstanding.length > 0
? `Open balance: ${php(totalBalance)}. Please settle within ${RESELLER_CREDIT_GRACE_DAYS} days after delivery to keep continuous delivery active.`
: 'Clear account. Orders and deliveries allowed.'
 }
 }

 function getResellerCreditBlockInfo(resellerId) {
 return buildResellerCreditStatus(resellerId, deliveryInvoices, today)
 }

 async function checkResellerCreditBlockFresh(resellerId) {
 if (!resellerId) return buildResellerCreditStatus('', [], today)
 const branchIds = getResellerBranchIds(resellerId)
 let query = supabase
.from('delivery_invoices')
.select('id, invoice_number, reseller_id, reseller_name, delivery_date, due_date, total_amount, paid_amount, status')
.order('delivery_date', { ascending:true })

 query = branchIds.length > 1? query.in('reseller_id', branchIds): query.eq('reseller_id', resellerId)
 const { data, error } = await query

 if (error) {
 console.warn('checkResellerCreditBlockFresh:', error)
 return getResellerCreditBlockInfo(resellerId)
 }

 return buildResellerCreditStatus(resellerId, data || [], today)
 }

 function isOptionalSupabaseObjectMissing(error) {
 const msg = String(error?.message || error || '').toLowerCase()
 return msg.includes('does not exist') || msg.includes('schema cache') || msg.includes('could not find') || msg.includes('column')
 }

 function isResellerPortalReturnRecord(row) {
 return String(row?.recorded_by || '').toLowerCase().includes('reseller portal')
 }

 function getInvoiceReturnRecordsForPrint(invoice) {
 const allReturns = Array.isArray(invoice?.reseller_returns) ? invoice.reseller_returns : []
 if (!allReturns.length) return []
 const adminEncoded = allReturns.filter(row => !isResellerPortalReturnRecord(row))
 // Admin/owner/driver/settlement entry is treated as final. Reseller portal entry is used only when no admin return exists yet.
 return adminEncoded.length ? adminEncoded : allReturns
 }

 function getInvoiceReturnLookups(invoice) {
 const byVariantId = {}
 const byName = {}
 getInvoiceReturnRecordsForPrint(invoice).forEach(ret => {
 ;(ret.reseller_return_items || []).forEach(item => {
 const qty = safeNum(item.returned_quantity ?? item.returned_qty ?? item.quantity ?? item.qty, 0)
 if (!qty) return
 const variantId = String(item.variant_id || '').trim()
 const nameKey = normalizeDonutVariantName(item.variant_name || item.product_name || item.item_name || item.name || '')
 if (variantId) byVariantId[variantId] = safeNum(byVariantId[variantId], 0) + qty
 if (nameKey) byName[nameKey] = safeNum(byName[nameKey], 0) + qty
 })
 })
 return { byVariantId, byName }
 }

 function getInvoiceItemDeliveredQty(item = {}) {
 return Math.max(0, safeNum(item.delivered_quantity ?? item.actual_quantity ?? item.quantity, 0))
 }

 function getInvoiceItemPrice(item = {}) {
 return moneyRound(item.reseller_price ?? item.unit_price ?? item.price ?? item.selling_price ?? 0)
 }

 function getDeliveryInvoiceCustomerType(invoice = {}) {
 const explicitType = String(invoice?.customer_type || '').trim().toLowerCase().replace(/[\s-]+/g, '_')
 if (explicitType === 'non_reseller' || explicitType === 'nonreseller') return 'non_reseller'
 if (explicitType === 'reseller') return 'reseller'
 if (invoice?.reseller_id) return 'reseller'
 const notes = String(invoice?.notes || '').toLowerCase()
 if (notes.includes('non-reseller invoice') || notes.includes('non reseller invoice')) return 'non_reseller'
 return 'non_reseller'
 }

 function getDeliveryInvoiceDiscountPct(invoice = {}) {
 const customerType = getDeliveryInvoiceCustomerType(invoice)
 const storedDiscount = safeNum(invoice?.discount_pct, NaN)
 if (Number.isFinite(storedDiscount)) return storedDiscount
 return customerType === 'reseller' ? 20 : 0
 }

 function getDeliveryInvoiceEditUnitPrice(invoice = {}, retailPrice = 0) {
 const discountPct = getDeliveryInvoiceDiscountPct(invoice)
 return moneyRound(safeNum(retailPrice, 0) * (1 - discountPct / 100))
 }

 function getInvoiceItemGrossAmount(item = {}) {
 const stored = safeNum(item.total_price ?? item.amount ?? item.line_total, NaN)
 if (Number.isFinite(stored)) return moneyRound(stored)
 return moneyRound(getInvoiceItemDeliveredQty(item) * getInvoiceItemPrice(item))
 }

 function getInvoiceItemUnsoldQuantity(invoice, item = {}) {
 const direct = safeNum(item.unsold_quantity ?? item.returned_quantity ?? item.returns_qty ?? item.returned_qty, NaN)
 if (Number.isFinite(direct) && direct > 0) return Math.min(getInvoiceItemDeliveredQty(item), direct)
 const lookups = getInvoiceReturnLookups(invoice)
 const variantId = String(item.variant_id || '').trim()
 if (variantId && Object.prototype.hasOwnProperty.call(lookups.byVariantId, variantId)) {
 return Math.min(getInvoiceItemDeliveredQty(item), safeNum(lookups.byVariantId[variantId], 0))
 }
 const nameKey = normalizeDonutVariantName(item.variant_name || item.product_name || item.name || '')
 if (nameKey && Object.prototype.hasOwnProperty.call(lookups.byName, nameKey)) {
 return Math.min(getInvoiceItemDeliveredQty(item), safeNum(lookups.byName[nameKey], 0))
 }
 return 0
 }

 function attachUnsoldQuantitiesToInvoice(invoice) {
 const inv = invoice || {}
 const items = Array.isArray(inv.delivery_invoice_items) ? inv.delivery_invoice_items : []
 return {
 ...inv,
 delivery_invoice_items:items.map(item => ({
 ...item,
 unsold_quantity:getInvoiceItemUnsoldQuantity(inv, item)
 }))
 }
 }

 function mergeDeliveryInvoicesWithReturns(invoiceRows = [], returnRows = []) {
 const returnsByInvoiceId = {}
 ;(returnRows || []).forEach(row => {
 const key = String(row.invoice_id || '')
 if (!key) return
 if (!returnsByInvoiceId[key]) returnsByInvoiceId[key] = []
 returnsByInvoiceId[key].push(row)
 })
 return (invoiceRows || []).map(inv => attachUnsoldQuantitiesToInvoice({
 ...inv,
 reseller_returns:returnsByInvoiceId[String(inv.id || '')] || inv.reseller_returns || []
 }))
 }

 async function attachReturnsToDeliveryInvoices(invoiceRows = []) {
 const rows = Array.isArray(invoiceRows) ? invoiceRows : []
 const ids = rows.map(inv => inv?.id).filter(Boolean)
 if (!ids.length) return rows.map(attachUnsoldQuantitiesToInvoice)
 try {
 const { data, error } = await supabase
 .from('reseller_returns')
 .select('*, reseller_return_items(*)')
 .in('invoice_id', ids)
 if (error) {
 if (!isOptionalSupabaseObjectMissing(error)) console.warn('attachReturnsToDeliveryInvoices:', error)
 return rows.map(attachUnsoldQuantitiesToInvoice)
 }
 return mergeDeliveryInvoicesWithReturns(rows, data || [])
 } catch(e) {
 console.warn('attachReturnsToDeliveryInvoices:', e)
 return rows.map(attachUnsoldQuantitiesToInvoice)
 }
 }

 function getInvoiceViewItemRows(invoice) {
 const items = Array.isArray(invoice?.delivery_invoice_items) ? invoice.delivery_invoice_items : []
 return items.map(item => {
 const deliveredQty = getInvoiceItemDeliveredQty(item)
 const unsoldQty = Math.min(deliveredQty, getInvoiceItemUnsoldQuantity(invoice, item))
 const soldQty = Math.max(0, deliveredQty - unsoldQty)
 const price = getInvoiceItemPrice(item)
 const grossAmount = moneyRound(deliveredQty * price)
 const returnsCredit = moneyRound(unsoldQty * price)
 const netAmount = moneyRound(soldQty * price)
 return {
 ...item,
 deliveredQty,
 unsoldQty,
 soldQty,
 price,
 grossAmount,
 returnsCredit,
 netAmount
 }
 })
 }


 function getDaysUntilLocal(targetDate, asOfDate = today) {
 const target = parseLocalDate(targetDate)
 const asOf = parseLocalDate(asOfDate)
 if (!target ||!asOf) return null
 return Math.floor((target.getTime() - asOf.getTime()) / (1000 * 60 * 60 * 24))
 }

 function getPayableDueDate(row) {
 return row?.due_date || row?.check_date || row?.payable_date || row?.expense_date || today
 }

 function normalizeCompanyPayable(row) {
 const dueDate = getPayableDueDate(row)
 const daysUntilDue = getDaysUntilLocal(dueDate, today)
 const amount = safeNum(row?.amount, 0)
 const status = String(row?.status || 'scheduled').toLowerCase()
 let urgency = 'open'
 if (daysUntilDue!== null && daysUntilDue < 0) urgency = 'overdue'
 else if (daysUntilDue === 0) urgency = 'due_today'
 else if (daysUntilDue!== null && daysUntilDue <= 3) urgency = 'approaching'

 return {
...row,
 source:'company_payables',
 due_date_effective:dueDate,
 days_until_due:daysUntilDue,
 balance_amount:amount,
 urgency,
 status_normalized:status,
 display_payee:row?.payee_name || row?.supplier_name || row?.category || 'Company payable',
 display_category:row?.category || row?.payment_type || 'Payable'
 }
 }

 function normalizePendingExpenseAsPayable(exp) {
 const dueDate = exp?.expense_date || today
 const daysUntilDue = getDaysUntilLocal(dueDate, today)
 let urgency = 'open'
 if (daysUntilDue!== null && daysUntilDue < 0) urgency = 'overdue'
 else if (daysUntilDue === 0) urgency = 'due_today'
 else if (daysUntilDue!== null && daysUntilDue <= 3) urgency = 'approaching'
 return {
...exp,
 source:'daily_expenses',
 due_date_effective:dueDate,
 days_until_due:daysUntilDue,
 balance_amount:safeNum(exp?.amount, 0),
 urgency,
 status_normalized:String(exp?.status || 'pending').toLowerCase(),
 display_payee:exp?.description || exp?.category || 'Pending expense',
 display_category:exp?.category || 'Expense Approval'
 }
 }

 function getOwnerPaymentDeadlineAlerts(payableRows = companyPayables, expenseRows = dailyExpenses, asOfDate = today) {
 const openCompanyPayables = (payableRows || [])
.filter(row =>!['paid','cancelled','void','rejected'].includes(String(row?.status || 'scheduled').toLowerCase()))
.filter(row => safeNum(row?.amount, 0) > 0)
.map(row => {
 const dueDate = getPayableDueDate(row)
 const daysUntilDue = getDaysUntilLocal(dueDate, asOfDate)
 let urgency = 'open'
 if (daysUntilDue!== null && daysUntilDue < 0) urgency = 'overdue'
 else if (daysUntilDue === 0) urgency = 'due_today'
 else if (daysUntilDue!== null && daysUntilDue <= 3) urgency = 'approaching'
 return {...normalizeCompanyPayable(row), due_date_effective:dueDate, days_until_due:daysUntilDue, urgency }
 })

 const pendingExpenseRows = (expenseRows || [])
.filter(exp => String(exp?.status || '').toLowerCase() === 'pending')
.filter(exp => safeNum(exp?.amount, 0) > 0)
.map(normalizePendingExpenseAsPayable)

 const openRows = [...openCompanyPayables,...pendingExpenseRows].sort((a, b) => {
 const da = a.days_until_due?? 99999
 const db = b.days_until_due?? 99999
 if (da!== db) return da - db
 return safeNum(b.balance_amount, 0) - safeNum(a.balance_amount, 0)
 })

 const warningRows = openRows.filter(r => ['overdue','due_today','approaching'].includes(r.urgency))
 const overdueRows = warningRows.filter(r => r.urgency === 'overdue')
 const dueTodayRows = warningRows.filter(r => r.urgency === 'due_today')
 const approachingRows = warningRows.filter(r => r.urgency === 'approaching')
 const totalOpenBalance = openRows.reduce((sum, r) => sum + safeNum(r.balance_amount, 0), 0)
 const warningBalance = warningRows.reduce((sum, r) => sum + safeNum(r.balance_amount, 0), 0)

 return {
 openRows,
 warningRows,
 overdueRows,
 dueTodayRows,
 approachingRows,
 totalOpenBalance,
 warningBalance,
 warningCount: warningRows.length,
 overdueBalance: overdueRows.reduce((sum, r) => sum + safeNum(r.balance_amount, 0), 0),
 dueTodayBalance: dueTodayRows.reduce((sum, r) => sum + safeNum(r.balance_amount, 0), 0),
 approachingBalance: approachingRows.reduce((sum, r) => sum + safeNum(r.balance_amount, 0), 0)
 }
 }

 function getPaymentDeadlineLabel(row) {
  if (row?.days_until_due === null || row?.days_until_due === undefined) return 'No due date'
  if (row.days_until_due < 0) return `${Math.abs(row.days_until_due)} day(s) overdue`
  if (row.days_until_due === 0) return 'Due today'
  if (row.days_until_due === 1) return 'Due tomorrow'
  return `Due in ${row.days_until_due} days`
}

  async function autoMarkTodayDelivered() {
 try {
 const { data: todayInvs } = await supabase.from('delivery_invoices')
.select('id, invoice_number, reseller_name, status').eq('delivery_date', today)
 if (!todayInvs) return
for (const inv of todayInvs.filter(i => !['delivered','paid','cancelled','voided'].includes(String(i.status || '').toLowerCase()))) {
 await supabase.from('delivery_invoices').update({ status:'delivered' }).eq('id', inv.id)
 await logAudit('AUTO-DELIVERED', 'System', inv.reseller_name, inv.invoice_number + ' auto-marked delivered')
 }
 } catch(e) { console.warn('autoMarkTodayDelivered:', e) }
 }
 async function fetchAllDeliveryInvoiceRows(selectClause) {
 const pageSize = 1000
 const maxPages = 100
 const rowsById = new Map()
 let from = 0
 let totalCount = null

 for (let page = 0; page < maxPages; page++) {
 const { data, error, count } = await supabase
 .from('delivery_invoices')
 .select(selectClause, { count:'exact' })
 .order('delivery_date', { ascending:false })
 .order('created_at', { ascending:false })
 .order('id', { ascending:false })
 .range(from, from + pageSize - 1)

 if (error) return { data:[], error }

 const rows = data || []
 rows.forEach((row, index) => {
 const key = row?.id? String(row.id): `row-${from + index}`
 rowsById.set(key, row)
 })

 if (totalCount === null && Number.isFinite(count)) totalCount = count
 if (rows.length === 0) break

 from += rows.length
 if (totalCount !== null && from >= totalCount) break

 if (page === maxPages - 1) {
 console.warn(`Delivery invoice loading reached the safety limit of ${maxPages * pageSize} rows.`)
 }
 }

 return { data:Array.from(rowsById.values()), error:null }
 }

 async function loadDeliveryInvoices() {
 setInvoicesLoading(true)
 try {
 await autoMarkTodayDelivered()

 // Load every saved invoice in pages. The previous .limit(500) silently hid
 // older records once the database exceeded 500 invoices.
 const withItems = await fetchAllDeliveryInvoiceRows('*, delivery_invoice_items(*)')
if (!withItems.error) {
const normalized = await normalizePaidInvoiceRows((withItems.data || []).filter(isSalesSummaryInvoiceCounted))
 const withReturns = await attachReturnsToDeliveryInvoices(normalized)
 setDeliveryInvoices(withReturns.sort(sortDeliveryInvoicesNewestFirst))
 return
 }

 console.warn('delivery_invoices with items failed, trying basic invoice list:', withItems.error)
 const basic = await fetchAllDeliveryInvoiceRows('*')
 if (basic.error) {
 console.warn('delivery_invoices basic query failed:', basic.error)
 setDeliveryInvoices([])
 return
 }

const normalizedBasic = await normalizePaidInvoiceRows((basic.data || []).filter(isSalesSummaryInvoiceCounted))
 const basicWithReturns = await attachReturnsToDeliveryInvoices(normalizedBasic)
 setDeliveryInvoices(basicWithReturns.sort(sortDeliveryInvoicesNewestFirst))
 } catch(e) {
 console.warn('loadDeliveryInvoices:', e)
 setDeliveryInvoices([])
 } finally {
 setInvoicesLoading(false)
 }
 }

 function getNextMonthStart(monthKey) {
 const clean = String(monthKey || today.slice(0,7)).slice(0, 7)
 const [year, month] = clean.split('-').map(Number)
 const d = new Date(year || new Date().getFullYear(), (month || 1), 1)
 d.setMinutes(d.getMinutes() - d.getTimezoneOffset())
 return d.toISOString().slice(0, 10)
 }

 function isOnlinePaymentMethod(method) {
 const m = String(method || '').trim().toLowerCase()
 if (!m) return false
 if (m === 'cash') return false
 return ONLINE_PAYMENT_METHODS.map(x=>String(x).toLowerCase()).includes(m) || m.includes('gcash') || m.includes('maya') || m.includes('bank') || m.includes('online') || m.includes('check')
 }

