 async function createDeliveryInvoice() {
 const customerType = invoiceCustomerType === 'non_reseller' ? 'non_reseller' : 'reseller'
 const discountPercent = safeNum(invoiceDiscountPct, customerType === 'reseller' ? 20 : 0)

 if (!invoiceDate) { showToast('Please select a delivery date.','red'); return }

 if (customerType === 'reseller' && !invoiceResellerId) {
 showToast('Please select a reseller.','red')
 return
 }

 if (customerType === 'non_reseller' && !String(invoiceCustomerName || '').trim()) {
 showToast('Please enter the customer name.','red')
 return
 }

 const validItems = invoiceItems.filter(i => i.variant_id && Number(i.quantity) > 0)
 if (validItems.length === 0) { showToast('Please add at least one item with quantity.','red'); return }

 if (customerType === 'reseller') {
 const visibleCreditStatus = getResellerCreditBlockInfo(invoiceResellerId)
 if (visibleCreditStatus.blocked) {
 showToast(`Credit warning only. Invoice creation is allowed, but review this reseller before approval/dispatch. ${visibleCreditStatus.message}`, 'red')
 }
 }

 setSavingInvoice(true)
 try {
 const reseller = customerType === 'reseller' ? resellers.find(r => r.id === invoiceResellerId) : null

 if (customerType === 'reseller') {
 // Manual invoice creation must be checked against the actual selected reseller/branch only.
 // Do not use the copy-template branch, parent account, or sibling branches for duplicate blocking.
 const duplicateCheck = await checkSameDayInvoiceForExactBranch(invoiceResellerId, invoiceDate, { resellerName:reseller?.name || '' })
 if (duplicateCheck.blocked) {
 showToast(duplicateCheck.message, 'red')
 await logAudit('INVOICE CREATE BLOCKED - EXACT BRANCH DUPLICATE', adminRole, reseller?.name || '', duplicateCheck.message)
 setSavingInvoice(false)
 return
 }
 }

 let freshCreditStatus = null
 if (customerType === 'reseller') {
 freshCreditStatus = await checkResellerCreditBlockFresh(invoiceResellerId)
 if (freshCreditStatus.blocked) {
 showToast(`Credit warning for ${reseller?.name || 'this reseller'}. Invoice will still be created, but admin should review before dispatch. ${freshCreditStatus.message}`, 'red')
 await logAudit('INVOICE CREATED WITH CREDIT WARNING', adminRole, reseller?.name || '', freshCreditStatus.message)
 }
 }

 const invoiceNum = `INV-${invoiceDate.replace(/-/g,'')}-${Math.floor(1000+Math.random()*9000)}`
 const dueDate = new Date(invoiceDate)
 dueDate.setDate(dueDate.getDate() + (customerType === 'reseller' ? RESELLER_CREDIT_GRACE_DAYS : 0))
 const dueDateStr = dueDate.toISOString().slice(0,10)

 const lineItems = validItems.map(i => {
 const variant = donutVariants.find(v => v.id === i.variant_id)
 const retailPrice = safeNum(variant?.selling_price ?? i.retail_price, 0)
 const invoicePrice = moneyRound(retailPrice * (1 - discountPercent / 100))
 return {
 ...i,
 retail_price:retailPrice,
 reseller_price:invoicePrice,
 total_price:moneyRound(invoicePrice * Number(i.quantity || 0))
 }
 })

 const subtotal = moneyRound(lineItems.reduce((s,i) => s + safeNum(i.total_price, 0), 0))
 const customerName = customerType === 'reseller' ? (reseller?.name || '') : String(invoiceCustomerName || '').trim()
 const customerAddress = customerType === 'reseller' ? (reseller?.address || reseller?.area || '') : String(invoiceCustomerAddress || '').trim()
 const customerContact = customerType === 'reseller' ? (reseller?.phone || '') : String(invoiceCustomerContact || '').trim()
 const baseNotes = invoiceNotes || ''
 const nonResellerNote = customerType === 'non_reseller'
 ? `Non-reseller invoice | Customer: ${customerName}${customerContact ? ' | Contact: ' + customerContact : ''}${customerAddress ? ' | Address: ' + customerAddress : ''}`
 : ''
 const finalNotes = [baseNotes, nonResellerNote].filter(Boolean).join(' | ') || null

 const invoicePayload = {
 invoice_number:invoiceNum,
 reseller_id:customerType === 'reseller' ? invoiceResellerId : null,
 reseller_name:customerName,
 delivery_date:invoiceDate,
 due_date:dueDateStr,
 subtotal,
 discount_pct:discountPercent,
 total_amount:subtotal,
 status:'unpaid',
 notes:finalNotes,
 created_by:currentAdminLabel,
 prepared_by:invoicePreparedBy||null,
 dispatched_by:invoiceDispatchedBy||null,
 crates_used:Number(invoiceCrates||0),
 customer_type:customerType,
 customer_name:customerName,
 customer_address:customerAddress || null,
 customer_contact:customerContact || null,
 container_type:invoiceContainerType || 'Crates'
 }

 let { data:inv, error:invErr } = await supabase.from('delivery_invoices').insert(invoicePayload).select().single()

 if (invErr && String(invErr.message || '').toLowerCase().includes('column')) {
 const fallbackPayload = {...invoicePayload}
 delete fallbackPayload.customer_type
 delete fallbackPayload.customer_name
 delete fallbackPayload.customer_address
 delete fallbackPayload.customer_contact
 delete fallbackPayload.container_type
 ;({ data:inv, error:invErr } = await supabase.from('delivery_invoices').insert(fallbackPayload).select().single())
 }

 if (invErr) throw invErr

 const itemRows = lineItems.map(i => ({
 invoice_id:inv.id,
 variant_id:i.variant_id,
 variant_name:i.variant_name,
 retail_price:i.retail_price,
 reseller_price:i.reseller_price,
 quantity:Number(i.quantity),
 total_price:i.total_price
 }))
 const { error:itemErr } = await supabase.from('delivery_invoice_items').insert(itemRows)
 if (itemErr) throw itemErr

 await logAudit('INVOICE CREATED', adminRole, customerName, `${invoiceNum} ${php(subtotal)} ${discountPercent}% discount ${customerType}`)
 showToast(`Invoice ${invoiceNum} created!`)
 setShowCreateInvoice(false)
 setInvoiceCustomerType('reseller')
 setInvoiceDiscountPct('20')
 setInvoiceResellerId('')
 setInvoiceCustomerName('')
 setInvoiceCustomerAddress('')
 setInvoiceCustomerContact('')
 setInvoiceContainerType('Crates')
 setInvoiceItems([])
 setInvoiceNotes('')
 setInvoicePreparedBy('')
 setInvoiceDispatchedBy('')
 setInvoiceCrates('')
 loadDeliveryInvoices()
 } catch(err) { showToast('Failed: '+err.message,'red') }
 setSavingInvoice(false)
 }
 async function saveInvoiceEdit() {
 if (!editingInvoice) return
 const cutoffStatus = getOrderCutoffStatus(editingInvoice.delivery_date)
 if (cutoffStatus.locked) {
 showToast(` Invoice editing is locked for tomorrow's delivery after ${ORDER_CUTOFF_LABEL} PH time.`, 'red')
 await logAudit('INVOICE EDIT BLOCKED - ORDER CUT-OFF', adminRole, editingInvoice.reseller_name || '', `${editingInvoice.invoice_number || ''} ${cutoffStatus.message}`)
 return
 }
 const validItems = editInvoiceItems.filter(i => i.variant_id && Number(i.quantity) > 0)
 if (validItems.length === 0) { showToast(' Please add at least one item.','red'); return }
 setSavingEditInvoice(true)
 try {
 // Recalculate totals using the selected invoice discount.
 // Existing invoices keep their stored discount until the user changes it in Edit Invoice.
 const discountPercent = getDeliveryInvoiceDiscountPct(editingInvoice)
 const lineItems = validItems.map(i => {
 const variant = donutVariants.find(v => v.id === i.variant_id)
 const retailPrice = safeNum(variant?.selling_price ?? i.retail_price, 0)
 const invoicePrice = getDeliveryInvoiceEditUnitPrice(editingInvoice, retailPrice)
 return {...i, retail_price:retailPrice, reseller_price:invoicePrice, total_price:moneyRound(invoicePrice * Number(i.quantity || 0)) }
 })
 const subtotal = moneyRound(lineItems.reduce((s,i) => s + safeNum(i.total_price, 0), 0))
 // Update invoice header
 await supabase.from('delivery_invoices').update({
 subtotal, total_amount:subtotal, discount_pct:discountPercent,
 notes:editingInvoice.notes||null,
 prepared_by:editingInvoice.prepared_by||null,
 dispatched_by:editingInvoice.dispatched_by||null,
 crates_used:Number(editingInvoice.crates_used||0)
 }).eq('id', editingInvoice.id)
 // Replace line items
 await supabase.from('delivery_invoice_items').delete().eq('invoice_id', editingInvoice.id)
 await supabase.from('delivery_invoice_items').insert(lineItems.map(i => ({
 invoice_id:editingInvoice.id, variant_id:i.variant_id, variant_name:i.variant_name,
 retail_price:i.retail_price, reseller_price:i.reseller_price,
 quantity:Number(i.quantity), total_price:i.total_price
 })))
 await logAudit('INVOICE EDITED', adminRole, editingInvoice.reseller_name, `${editingInvoice.invoice_number} updated to ${php(subtotal)}`)
 showToast(` Invoice updated new total: ${php(subtotal)}`)
 setEditingInvoice(null); setEditInvoiceItems([])
 loadDeliveryInvoices()
 } catch(err) { showToast(' Failed: '+err.message,'red') }
 setSavingEditInvoice(false)
 }
 function getInvoiceDeletionReasonLabel(value) {
  return INVOICE_DELETION_REASON_OPTIONS.find(([key]) => key === value)?.[1] || String(value || '').replace(/_/g, ' ') || 'Not specified'
 }

 function getPendingInvoiceDeletionRequest(invoiceId) {
  return (invoiceDeletionRequests || []).find(request => request.invoice_id === invoiceId && request.status === 'pending') || null
 }

 function getApprovedInvoiceDeletionRequests() {
  return (invoiceDeletionRequests || []).filter(request => request.status === 'approved' && ['voided','deleted'].includes(String(request.result_action || '').toLowerCase()))
 }

 function getInvoiceDeletionDeliveryDate(request) {
  return String(request?.invoice_snapshot?.invoice?.delivery_date || '').slice(0, 10)
 }

 function invoiceDeletionRequestMatchesSearch(request, searchTerm = invoiceSearchTerm) {
  const term = normalizeInvoiceSearchValue(searchTerm)
  if (!term) return true
  const invoice = request?.invoice_snapshot?.invoice || {}
  const items = Array.isArray(request?.invoice_snapshot?.items) ? request.invoice_snapshot.items : []
  return normalizeInvoiceSearchValue([
   request?.invoice_number,
   request?.reseller_name,
   request?.requested_by_name,
   request?.reviewed_by_name,
   request?.reason_detail,
   request?.result_action,
   request?.result_summary,
   getInvoiceDeletionDeliveryDate(request),
   invoice?.customer_name,
   invoice?.customer_address,
   invoice?.delivery_address,
   invoice?.contact_number,
   ...items.map(item => item?.variant_name)
  ].filter(Boolean).join(' ')).includes(term)
 }

 function getVisibleApprovedInvoiceDeletionRequests(dayFilter = invoiceDayFilter) {
  const searchActive = !!normalizeInvoiceSearchValue(invoiceSearchTerm)
  return getApprovedInvoiceDeletionRequests()
  .filter(request => searchActive || dayFilter === 'all' || getInvoiceDeletionDeliveryDate(request) === dayFilter)
  .filter(request => invoiceDeletionRequestMatchesSearch(request))
  .sort((a, b) => String(b.reviewed_at || b.updated_at || '').localeCompare(String(a.reviewed_at || a.updated_at || '')))
 }

 async function loadInvoiceDeletionAccess(options = {}) {
  try {
   const { data, error } = await supabase.rpc('get_invoice_deletion_access')
   if (error) throw error
   const nextAccess = {
    can_request:!!data?.can_request,
    can_review:!!data?.can_review,
    admin_user_id:data?.admin_user_id || null,
    admin_name:data?.admin_name || ''
   }
   setInvoiceDeletionAccess(nextAccess)
   return nextAccess
  } catch (error) {
   if (!options.silent) console.warn('loadInvoiceDeletionAccess:', error?.message || error)
   const noAccess = { can_request:false, can_review:false, admin_user_id:null, admin_name:'' }
   setInvoiceDeletionAccess(noAccess)
   return noAccess
  }
 }

 async function loadInvoiceDeletionRequests(options = {}) {
  if (!options.silent) setInvoiceDeletionRequestsLoading(true)
  try {
   const { data, error } = await supabase
   .from('invoice_deletion_requests')
   .select('*')
   .order('requested_at', { ascending:false })
   .limit(100)
   if (error) throw error
   setInvoiceDeletionRequests(data || [])
   return data || []
  } catch (error) {
   if (!options.silent) console.warn('loadInvoiceDeletionRequests:', error?.message || error)
   setInvoiceDeletionRequests([])
   return []
  } finally {
   if (!options.silent) setInvoiceDeletionRequestsLoading(false)
  }
 }

 function openInvoiceDeletionCenter() {
  setActiveTab('sales')
  setSalesView('deliveries')
  setDeliveriesSubTab('operations')
  setSidebarOpen(false)
  setShowNotifications(false)
  void loadInvoiceDeletionAccess({ silent:true })
  void loadInvoiceDeletionRequests({ silent:true })
  window.setTimeout(() => {
   document.getElementById('invoice-deletion-approval-center')?.scrollIntoView({ behavior:'smooth', block:'start' })
  }, 180)
 }

 function beginInvoiceDeletionRequest(invoice) {
  if (!invoice?.id) { showToast('Invalid invoice selected.', 'red'); return }
  if (!invoiceDeletionAccess.can_request) {
   showToast('This account is not authorized to request invoice deletion.', 'red')
   return
  }
  const pending = getPendingInvoiceDeletionRequest(invoice.id)
  if (pending) {
   showToast(`Deletion request for ${invoice.invoice_number} is already waiting for owner approval.`, 'red')
   openInvoiceDeletionCenter()
   return
  }
  setRequestingInvoiceDeletion(invoice)
  setInvoiceDeletionReasonCategory('')
  setInvoiceDeletionReasonDetail('')
 }

 async function submitInvoiceDeletionRequest() {
  const invoice = requestingInvoiceDeletion
  const reasonCategory = invoiceDeletionReasonCategory
  const reasonDetail = invoiceDeletionReasonDetail.trim()
  if (!invoice?.id) { showToast('Select an invoice first.', 'red'); return }
  if (!reasonCategory) { showToast('Select the reason for requesting deletion.', 'red'); return }
  if (reasonDetail.length < 10) { showToast('Enter a detailed explanation with at least 10 characters.', 'red'); return }

  setInvoiceDeletionSubmitting(true)
  try {
   const { data, error } = await supabase.rpc('request_invoice_deletion', {
    p_invoice_id:invoice.id,
    p_reason_category:reasonCategory,
    p_reason_detail:reasonDetail
   })
   if (error) throw error
   setRequestingInvoiceDeletion(null)
   setInvoiceDeletionReasonCategory('')
   setInvoiceDeletionReasonDetail('')
   await Promise.all([loadInvoiceDeletionRequests({ silent:true }), loadNotifications()])
   showToast(data?.message || `Deletion request for ${invoice.invoice_number} sent to the owner.`)
   window.setTimeout(() => document.getElementById('invoice-deletion-approval-center')?.scrollIntoView({ behavior:'smooth', block:'start' }), 120)
  } catch (error) {
   showToast('Request failed: ' + (error?.message || error), 'red')
  } finally {
   setInvoiceDeletionSubmitting(false)
  }
 }

 async function reviewInvoiceDeletionRequest(request, decision) {
  if (!request?.id || !invoiceDeletionAccess.can_review) {
   showToast('Only the authenticated owner can review deletion requests.', 'red')
   return
  }
  const reviewNote = String(invoiceDeletionReviewNotes[request.id] || '').trim()
  if (decision === 'reject' && reviewNote.length < 3) {
   showToast('Enter a rejection note with at least 3 characters.', 'red')
   return
  }
 const message = decision === 'approve'
   ? `Approve ${request.requested_by_name || 'the requester'}'s request for ${request.invoice_number}? The server will permanently delete it only if it is a clean unpaid invoice; otherwise it will be voided and financial history will remain.`
   : `Reject the deletion request for ${request.invoice_number}? The invoice will remain unchanged.`
  if (!window.confirm(message)) return

  const key = `${request.id}:${decision}`
  setInvoiceDeletionReviewProcessing(previous => ({...previous, [key]:true}))
  try {
   const { data, error } = await supabase.rpc('review_invoice_deletion_request', {
    p_request_id:request.id,
    p_decision:decision,
    p_review_note:reviewNote || null
   })
   if (error) throw error
   setInvoiceDeletionReviewNotes(previous => ({...previous, [request.id]:''}))
   if (viewingInvoice?.id === request.invoice_id) setViewingInvoice(null)
   if (editingInvoice?.id === request.invoice_id) { setEditingInvoice(null); setEditInvoiceItems([]) }
   await Promise.all([
    loadInvoiceDeletionRequests({ silent:true }),
    loadDeliveryInvoices(),
    loadNotifications(),
    loadFinancialData()
   ])
   refreshFoundationAfterDataChange('invoice-deletion-reviewed')
   if (decision === 'approve') { setInvoiceFilter('voided'); setInvoiceDayFilter('all') }
   showToast(data?.message || `Invoice deletion request ${decision === 'approve' ? 'approved' : 'rejected'}.`)
  } catch (error) {
   showToast('Review failed: ' + (error?.message || error), 'red')
  } finally {
   setInvoiceDeletionReviewProcessing(previous => ({...previous, [key]:false}))
  }
 }

function getInvoiceProductionDispatchNote(invoice) {
  const clean = value => String(value || '').replace(/\s+/g, ' ').trim()
  const directNote = [
    invoice?.reseller_request,
    invoice?.reseller_requests,
    invoice?.reseller_note,
    invoice?.reseller_notes,
    invoice?.order_request,
    invoice?.order_requests,
    invoice?.order_note,
    invoice?.order_notes,
    invoice?.special_instruction,
    invoice?.special_instructions,
    invoice?.production_note,
    invoice?.dispatch_note
  ].map(clean).find(Boolean)

  if (directNote) return directNote.slice(0, 140)

  const rawNotes = clean(invoice?.notes)
  if (!rawNotes) return ''

  const noteSegments = rawNotes
    .split(/\s*(?:\||\n|;)\s*/g)
    .map(clean)
    .filter(Boolean)

  const labelledNotePattern = /^(reseller\s*(?:request|requests|note|notes|instruction|instructions)|order\s*(?:request|requests|note|notes|instruction|instructions)|production\s*(?:\/\s*)?dispatch\s*note|dispatch\s*note)\s*:\s*/i
  const labelledNote = noteSegments.find(segment => labelledNotePattern.test(segment))
  if (labelledNote) return clean(labelledNote.replace(labelledNotePattern, '')).slice(0, 140)

  const internalNotePatterns = [
    /^from order\b/i,
    /^returns?\b/i,
    /^driver returns?\b/i,
    /^adjustment\b/i,
    /^actual\b/i,
    /^settlement\b/i,
    /^recorded inside payment\b/i,
    /^non-reseller invoice\b/i
  ]
  const manualNote = noteSegments.find(segment => !internalNotePatterns.some(pattern => pattern.test(segment)))
  return manualNote ? manualNote.slice(0, 140) : ''
}

