 function buildDeliveryInvoicePrintPage(invoice, pageClass = '') {
    const items = Array.isArray(invoice.delivery_invoice_items) ? invoice.delivery_invoice_items : [];
    const reseller = resellers.find(r => String(r.id) === String(invoice.reseller_id));
    const resellerAccount = resellerAccounts.find(a => String(a.id) === String(reseller?.reseller_account_id || invoice.reseller_account_id || ''));

    const cleanText = value => String(value || '').trim();
    const normalize = value => cleanText(value).toLowerCase().replace(/[^a-z0-9]/g, '');
    const escapeHtml = value => cleanText(value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');

    const peso = value => {
      const amount = safeNum(value, 0).toLocaleString('en-PH', { minimumFractionDigits:2, maximumFractionDigits:2 });
      return '\u20B1' + amount;
    };

    const formatInvoiceDate = value => {
      const raw = cleanText(value);
      if (!raw) return '';
      const datePart = raw.slice(0, 10);
      const parts = datePart.split('-');
      if (parts.length === 3) return parts[1] + ' / ' + parts[2] + ' / ' + parts[0];
      return raw;
    };

    const customerType = cleanText(invoice.customer_type || (invoice.reseller_id ? 'reseller' : 'non_reseller')).toLowerCase();
    const resellerName = customerType === 'non_reseller'
      ? [invoice.customer_name, invoice.reseller_name, invoice.customer_contact].map(cleanText).find(Boolean) || ''
      : [
        reseller?.contact_person,
        resellerAccount?.owner_name,
        resellerAccount?.account_name,
        invoice.reseller_contact_person,
        invoice.reseller_owner_name,
        invoice.customer_name,
        invoice.reseller_name,
        reseller?.name
      ].map(cleanText).find(Boolean) || '';

    const resellerAddress = customerType === 'non_reseller'
      ? [invoice.customer_address, invoice.address, invoice.customer_contact].map(cleanText).find(Boolean) || ''
      : [
        reseller?.address,
        invoice.customer_address,
        invoice.reseller_address,
        invoice.address,
        reseller?.area
      ].map(cleanText).find(Boolean) || '';

    const containerLabel = cleanText(invoice.container_type || 'Crates');
    const preparedBy = '';
    const productionDispatchNote = getInvoiceProductionDispatchNote(invoice);

    const rows = [
      { label:'Choco Balls', aliases:['Choco Balls'] },
      { label:'', aliases:[] },
      { label:'Almond Glitz', aliases:['Almond Glitz'] },
      { label:'Fanfans', aliases:['Fanfans', 'Fan Fans'] },
      { label:'Oreo Dream', aliases:['Oreo Dream'] },
      { label:'Lotus Cloud', aliases:['Lotus Cloud'] },
      { label:'Rings', aliases:['Rings'] },
      { label:'Shells', aliases:['Shells'] },
      { label:'Bav. Midnight', aliases:['Bavarian Midnight', 'Bav. Midnight', 'Bav Midnight'] },
      { label:'Circlets', aliases:['Circlets', 'Glazed Circlets', 'Glaze Circlet'] },
      { label:'Bavarian Bites', aliases:['Bavarian Bites'] },
      { label:'Bavarian Pops', aliases:['Bavarian Pops'] },
      { label:'Strawberry Pops', aliases:['Strawberry Pops'] },
      { label:'Taro Pops', aliases:['Taro Pops'] },
      { label:'Cinnamon Rolls', aliases:['Cinnamon Rolls'] },
      { label:'Biscoreo', aliases:['Biscoreo'] },
      { label:'Choco Lollisticks', aliases:['Choco Lollisticks', 'Choco Lollistick', 'Choco Lollistiks'] }
    ];

    const getQty = item => safeNum(item?.delivered_quantity ?? item?.actual_quantity ?? item?.quantity, 0);
    const getPrice = item => safeNum(item?.reseller_price ?? item?.unit_price ?? item?.price ?? item?.selling_price, 0);
    const getAmount = item => {
      const stored = safeNum(item?.total_price ?? item?.amount ?? item?.line_total, NaN);
      if (Number.isFinite(stored)) return stored;
      return getQty(item) * getPrice(item);
    };

    const findMatchingItems = row => {
      if (!row.label) return [];
      const aliases = row.aliases.map(normalize);
      return items.filter(item => {
        const itemName = normalize(item.variant_name || item.product_name || item.name || '');
        return aliases.some(alias => itemName === alias || itemName.includes(alias) || alias.includes(itemName));
      });
    };

    const productRowsHtml = rows.map(row => {
      if (!row.label) {
        return '<tr class="product-row"><td>&nbsp;</td><td></td><td></td><td></td><td></td></tr>';
      }

      const matched = findMatchingItems(row);
      const qty = matched.reduce((sum, item) => sum + getQty(item), 0);
      const first = matched[0] || null;
      const price = first ? getPrice(first) : 0;
      const amount = matched.reduce((sum, item) => sum + getAmount(item), 0);
      const unsoldQty = matched.reduce((sum, item) => sum + getInvoiceItemUnsoldQuantity(invoice, item), 0);

      return `<tr class="product-row">
        <td class="product-name">${escapeHtml(row.label)}</td>
        <td class="number-cell">${qty ? qty.toLocaleString('en-PH') : ''}</td>
        <td class="money-cell">${price ? peso(price) : ''}</td>
        <td class="money-cell">${amount ? peso(amount) : ''}</td>
        <td class="number-cell">${unsoldQty ? unsoldQty.toLocaleString('en-PH') : ''}</td>
      </tr>`;
    }).join('');

    const computedTotal = rows.reduce((sum, row) => {
      return sum + findMatchingItems(row).reduce((itemSum, item) => itemSum + getAmount(item), 0);
    }, 0);

    const invoiceTotal = safeNum(invoice.total_amount, computedTotal || 0) || computedTotal;

    return `
      <section class="invoice-page ${pageClass}">
        <table class="invoice-table">
          <colgroup>
            <col style="width:31%;">
            <col style="width:21%;">
            <col style="width:16%;">
            <col style="width:16%;">
            <col style="width:16%;">
          </colgroup>

          <tr class="title-row">
            <td colspan="5">Roma\u2019s Donuts \u2013 Delivery Invoice</td>
          </tr>

          <tr class="field-row">
            <td class="field-label">Date:</td>
            <td class="field-value date-fill" colspan="3">${escapeHtml(formatInvoiceDate(invoice.delivery_date || invoice.invoice_date || ''))}</td>
            <td></td>
          </tr>

          <tr class="field-row">
            <td class="field-label">Customer:</td>
            <td class="field-value customer-fill" colspan="3">${escapeHtml(resellerName)}</td>
            <td></td>
          </tr>

          <tr class="field-row">
            <td class="field-label">Address:</td>
            <td class="field-value address-fill" colspan="3">${escapeHtml(resellerAddress)}</td>
            <td></td>
          </tr>

          <tr class="note-row">
            <td class="note-cell" colspan="5">NOTES:${productionDispatchNote ? ' ' + escapeHtml(productionDispatchNote) : ''}</td>
          </tr>

          <tr class="header-row">
            <th>Product</th>
            <th>Delivered</th>
            <th>Price</th>
            <th>Amount</th>
            <th>Unsold</th>
          </tr>

          ${productRowsHtml}

          <tr class="blank-row"><td></td><td></td><td></td><td></td><td></td></tr>

          <tr class="footer-row">
            <td class="footer-label">${escapeHtml(containerLabel)} Used</td>
            <td class="number-cell">${invoice.crates_used ? escapeHtml(invoice.crates_used) : ''}</td>
            <td></td>
            <td></td>
            <td></td>
          </tr>

          <tr class="footer-row">
            <td class="footer-label">${escapeHtml(containerLabel)} Cover</td>
            <td></td>
            <td class="total-label">TOTAL</td>
            <td class="total-amount">${peso(invoiceTotal)}</td>
            <td></td>
          </tr>

          <tr class="footer-row">
            <td class="footer-label prepared-fill">Prepared by:</td>
            <td class="prepared-fill" colspan="2">${escapeHtml(preparedBy)}</td>
            <td></td>
            <td></td>
          </tr>
        </table>
      </section>`;
  }



 function escapeWordDocText(value) {
   return String(value || '')
     .replace(/&/g, '&amp;')
     .replace(/</g, '&lt;')
     .replace(/>/g, '&gt;')
     .replace(/"/g, '&quot;')
     .replace(/'/g, '&#39;')
 }

 function sanitizeWordFileName(value) {
   const clean = String(value || 'roma-delivery-invoice')
     .replace(/[\\/:*?"<>|]+/g, '-')
     .replace(/\s+/g, '_')
     .replace(/_+/g, '_')
     .replace(/^_+|_+$/g, '')
   return clean.slice(0, 120) || 'roma-delivery-invoice'
 }


  // MASTER DONUT VARIETY ORDER - use this everywhere for uniform display.
  const DONUT_VARIANT_DISPLAY_ORDER = [
    { label:'Choco Balls', aliases:['Choco Balls'] },
    { label:'Matcha Pops', aliases:['Matcha Pops'] },
    { label:'Taro Pops', aliases:['Taro Pops'] },
    { label:'Strawberry Pops', aliases:['Strawberry Pops'] },
    { label:'Bavarian Pops', aliases:['Bavarian Pops'] },
    { label:'Bavarian Bites', aliases:['Bavarian Bites'] },
    { label:'Choco Lollisticks', aliases:['Choco Lollisticks', 'Choco Lollistick', 'Choco Lollistiks'] },
    { label:'Circlets', aliases:['Circlets', 'Glazed Circlets', 'Glaze Circlet'] },
    { label:'Cinnamon Rolls', aliases:['Cinnamon Rolls'] },
    { label:'Rings', aliases:['Rings'] },
    { label:'Shells', aliases:['Shells'] },
    { label:'Bav. Midnight', aliases:['Bavarian Midnight', 'Bav. Midnight', 'Bav Midnight'] },
    { label:'Biscoreo', aliases:['Biscoreo'] },
    { label:'Oreo Dream', aliases:['Oreo Dream'] },
    { label:'Fanfans', aliases:['Fanfans', 'Fan Fans'] },
    { label:'Almond Glitz', aliases:['Almond Glitz'] },
    { label:'Lotus Cloud', aliases:['Lotus Cloud'] }
  ];

  function normalizeDonutVariantName(value) {
    return String(value || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
  }

  const DONUT_VARIANT_ORDER_INDEX = DONUT_VARIANT_DISPLAY_ORDER.reduce((map, row, index) => {
    [row.label, ...(row.aliases || [])].forEach(name => {
      const key = normalizeDonutVariantName(name);
      if (key) map[key] = index;
    });
    return map;
  }, {});

  function getDonutVariantOrderIndex(value) {
    const key = normalizeDonutVariantName(value);
    return Object.prototype.hasOwnProperty.call(DONUT_VARIANT_ORDER_INDEX, key)
      ? DONUT_VARIANT_ORDER_INDEX[key]
      : 9999;
  }

  function compareDonutVariantNamesByGuide(a, b) {
    const ai = getDonutVariantOrderIndex(a);
    const bi = getDonutVariantOrderIndex(b);
    if (ai !== bi) return ai - bi;
    return String(a || '').localeCompare(String(b || ''));
  }

  function compareDonutVariantRowsByGuide(a, b) {
    const an = a?.variant_name || a?.variant || a?.product_name || a?.name || a?.product || '';
    const bn = b?.variant_name || b?.variant || b?.product_name || b?.name || b?.product || '';
    return compareDonutVariantNamesByGuide(an, bn);
  }

  function sortDonutVariantsByGuide(list) {
    return [...(Array.isArray(list) ? list : [])].sort((a, b) =>
      compareDonutVariantNamesByGuide(
        a?.name || a?.variant_name || a?.product_name || '',
        b?.name || b?.variant_name || b?.product_name || ''
      )
    );
  }

  function buildInvoiceProductTemplateFromGuide() {
    return DONUT_VARIANT_DISPLAY_ORDER.map(row => ({
      label: row.label,
      aliases: row.aliases || [row.label]
    }));
  }

 function getDeliveryInvoicePrintData(invoice) {
   const items = Array.isArray(invoice?.delivery_invoice_items) ? invoice.delivery_invoice_items : []
   const reseller = resellers.find(r => String(r.id) === String(invoice?.reseller_id))
   const resellerAccount = resellerAccounts.find(a => String(a.id) === String(reseller?.reseller_account_id || invoice?.reseller_account_id || ''))

   const cleanText = value => String(value || '').trim()
   const normalize = value => cleanText(value).toLowerCase().replace(/[^a-z0-9]/g, '')

   const peso = value => {
     const amount = safeNum(value, 0).toLocaleString('en-PH', { minimumFractionDigits:2, maximumFractionDigits:2 })
     return '\u20B1' + amount
   }

   const formatInvoiceDate = value => {
     const raw = cleanText(value)
     if (!raw) return ''
     const datePart = raw.slice(0, 10)
     const parts = datePart.split('-')
     if (parts.length === 3) return parts[1] + ' / ' + parts[2] + ' / ' + parts[0]
     return raw
   }

   const customerType = cleanText(invoice?.customer_type || (invoice?.reseller_id ? 'reseller' : 'non_reseller')).toLowerCase()
   const customerName = customerType === 'non_reseller'
     ? [invoice?.customer_name, invoice?.reseller_name, invoice?.customer_contact].map(cleanText).find(Boolean) || ''
     : [
       reseller?.contact_person,
       resellerAccount?.owner_name,
       resellerAccount?.account_name,
       invoice?.reseller_contact_person,
       invoice?.reseller_owner_name,
       invoice?.customer_name,
       invoice?.reseller_name,
       reseller?.name
     ].map(cleanText).find(Boolean) || ''

   const customerAddress = customerType === 'non_reseller'
     ? [invoice?.customer_address, invoice?.address, invoice?.customer_contact].map(cleanText).find(Boolean) || ''
     : [
       reseller?.address,
       invoice?.customer_address,
       invoice?.reseller_address,
       invoice?.address,
       reseller?.area
     ].map(cleanText).find(Boolean) || ''

    const productTemplate = buildInvoiceProductTemplateFromGuide()

   const getQty = item => safeNum(item?.delivered_quantity ?? item?.actual_quantity ?? item?.quantity, 0)
   const getPrice = item => safeNum(item?.reseller_price ?? item?.unit_price ?? item?.price ?? item?.selling_price, 0)
   const getAmount = item => {
     const stored = safeNum(item?.total_price ?? item?.amount ?? item?.line_total, NaN)
     if (Number.isFinite(stored)) return stored
     return getQty(item) * getPrice(item)
   }

   const findMatchingItems = row => {
     if (!row.label) return []
     const aliases = row.aliases.map(normalize)
     return items.filter(item => {
       const itemName = normalize(item.variant_name || item.product_name || item.name || '')
       return aliases.some(alias => itemName === alias || itemName.includes(alias) || alias.includes(itemName))
     })
   }

   const productRows = productTemplate.map(row => {
     if (!row.label) return { product:'', delivered:'', price:'', amount:'', unsold:'', _spacer:true }
     const matched = findMatchingItems(row)
     const qty = matched.reduce((sum, item) => sum + getQty(item), 0)
     const first = matched[0] || null
     const price = first ? getPrice(first) : 0
     const amount = matched.reduce((sum, item) => sum + getAmount(item), 0)
     const unsoldQty = matched.reduce((sum, item) => sum + getInvoiceItemUnsoldQuantity(invoice, item), 0)
     return {
       product: row.label,
       delivered: qty ? qty.toLocaleString('en-PH') : '',
       price: price ? peso(price) : '',
       amount: amount ? peso(amount) : '',
       unsold: unsoldQty ? unsoldQty.toLocaleString('en-PH') : '',
       _ordered: qty > 0
     }
   })

   const computedTotal = productTemplate.reduce((sum, row) => {
     return sum + findMatchingItems(row).reduce((itemSum, item) => itemSum + getAmount(item), 0)
   }, 0)
   const invoiceTotal = safeNum(invoice?.total_amount, computedTotal || 0) || computedTotal

   return {
     title:'Roma’s Donuts - Delivery Invoice',
     date:formatInvoiceDate(invoice?.delivery_date || invoice?.invoice_date || ''),
     customerName,
     customerAddress,
     containerLabel:cleanText(invoice?.container_type || 'Crates'),
     cratesUsed:invoice?.crates_used ? cleanText(invoice.crates_used) : '',
     productionDispatchNote:getInvoiceProductionDispatchNote(invoice),
     total:peso(invoiceTotal),
     preparedBy:'',
     productRows
   }
 }

 function wordXmlText(value) {
   return String(value ?? '')
     .replace(/&/g, '&amp;')
     .replace(/</g, '&lt;')
     .replace(/>/g, '&gt;')
     .replace(/"/g, '&quot;')
     .replace(/'/g, '&apos;')
 }

 function wordRun(text, opts = {}) {
   // Word DOCX uses half-points: 20 = Arial 10pt.
   const size = opts.size || 20
   // Use bold as the default for invoice readability on 4x6 thermal/photo paper.
   // Pass bold:false only for intentionally light text.
   const bold = opts.bold === false ? '' : '<w:b/><w:bCs/>'
   const italic = opts.italic ? '<w:i/><w:iCs/>' : ''
   const color = opts.color ? `<w:color w:val="${opts.color}"/>` : ''
   return `<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:sz w:val="${size}"/><w:szCs w:val="${size}"/>${bold}${italic}${color}</w:rPr><w:t xml:space="preserve">${wordXmlText(text)}</w:t></w:r>`
 }

 function wordParagraph(text, opts = {}) {
   const align = opts.align || 'left'
   // Arial 10 needs enough exact line height so Word does not display it as 5pt or clip bold text.
   const size = opts.size || 20
   const line = opts.line || Math.max(240, Math.ceil(size * 12))
   return `<w:p><w:pPr><w:jc w:val="${align}"/><w:spacing w:before="0" w:after="0" w:line="${line}" w:lineRule="exact"/></w:pPr>${wordRun(text, opts)}</w:p>`
 }

 function wordCell(text, opts = {}) {
   const width = safeNum(opts.width, 1000)
   const span = opts.span ? `<w:gridSpan w:val="${opts.span}"/>` : ''
   const shade = opts.shade ? `<w:shd w:fill="${opts.shade}"/>` : ''
   const vAlign = '<w:vAlign w:val="center"/>'
   const padLeft = safeNum(opts.padLeft, 14)
   const padRight = safeNum(opts.padRight, 14)
   const cellMargins = `<w:tcMar><w:top w:w="0" w:type="dxa"/><w:left w:w="${padLeft}" w:type="dxa"/><w:bottom w:w="0" w:type="dxa"/><w:right w:w="${padRight}" w:type="dxa"/></w:tcMar>`
   return `<w:tc><w:tcPr><w:tcW w:w="${width}" w:type="dxa"/>${span}${shade}${vAlign}${cellMargins}</w:tcPr>${wordParagraph(text, opts)}</w:tc>`
 }

 function wordRow(cells, height = 320) {
   return `<w:tr><w:trPr><w:trHeight w:val="${height}" w:hRule="exact"/><w:cantSplit/></w:trPr>${cells.join('')}</w:tr>`
 }

 function buildLogoDrawingRun(relId, sizeTwips) {
   const emu = Math.round(sizeTwips * 635)
   return `<w:r><w:drawing><wp:inline xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" distT="0" distB="0" distL="0" distR="0"><wp:extent cx="${emu}" cy="${emu}"/><wp:docPr id="1" name="Roma's Donuts Logo"/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="1" name="Roma's Donuts Logo"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="${relId}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${emu}" cy="${emu}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r>`
 }
 function wordImageCell(relId, sizeTwips, opts={}) {
   const width=safeNum(opts.width,1000), span=opts.span?`<w:gridSpan w:val="${opts.span}"/>`:''
   return `<w:tc><w:tcPr><w:tcW w:w="${width}" w:type="dxa"/>${span}<w:vAlign w:val="center"/></w:tcPr><w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="0" w:after="0"/></w:pPr>${buildLogoDrawingRun(relId,sizeTwips)}</w:p></w:tc>`
 }
 async function fetchLogoImageBytes() {
   try { const r=await fetch('/logo.png',{cache:'no-store'}); if(!r.ok) throw new Error(`HTTP ${r.status}`); return new Uint8Array(await r.arrayBuffer()) }
   catch(e) { console.warn('Roma invoice logo unavailable; continuing without logo.',e); return null }
 }
 function buildInvoiceDocxTopSpacer(startNewPage = false) {
   // Keeps the invoice title away from Word/printer top clipping while page margin stays 0.
   // For Print All, use pageBreakBefore on this spacer instead of placing a page-break paragraph
   // after each invoice. A trailing page-break paragraph can be forced onto its own sheet,
   // which creates the blank pages seen between invoices in Word print preview.
   const pageBreak = startNewPage ? '<w:pageBreakBefore/>' : ''
   return `<w:p><w:pPr>${pageBreak}<w:spacing w:before="0" w:after="0" w:line="20" w:lineRule="exact"/></w:pPr></w:p>`
 }

 function buildDeliveryInvoiceDocxTable(invoice, hasLogo) {
   const data = getDeliveryInvoicePrintData(invoice)
   // Fixed physical paper size:20mm x 165mm, confirmed from the Word custom
   // paper setup screenshot — this matches real paper stock, not a computed value. Table width is sized to fit
   // within the page margins (147 twips ≈ 2.6mm each side), leaving a
   // little clearance on all 4 sides as requested. Checked against the
   // maximum possible invoice (all 17 donut variants at once) — even that
   // fits comfortably within 165mm with room to spare, so this size is
   // safe for every invoice this system can produce, not just typical ones.
   // Keep the product table as five separate columns. The Amount column is slightly wider
   // so totals and peso amounts do not clip, while the Unsold column stays separate for returns.
   const widths = [1675, 1155, 863, 863, 864]
   const full = widths.reduce((sum, w) => sum + w, 0)
   const valueSpan4 = widths[1] + widths[2] + widths[3] + widths[4]

   // Brand palette — same red/gold used across the rest of the system.
   const BRAND_RED = 'CA1B1B'
   const BRAND_GOLD = 'FDD412'
   const PALE_GOLD = 'FCEEC0'
   const PALE_RED = 'FBDCDC'

   const rows = []
   if (hasLogo) rows.push(wordRow([wordImageCell('rIdLogo', 420, { width:full, span:5 })], 500))
   rows.push(wordRow([wordCell(data.title, { width:full, span:5, align:'center', bold:true, size:20, line:240, shade:BRAND_RED, color:'FFFFFF' })], 320))
   rows.push(wordRow([
     wordCell('Date:', { width:widths[0], align:'center', bold:true, size:20 }),
     wordCell(data.date, { width:valueSpan4, span:4, align:'left', size:20, shade:PALE_GOLD })
   ], 280))
   rows.push(wordRow([
     wordCell('Customer:', { width:widths[0], align:'center', bold:true, size:20 }),
     wordCell(data.customerName, { width:valueSpan4, span:4, align:'left', size:20, shade:PALE_GOLD })
   ], 280))
   rows.push(wordRow([
     wordCell('Address:', { width:widths[0], align:'center', bold:true, size:20 }),
     wordCell(data.customerAddress, { width:valueSpan4, span:4, align:'left', size:20, shade:PALE_RED })
   ], 280))
   rows.push(wordRow([
     wordCell(`NOTES:${data.productionDispatchNote ? ' ' + data.productionDispatchNote : ''}`, { width:full, span:5, align:'left', bold:true, size:20, line:240, shade:PALE_GOLD })
   ], 250))
   rows.push(wordRow([
     wordCell('Product', { width:widths[0], align:'center', bold:true, size:20, shade:BRAND_RED, color:'FFFFFF' }),
     wordCell('Delivered', { width:widths[1], align:'center', bold:true, size:20, shade:BRAND_RED, color:'FFFFFF' }),
     wordCell('Price', { width:widths[2], align:'center', bold:true, size:20, shade:BRAND_RED, color:'FFFFFF' }),
     wordCell('Amount', { width:widths[3], align:'center', bold:true, size:20, shade:BRAND_RED, color:'FFFFFF' }),
     wordCell('Unsold', { width:widths[4], align:'center', bold:true, size:20, shade:BRAND_RED, color:'FFFFFF' })
   ], 280))

   data.productRows.forEach(row => {
     rows.push(wordRow([
       wordCell(row.product, { width:widths[0], align:'center', bold:!!row.product, size:20 }),
       wordCell(row.delivered, { width:widths[1], align:'center', size:20 }),
       wordCell(row.price, { width:widths[2], align:'right', size:20 }),
       wordCell(row.amount, { width:widths[3], align:'right', size:20 }),
       wordCell(row.unsold, { width:widths[4], align:'center', size:20 })
      ], 280))
   })

   rows.push(wordRow(widths.map(w => wordCell('', { width:w, align:'center', size:20 })), 40))
   rows.push(wordRow([
     wordCell(`${data.containerLabel} Used`, { width:widths[0], align:'center', bold:true, italic:true, size:20 }),
     wordCell(data.cratesUsed, { width:widths[1], align:'center', size:20 }),
     wordCell('', { width:widths[2], align:'center', size:20 }),
     wordCell('', { width:widths[3], align:'center', size:20 }),
     wordCell('', { width:widths[4], align:'center', size:20 })
   ], 280))
   rows.push(wordRow([
     wordCell(`${data.containerLabel} Cover`, { width:widths[0], align:'center', bold:true, italic:true, size:20 }),
     wordCell('', { width:widths[1], align:'center', size:20, shade:BRAND_GOLD }),
     wordCell('TOTAL', { width:widths[2], align:'center', bold:true, size:20, shade:BRAND_GOLD }),
     wordCell(data.total, { width:widths[3], align:'right', bold:true, size:20, shade:BRAND_GOLD }),
     wordCell('', { width:widths[4], align:'center', size:20, shade:BRAND_GOLD })
   ], 320))
   rows.push(wordRow([
     wordCell('Prepared by:', { width:widths[0], align:'center', bold:true, italic:true, size:20, shade:PALE_GOLD }),
     wordCell(data.preparedBy, { width:valueSpan4, span:4, align:'left', size:20, shade:PALE_GOLD })
   ], 280))

   return `<w:tbl><w:tblPr><w:tblW w:w="${full}" w:type="dxa"/><w:jc w:val="center"/><w:tblLayout w:type="fixed"/><w:tblLook w:firstRow="0" w:lastRow="0" w:firstColumn="0" w:lastColumn="0" w:noHBand="1" w:noVBand="1"/><w:tblBorders><w:top w:val="single" w:sz="14" w:space="0" w:color="${BRAND_RED}"/><w:left w:val="single" w:sz="14" w:space="0" w:color="${BRAND_RED}"/><w:bottom w:val="single" w:sz="14" w:space="0" w:color="${BRAND_RED}"/><w:right w:val="single" w:sz="14" w:space="0" w:color="${BRAND_RED}"/><w:insideH w:val="single" w:sz="10" w:space="0" w:color="${BRAND_RED}"/><w:insideV w:val="single" w:sz="10" w:space="0" w:color="${BRAND_RED}"/></w:tblBorders><w:tblCellMar><w:top w:w="0" w:type="dxa"/><w:left w:w="0" w:type="dxa"/><w:bottom w:w="0" w:type="dxa"/><w:right w:w="0" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>${widths.map(w => `<w:gridCol w:w="${w}"/>`).join('')}</w:tblGrid>${rows.join('')}</w:tbl>`
 }

 function buildDeliveryInvoicesDocxDocument(invoices, hasLogo) {
   const invoiceList = Array.isArray(invoices) ? invoices : []
   const bodyParts = []
   invoiceList.forEach((invoice, idx) => {
     bodyParts.push(buildInvoiceDocxTopSpacer(idx > 0))
     bodyParts.push(buildDeliveryInvoiceDocxTable(invoice))
   })

   // Fixed physical paper size: 105mm x 165mm (5953 x 9354 twips) — real
   // paper stock, confirmed exact from the Word custom paper setup screenshot. Margins of 147 twips (~2.6mm) on all 4
   // sides, per request. Verified safe for every invoice this system can
   // produce: even the maximum possible order (all 17 donut variants at
   // once) uses a full-height 10.5cm x 16.5cm layout with no second-page spill
   // and minimal blank space at the bottom.
   const MARGIN = 170
   return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body>${bodyParts.join('')}<w:sectPr><w:pgSz w:w="5760" w:h="8640"/><w:pgMar w:top="${MARGIN}" w:right="${MARGIN}" w:bottom="${MARGIN}" w:left="${MARGIN}" w:header="0" w:footer="0" w:gutter="0"/><w:cols w:space="0"/><w:docGrid w:linePitch="360"/></w:sectPr></w:body></w:document>`
 }

 function createCrc32Table() {
   const table = new Uint32Array(256)
   for (let i = 0; i < 256; i++) {
     let c = i
     for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1)
     table[i] = c >>> 0
   }
   return table
 }

 function crc32Bytes(bytes) {
   const table = createCrc32Table()
   let crc = 0xFFFFFFFF
   for (let i = 0; i < bytes.length; i++) crc = table[(crc ^ bytes[i]) & 0xFF] ^ (crc >>> 8)
   return (crc ^ 0xFFFFFFFF) >>> 0
 }

 function writeUint16LE(array, value) {
   array.push(value & 0xFF, (value >>> 8) & 0xFF)
 }

 function writeUint32LE(array, value) {
   array.push(value & 0xFF, (value >>> 8) & 0xFF, (value >>> 16) & 0xFF, (value >>> 24) & 0xFF)
 }

 function concatUint8Arrays(chunks) {
   const total = chunks.reduce((sum, chunk) => sum + chunk.length, 0)
   const out = new Uint8Array(total)
   let offset = 0
   chunks.forEach(chunk => { out.set(chunk, offset); offset += chunk.length })
   return out
 }

 function createStoredZipBlob(files, mimeType) {
   const encoder = new TextEncoder()
   const localChunks = []
   const centralChunks = []
   let offset = 0
   const now = new Date()
   const dosTime = ((now.getHours() & 0x1F) << 11) | ((now.getMinutes() & 0x3F) << 5) | ((Math.floor(now.getSeconds() / 2)) & 0x1F)
   const dosDate = (((now.getFullYear() - 1980) & 0x7F) << 9) | (((now.getMonth() + 1) & 0x0F) << 5) | (now.getDate() & 0x1F)

   files.forEach(file => {
     const nameBytes = encoder.encode(file.name)
     const dataBytes = typeof file.data === 'string' ? encoder.encode(file.data) : file.data
     const crc = crc32Bytes(dataBytes)
     const local = []
     writeUint32LE(local, 0x04034b50)
     writeUint16LE(local, 20)
     writeUint16LE(local, 0)
     writeUint16LE(local, 0)
     writeUint16LE(local, dosTime)
     writeUint16LE(local, dosDate)
     writeUint32LE(local, crc)
     writeUint32LE(local, dataBytes.length)
     writeUint32LE(local, dataBytes.length)
     writeUint16LE(local, nameBytes.length)
     writeUint16LE(local, 0)
     const localHeader = new Uint8Array([...local, ...nameBytes])
     localChunks.push(localHeader, dataBytes)

     const central = []
     writeUint32LE(central, 0x02014b50)
     writeUint16LE(central, 20)
     writeUint16LE(central, 20)
     writeUint16LE(central, 0)
     writeUint16LE(central, 0)
     writeUint16LE(central, dosTime)
     writeUint16LE(central, dosDate)
     writeUint32LE(central, crc)
     writeUint32LE(central, dataBytes.length)
     writeUint32LE(central, dataBytes.length)
     writeUint16LE(central, nameBytes.length)
     writeUint16LE(central, 0)
     writeUint16LE(central, 0)
     writeUint16LE(central, 0)
     writeUint16LE(central, 0)
     writeUint32LE(central, 0)
     writeUint32LE(central, offset)
     centralChunks.push(new Uint8Array([...central, ...nameBytes]))

     offset += localHeader.length + dataBytes.length
   })

   const centralStart = offset
   const centralData = concatUint8Arrays(centralChunks)
   const end = []
   writeUint32LE(end, 0x06054b50)
   writeUint16LE(end, 0)
   writeUint16LE(end, 0)
   writeUint16LE(end, files.length)
   writeUint16LE(end, files.length)
   writeUint32LE(end, centralData.length)
   writeUint32LE(end, centralStart)
   writeUint16LE(end, 0)

   const zipData = concatUint8Arrays([...localChunks, centralData, new Uint8Array(end)])
   return new Blob([zipData], { type:mimeType })
 }

 function buildDeliveryInvoicesDocxBlob(invoices, logoBytes) {
   const hasLogo = logoBytes instanceof Uint8Array && logoBytes.length > 0
   const documentXml = buildDeliveryInvoicesDocxDocument(invoices, hasLogo)
   const contentTypes = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>${hasLogo ? '<Default Extension="png" ContentType="image/png"/>' : ''}<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/word/settings.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml"/></Types>`
   const rootRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`
   const docRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/>${hasLogo ? '<Relationship Id="rIdLogo" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/logo.png"/>' : ''}</Relationships>`
   const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:b/><w:bCs/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr></w:pPrDefault></w:docDefaults></w:styles>`
   const settings = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:settings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:zoom w:percent="100"/><w:compat><w:compatSetting w:name="compatibilityMode" w:uri="http://schemas.microsoft.com/office/word" w:val="15"/></w:compat></w:settings>`

   return createStoredZipBlob([
     { name:'[Content_Types].xml', data:contentTypes },
     { name:'_rels/.rels', data:rootRels },
     { name:'word/document.xml', data:documentXml },
     { name:'word/_rels/document.xml.rels', data:docRels },
     { name:'word/styles.xml', data:styles },
     { name:'word/settings.xml', data:settings }
   ,
     ...(hasLogo ? [{ name:'word/media/logo.png', data:logoBytes }] : [])], 'application/vnd.openxmlformats-officedocument.wordprocessingml.document')
 }

 function downloadDeliveryInvoiceDocxFile(filename, invoices, logoBytes) {
   const blob = buildDeliveryInvoicesDocxBlob(invoices, logoBytes)
   const url = URL.createObjectURL(blob)
   const link = document.createElement('a')
   link.href = url
   link.download = `${sanitizeWordFileName(filename)}.docx`
   document.body.appendChild(link)
   link.click()
   document.body.removeChild(link)
   setTimeout(() => URL.revokeObjectURL(url), 1500)
 }

 const DELIVERY_INVOICE_SOURCE_WIDTH_MM = 105
 const DELIVERY_INVOICE_SOURCE_HEIGHT_MM = 165
 const DELIVERY_INVOICE_PAGE_WIDTH_MM = 101.6
 const DELIVERY_INVOICE_PAGE_HEIGHT_MM = 152.4
 const DELIVERY_INVOICE_SAFE_MARGIN_MM = 3
 const DELIVERY_INVOICE_EXPORT_DPI = 300

 function downloadGeneratedInvoiceFile(filename, blob) {
   const url = URL.createObjectURL(blob)
   const link = document.createElement('a')
   link.href = url
   link.download = sanitizeWordFileName(filename)
   document.body.appendChild(link)
   link.click()
   document.body.removeChild(link)
   setTimeout(() => URL.revokeObjectURL(url), 2000)
 }

 function invoiceCanvasToBlob(canvas, type = 'image/png') {
   return new Promise((resolve, reject) => {
     canvas.toBlob(blob => {
       if (blob) resolve(blob)
       else reject(new Error('The browser could not create the invoice image.'))
     }, type, 1)
   })
 }

 async function renderDeliveryInvoicePageCanvas(invoice) {
   const iframe = document.createElement('iframe')
   iframe.setAttribute('aria-hidden', 'true')
   iframe.style.position = 'fixed'
   iframe.style.left = '-20000px'
   iframe.style.top = '0'
   iframe.style.width = `${DELIVERY_INVOICE_SOURCE_WIDTH_MM}mm`
   iframe.style.height = `${DELIVERY_INVOICE_SOURCE_HEIGHT_MM}mm`
   iframe.style.border = '0'
   iframe.style.opacity = '0'
   iframe.style.pointerEvents = 'none'
   document.body.appendChild(iframe)

   try {
     const frameDocument = iframe.contentDocument
     if (!frameDocument) throw new Error('The browser could not prepare the invoice export page.')
     frameDocument.open()
     frameDocument.write(`<!doctype html><html><head><meta charset="utf-8">${buildDeliveryInvoicePrintCSS()}<style>
       html,body{width:${DELIVERY_INVOICE_SOURCE_WIDTH_MM}mm!important;min-height:${DELIVERY_INVOICE_SOURCE_HEIGHT_MM}mm!important;height:auto!important;overflow:visible!important;background:#fff!important;}
       .invoice-page{width:${DELIVERY_INVOICE_SOURCE_WIDTH_MM}mm!important;min-height:${DELIVERY_INVOICE_SOURCE_HEIGHT_MM}mm!important;height:auto!important;margin:0!important;overflow:visible!important;background:#fff!important;}
       .title-row td{justify-content:center!important;text-align:center!important;}
       .title-row img,.invoice-logo,img[alt*="logo" i]{display:none!important;}
     </style></head><body>${buildDeliveryInvoicePrintPage(invoice)}</body></html>`)
     frameDocument.close()

     if (frameDocument.fonts?.ready) await frameDocument.fonts.ready
     await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))
     const invoicePage = frameDocument.querySelector('.invoice-page')
     if (!invoicePage) throw new Error('The invoice export layout could not be rendered.')

     // The Word export uses the invoice itself as an image. Remove image branding
     // from the invoice body so only the Roma's Donuts wordmark/title remains.
     invoicePage.querySelectorAll('img').forEach(img => img.remove())

     const pageRect = invoicePage.getBoundingClientRect()
     const sourceWindowWidth = Math.ceil(Math.max(pageRect.width, (DELIVERY_INVOICE_SOURCE_WIDTH_MM / 25.4) * 96))
     const sourceWindowHeight = Math.ceil(Math.max(pageRect.height, invoicePage.scrollHeight, (DELIVERY_INVOICE_SOURCE_HEIGHT_MM / 25.4) * 96))
     const contentCanvas = await html2canvas(invoicePage, {
       backgroundColor:'#ffffff',
       logging:false,
       scale:DELIVERY_INVOICE_EXPORT_DPI / 96,
       useCORS:true,
       windowWidth:sourceWindowWidth,
       windowHeight:sourceWindowHeight,
       scrollX:0,
       scrollY:0
     })

     const pageCanvas = document.createElement('canvas')
     pageCanvas.width = Math.round((DELIVERY_INVOICE_PAGE_WIDTH_MM / 25.4) * DELIVERY_INVOICE_EXPORT_DPI)
     pageCanvas.height = Math.round((DELIVERY_INVOICE_PAGE_HEIGHT_MM / 25.4) * DELIVERY_INVOICE_EXPORT_DPI)
     const marginPx = Math.round((DELIVERY_INVOICE_SAFE_MARGIN_MM / 25.4) * DELIVERY_INVOICE_EXPORT_DPI)
     const targetWidth = pageCanvas.width - (marginPx * 2)
     const targetHeight = pageCanvas.height - (marginPx * 2)
     const scale = Math.min(targetWidth / contentCanvas.width, targetHeight / contentCanvas.height)
     const drawWidth = Math.max(1, Math.round(contentCanvas.width * scale))
     const drawHeight = Math.max(1, Math.round(contentCanvas.height * scale))
     const drawX = Math.round((pageCanvas.width - drawWidth) / 2)
     const drawY = Math.round((pageCanvas.height - drawHeight) / 2)
     const ctx = pageCanvas.getContext('2d')
     if (!ctx) throw new Error('The browser could not create the invoice export canvas.')
     ctx.fillStyle = '#ffffff'
     ctx.fillRect(0, 0, pageCanvas.width, pageCanvas.height)
     ctx.imageSmoothingEnabled = true
     ctx.imageSmoothingQuality = 'high'
     ctx.drawImage(contentCanvas, drawX, drawY, drawWidth, drawHeight)
     return pageCanvas
   } finally {
     iframe.remove()
   }
 }

 async function downloadDeliveryInvoicePdfFile(filename, invoices) {
   const invoiceList = Array.isArray(invoices) ? invoices : []
   if (!invoiceList.length) throw new Error('No invoices are available for PDF export.')
   const pdf = new jsPDF({
     orientation:'portrait',
     unit:'mm',
     format:[DELIVERY_INVOICE_PAGE_WIDTH_MM, DELIVERY_INVOICE_PAGE_HEIGHT_MM],
     compress:true
   })
   for (let idx = 0; idx < invoiceList.length; idx++) {
     if (idx > 0) pdf.addPage([DELIVERY_INVOICE_PAGE_WIDTH_MM, DELIVERY_INVOICE_PAGE_HEIGHT_MM], 'portrait')
     const canvas = await renderDeliveryInvoicePageCanvas(invoiceList[idx])
     pdf.addImage(canvas, 'PNG', 0, 0, DELIVERY_INVOICE_PAGE_WIDTH_MM, DELIVERY_INVOICE_PAGE_HEIGHT_MM, undefined, 'FAST')
   }
   downloadGeneratedInvoiceFile(`${filename}.pdf`, pdf.output('blob'))
 }

 async function downloadDeliveryInvoiceImageFiles(filename, invoices) {
   const invoiceList = Array.isArray(invoices) ? invoices : []
   if (!invoiceList.length) throw new Error('No invoices are available for image export.')
   const imageFiles = []
   for (let idx = 0; idx < invoiceList.length; idx++) {
     const invoice = invoiceList[idx]
     const canvas = await renderDeliveryInvoicePageCanvas(invoice)
     const blob = await invoiceCanvasToBlob(canvas)
     const invoiceNumber = invoice?.invoice_number || invoice?.id || `Invoice_${idx + 1}`
     imageFiles.push({
       name:`${String(idx + 1).padStart(2, '0')}_${sanitizeWordFileName(invoiceNumber)}.png`,
       data:new Uint8Array(await blob.arrayBuffer())
     })
   }

   if (imageFiles.length === 1) {
     downloadGeneratedInvoiceFile(`${filename}.png`, new Blob([imageFiles[0].data], { type:'image/png' }))
     return
   }
   const zipBlob = createStoredZipBlob(imageFiles, 'application/zip')
   downloadGeneratedInvoiceFile(`${filename}.zip`, zipBlob)
 }


 
 function buildDeliveryInvoiceWordImageDrawing(relId, drawingId) {
   const widthEmu = 4 * 914400
   const heightEmu = 6 * 914400
   return `<w:r><w:drawing><wp:anchor xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" distT="0" distB="0" distL="0" distR="0" simplePos="0" relativeHeight="251658240" behindDoc="0" locked="1" layoutInCell="1" allowOverlap="1"><wp:simplePos x="0" y="0"/><wp:positionH relativeFrom="page"><wp:posOffset>0</wp:posOffset></wp:positionH><wp:positionV relativeFrom="page"><wp:posOffset>0</wp:posOffset></wp:positionV><wp:extent cx="${widthEmu}" cy="${heightEmu}"/><wp:effectExtent l="0" t="0" r="0" b="0"/><wp:wrapNone/><wp:docPr id="${drawingId}" name="Roma's Donuts Invoice ${drawingId}"/><wp:cNvGraphicFramePr><a:graphicFrameLocks xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" noChangeAspect="1"/></wp:cNvGraphicFramePr><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="${drawingId}" name="Invoice ${drawingId}"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="${relId}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${widthEmu}" cy="${heightEmu}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:anchor></w:drawing></w:r>`
 }

 async function downloadDeliveryInvoiceWordImageFile(filename, invoices) {
   const invoiceList = Array.isArray(invoices) ? invoices : []
   if (!invoiceList.length) throw new Error('No invoices are available for Word export.')

   const imageFiles = []
   for (let idx = 0; idx < invoiceList.length; idx++) {
     const canvas = await renderDeliveryInvoicePageCanvas(invoiceList[idx])
     const blob = await invoiceCanvasToBlob(canvas)
     imageFiles.push(new Uint8Array(await blob.arrayBuffer()))
   }

   const bodyXml = imageFiles.map((_, idx) => {
     const pageBreak = idx > 0 ? '<w:pageBreakBefore/>' : ''
     return `<w:p><w:pPr>${pageBreak}<w:spacing w:before="0" w:after="0" w:line="1" w:lineRule="exact"/></w:pPr>${buildDeliveryInvoiceWordImageDrawing(`rIdInvoice${idx + 1}`, idx + 1)}</w:p>`
   }).join('')

   // True 4 x 6 inch portrait pages. Each page contains one full-page PNG,
   // so Microsoft Word cannot reflow the invoice table or crop its bottom rows.
   const documentXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body>${bodyXml}<w:sectPr><w:pgSz w:w="5760" w:h="8640"/><w:pgMar w:top="0" w:right="0" w:bottom="0" w:left="0" w:header="0" w:footer="0" w:gutter="0"/><w:cols w:space="0"/><w:docGrid w:linePitch="360"/></w:sectPr></w:body></w:document>`
   const contentTypes = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/word/settings.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml"/></Types>`
   const rootRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`
   const imageRelationships = imageFiles.map((_, idx) => `<Relationship Id="rIdInvoice${idx + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/invoice-${idx + 1}.png"/>`).join('')
   const docRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/>${imageRelationships}</Relationships>`
   const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:pPrDefault><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr></w:pPrDefault></w:docDefaults></w:styles>`
   const settings = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:settings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:zoom w:percent="100"/><w:doNotAutoCompressPictures/><w:compat><w:compatSetting w:name="compatibilityMode" w:uri="http://schemas.microsoft.com/office/word" w:val="15"/></w:compat></w:settings>`

   const files = [
     { name:'[Content_Types].xml', data:contentTypes },
     { name:'_rels/.rels', data:rootRels },
     { name:'word/document.xml', data:documentXml },
     { name:'word/_rels/document.xml.rels', data:docRels },
     { name:'word/styles.xml', data:styles },
     { name:'word/settings.xml', data:settings }
   ]
   imageFiles.forEach((data, idx) => files.push({ name:`word/media/invoice-${idx + 1}.png`, data }))

   const docxBlob = createStoredZipBlob(files, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document')
   downloadGeneratedInvoiceFile(`${filename}.docx`, docxBlob)
 }

function buildPayslipDocxTable(pay, payrollStart, payrollEnd, idx = 0) {
   const data = normalizePayslipForPrint(pay || {})
   const serialNo = data.payslipSerial || genSerial(String(payrollStart || data.payrollStart || getTodayDate()), idx)
   const start = payrollStart || data.payrollStart || ''
   const end = payrollEnd || data.payrollEnd || ''
   const basicPay = safeNum(data.workedBasicPay || data.basicPay, 0)

   // Keep the exact reseller-invoice printable width and physical paper size.
   // The right column is widened so serial numbers, positions, amounts, and
   // signature labels remain fully visible in Microsoft Word.
   const widths = [3180, 2340]
   const full = widths[0] + widths[1]

   // Minimal Roma's Donuts branding: red title/outer border, a restrained
   // gold employee-name accent, and neutral black/gray document sections.
   const BLACK = '1F1F1F'
   const DARK_GRAY = '404040'
   const LINE_GRAY = 'A6A6A6'
   const LIGHT_GRAY = 'E7E6E6'
   const VERY_LIGHT_GRAY = 'F5F5F5'
   const WHITE = 'FFFFFF'
   const BRAND_RED = 'CA1B1B'
   const BRAND_GOLD = 'FDD412'
   const PALE_GOLD = 'FFF4C4'

   // SIL is intentionally not named on the printed payslip. When a paid-leave
   // amount exists, it is still included under Other Earnings so the printed
   // breakdown remains mathematically consistent with Total Earnings.
   const otherEarningsForPrint =
     safeNum(data.adjustmentEarnings, 0) +
     safeNum(data.paidLeavePay, 0)
   const adjustmentAdditionItems = data.adjustmentAdditionItems || []
   const adjustmentDeductionItems = data.adjustmentDeductionItems || []
   const cashAdvanceItems = data.cashAdvanceItems || []

   const rows = []
   const addAmountRow = (label, amount, options = {}) => {
     const estimatedLines = Math.max(1, Math.ceil(String(label || '').length / 52))
     rows.push(wordRow([
       wordCell(label, {
         width:widths[0],
         align:'left',
         bold:options.boldLabel === true,
         size:options.size || 16,
         shade:options.shade || '',
         color:options.color || ''
       }),
       wordCell(php(safeNum(amount, 0)), {
         width:widths[1],
         align:'right',
         bold:true,
         size:options.amountSize || options.size || 16,
         shade:options.shade || '',
         color:options.amountColor || options.color || '',
         padRight:150
       })
     ], Math.max(options.height || 275, estimatedLines * 235)))
   }

   rows.push(wordRow([
     wordCell("ROMA'S DONUTS  |  EMPLOYEE PAYSLIP", {
       width:full,
       span:2,
       align:'center',
       bold:true,
       size:20,
       line:240,
       shade:BRAND_RED,
       color:WHITE
     })
   ], 390))

   rows.push(wordRow([
     wordCell(`PAY PERIOD: ${formatDateForDisplay(start)} - ${formatDateForDisplay(end)}`, {
       width:widths[0], align:'left', bold:true, size:15, shade:VERY_LIGHT_GRAY
     }),
     wordCell(`SERIAL: ${serialNo || '-'}`, {
       width:widths[1], align:'right', bold:true, size:13, shade:VERY_LIGHT_GRAY, padRight:150
     })
   ], 310))

   rows.push(wordRow([
     wordCell(data.employeeName || 'Employee', {
       width:full, span:2, align:'center', bold:true, size:20, shade:PALE_GOLD, color:BLACK
     })
   ], 320))

   rows.push(wordRow([
     wordCell(`EMPLOYEE CODE: ${data.employeeCode || '-'}`, {
       width:widths[0], align:'left', bold:false, size:15
     }),
     wordCell(`POSITION: ${data.position || '-'}`, {
       width:widths[1], align:'right', bold:false, size:13, padRight:150
     })
   ], 310))

   rows.push(wordRow([
     wordCell('ATTENDANCE / PAYROLL BASIS', {
       width:full, span:2, align:'center', bold:true, size:17, shade:LIGHT_GRAY, color:BRAND_RED
     })
   ], 280))

   rows.push(wordRow([
     wordCell(`WORKED: ${data.workedDays}  |  ABSENT: ${data.absentDays}`, {
       width:widths[0], align:'left', bold:false, size:15, shade:VERY_LIGHT_GRAY
     }),
     wordCell(`OT: ${data.overtimeMinutes} MIN  |  ND: ${data.nightDiffMinutes} MIN`, {
       width:widths[1], align:'right', bold:false, size:13, shade:VERY_LIGHT_GRAY, padRight:150
     })
   ], 350))

   rows.push(wordRow([
     wordCell('EARNINGS', {
       width:full, span:2, align:'center', bold:true, size:17, shade:LIGHT_GRAY, color:BRAND_RED
     })
   ], 280))

   addAmountRow(`Basic / Regular Pay (${data.workedDays} paid day(s))`, basicPay)
   addAmountRow(`Overtime Pay (${data.overtimeMinutes} min)`, data.overtimePay)
   addAmountRow(`Night Differential Pay (${data.nightDiffMinutes} min)`, data.nightDiffPay)
   addAmountRow('Holiday Pay', data.holidayPay)
   addAmountRow('Birthday Pay', data.birthdayPay)
   if (adjustmentAdditionItems.length > 0) {
     adjustmentAdditionItems.forEach(item => addAmountRow(`${getPayslipBreakdownLabel(item, 'Payroll Addition')}${getPayslipBreakdownNote(item) ? ` — ${getPayslipBreakdownNote(item)}` : ''}`, item.amount))
     if (safeNum(data.unitemizedAdjustmentEarnings, 0) > 0) addAmountRow('Other Earnings (unitemized legacy amount)', data.unitemizedAdjustmentEarnings)
     if (safeNum(data.paidLeavePay, 0) > 0) addAmountRow('Paid Leave Pay', data.paidLeavePay)
   } else {
     addAmountRow('Other Earnings / Adjustments', otherEarningsForPrint)
   }
   addAmountRow('TOTAL EARNINGS / GROSS PAY', data.totalEarnings, {
     shade:LIGHT_GRAY, boldLabel:true, size:17, height:310, color:BLACK
   })

   rows.push(wordRow([
     wordCell('DEDUCTIONS', {
       width:full, span:2, align:'center', bold:true, size:17, shade:LIGHT_GRAY, color:BRAND_RED
     })
   ], 280))

   addAmountRow(`Late Deduction (${data.lateMinutes} min)`, data.lateDeduction)
   addAmountRow(`Undertime Deduction (${data.undertimeMinutes} min)`, data.undertimeDeduction)
   addAmountRow('Excess Break Deduction', data.excessBreakDeduction)
   if (cashAdvanceItems.length > 0) cashAdvanceItems.forEach(item => addAmountRow(`${getPayslipBreakdownLabel(item, 'Cash Advance')}${getPayslipBreakdownNote(item) ? ` — ${getPayslipBreakdownNote(item)}` : ''}`, item.amount))
   else addAmountRow('Cash Advance Deduction', data.cashAdvanceDeduction)
   addAmountRow('Absence / Unpaid Leave Deduction', data.absenceDeduction)
   addAmountRow('Deferred Cash Advance', data.deferredCADeduction)
   addAmountRow('SSS', data.sssDeduction)
   addAmountRow('Pag-IBIG', data.pagibigDeduction)
   addAmountRow('PhilHealth', data.philhealthDeduction)
   if (adjustmentDeductionItems.length > 0) adjustmentDeductionItems.forEach(item => addAmountRow(`${getPayslipBreakdownLabel(item, 'Payroll Deduction')}${getPayslipBreakdownNote(item) ? ` — ${getPayslipBreakdownNote(item)}` : ''}`, item.amount))
   if (safeNum(data.unitemizedAdjustmentDeductions, 0) > 0 || (safeNum(data.adjustmentDeductions, 0) > 0 && adjustmentDeductionItems.length === 0 && safeNum(data.absenceDeduction, 0) <= 0)) addAmountRow(adjustmentDeductionItems.length > 0 || safeNum(data.absenceDeduction, 0) > 0 ? 'Other Deduction (unitemized legacy amount)' : 'Other Deductions / Adjustments', data.unitemizedAdjustmentDeductions || data.adjustmentDeductions)
   addAmountRow('TOTAL DEDUCTIONS', data.totalDeductions, {
     shade:LIGHT_GRAY, boldLabel:true, size:17, height:310, color:BLACK
   })

   rows.push(wordRow([
     wordCell('NET PAY / TAKE HOME PAY', {
       width:widths[0], align:'left', bold:true, size:19, shade:BLACK, color:WHITE
     }),
     wordCell(php(data.netPay), {
       width:widths[1], align:'right', bold:true, size:22, shade:BLACK, color:BRAND_GOLD, padRight:150
     })
   ], 420))

   if (data.nonCADeductionOverflow > 0) {
     rows.push(wordRow([
       wordCell(`NOTICE: Non-CA deductions exceeded earnings by ${php(data.nonCADeductionOverflow)}.`, {
         width:full, span:2, align:'center', bold:true, size:13, shade:VERY_LIGHT_GRAY, color:BRAND_RED
       })
     ], 260))
   }

   rows.push(wordRow([
     wordCell('____________________________', {
       width:widths[0], align:'center', bold:false, size:15
     }),
     wordCell('________________________', {
       width:widths[1], align:'center', bold:false, size:15
     })
   ], 340))

   rows.push(wordRow([
     wordCell('EMPLOYEE / DATE', {
       width:widths[0], align:'center', bold:false, size:12
     }),
     wordCell('AUTHORIZED / DATE', {
       width:widths[1], align:'center', bold:false, size:12
     })
   ], 220))

   return `<w:tbl><w:tblPr><w:tblW w:w="${full}" w:type="dxa"/><w:jc w:val="center"/><w:tblLayout w:type="fixed"/><w:tblLook w:firstRow="0" w:lastRow="0" w:firstColumn="0" w:lastColumn="0" w:noHBand="1" w:noVBand="1"/><w:tblBorders><w:top w:val="single" w:sz="14" w:space="0" w:color="${BRAND_RED}"/><w:left w:val="single" w:sz="14" w:space="0" w:color="${BRAND_RED}"/><w:bottom w:val="single" w:sz="14" w:space="0" w:color="${BRAND_RED}"/><w:right w:val="single" w:sz="14" w:space="0" w:color="${BRAND_RED}"/><w:insideH w:val="single" w:sz="6" w:space="0" w:color="${LINE_GRAY}"/><w:insideV w:val="single" w:sz="6" w:space="0" w:color="${LINE_GRAY}"/></w:tblBorders><w:tblCellMar><w:top w:w="0" w:type="dxa"/><w:left w:w="40" w:type="dxa"/><w:bottom w:w="0" w:type="dxa"/><w:right w:w="40" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid><w:gridCol w:w="${widths[0]}"/><w:gridCol w:w="${widths[1]}"/></w:tblGrid>${rows.join('')}</w:tbl>`
 }

 function buildPayslipsDocxDocument(records, payrollStart, payrollEnd) {
   const payslips = Array.isArray(records) ? records : []
   const bodyParts = []
   payslips.forEach((pay, idx) => {
     // Reuse the reseller-invoice page-break strategy so Print All creates
     // one payslip per sheet without blank pages between employees.
     bodyParts.push(buildInvoiceDocxTopSpacer(idx > 0))
     bodyParts.push(buildPayslipDocxTable(pay, payrollStart, payrollEnd, idx))
   })

   // Exact reseller-invoice physical paper size: 105mm x 165mm.
   const MARGIN = 147
   return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body>${bodyParts.join('')}<w:sectPr><w:pgSz w:w="5953" w:h="9354"/><w:pgMar w:top="${MARGIN}" w:right="${MARGIN}" w:bottom="${MARGIN}" w:left="${MARGIN}" w:header="0" w:footer="0" w:gutter="0"/><w:cols w:space="0"/><w:docGrid w:linePitch="360"/></w:sectPr></w:body></w:document>`
 }

 function buildPayslipsDocxBlob(records, payrollStart, payrollEnd) {
   const documentXml = buildPayslipsDocxDocument(records, payrollStart, payrollEnd)
   const contentTypes = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/word/settings.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml"/></Types>`
   const rootRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`
   const docRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/></Relationships>`
   const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:sz w:val="18"/><w:szCs w:val="18"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr></w:pPrDefault></w:docDefaults></w:styles>`
   const settings = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:settings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:zoom w:percent="100"/><w:compat><w:compatSetting w:name="compatibilityMode" w:uri="http://schemas.microsoft.com/office/word" w:val="15"/></w:compat></w:settings>`

   return createStoredZipBlob([
     { name:'[Content_Types].xml', data:contentTypes },
     { name:'_rels/.rels', data:rootRels },
     { name:'word/document.xml', data:documentXml },
     { name:'word/_rels/document.xml.rels', data:docRels },
     { name:'word/styles.xml', data:styles },
     { name:'word/settings.xml', data:settings }
   ], 'application/vnd.openxmlformats-officedocument.wordprocessingml.document')
 }

 function downloadPayslipsDocxFile(filename, records, payrollStart, payrollEnd) {
   const blob = buildPayslipsDocxBlob(records, payrollStart, payrollEnd)
   const url = URL.createObjectURL(blob)
   const link = document.createElement('a')
   link.href = url
   link.download = `${sanitizeWordFileName(filename)}.docx`
   document.body.appendChild(link)
   link.click()
   document.body.removeChild(link)
   setTimeout(() => URL.revokeObjectURL(url), 1500)
 }

 async function getFreshDeliveryInvoicesForPrintByDate(date) {
   const { data, error } = await supabase
     .from('delivery_invoices')
     .select('*, delivery_invoice_items(*)')
     .eq('delivery_date', date)
     .order('created_at', { ascending:false })

   if (error) throw error
  const normalized = await normalizePaidInvoiceRows((data || []).filter(isSalesSummaryInvoiceCounted))
   const withReturns = await attachReturnsToDeliveryInvoices(normalized)
   return withReturns.sort(sortDeliveryInvoicesNewestFirst)
 }

 function validateDeliveryInvoiceForPrint(invoice) {
   if (!invoice?.id || !invoice?.invoice_number) {
     return 'This invoice is not a saved database invoice yet. Refresh the invoice list and print only from the saved Delivery Invoices list.'
   }

   const rows = invoice.delivery_invoice_items || []
   if (!rows.length) {
     return 'This invoice has no saved line items. Refresh the invoice list before printing.'
   }

   const itemTotal = moneyRound(rows.reduce((sum, item) => sum + safeNum(item.total_price, safeNum(item.quantity,0) * safeNum(item.reseller_price,0)), 0))
   const headerTotal = moneyRound(invoice.total_amount ?? invoice.subtotal ?? 0)
   if (Math.abs(itemTotal - headerTotal) > 0.01) {
     return `Invoice total mismatch. Saved header is ${php(headerTotal)} but saved item rows total ${php(itemTotal)}. Please edit/recalculate the invoice before printing.`
   }

   return ''
 }

