 // Driver Return Form 
 function initDriverReturn(invoice) {
 const items = (invoice.delivery_invoice_items||[]).map(i=>({
 variant_id: i.variant_id, variant_name: i.variant_name,
 delivered_qty: Number(i.quantity||0), returned_qty: '', reseller_price: Number(i.reseller_price||0)
 }))
 setDriverReturnItems(items)
 setShowDriverReturnForm(invoice)
 }
 async function saveDriverReturn() {
 const invoice = showDriverReturnForm
 if (!invoice) return
 const validItems = driverReturnItems.filter(i=>Number(i.returned_qty)>0)
 setSavingDriverReturn(true)
 try {
 const totalCredit = validItems.reduce((s,i)=>s+Number(i.returned_qty)*i.reseller_price,0)
 // Save return record
 const { data:ret, error:retErr } = await supabase.from('reseller_returns').insert({
 invoice_id:invoice.id, reseller_id:invoice.reseller_id, reseller_name:invoice.reseller_name,
 return_date:today, total_returned_amount:totalCredit, recorded_by:adminRole, notes:'Driver return'
 }).select().single()
 if (retErr) throw retErr
 if (validItems.length > 0) {
 await supabase.from('reseller_return_items').insert(validItems.map(i=>({
 return_id:ret.id, variant_id:i.variant_id, variant_name:i.variant_name,
 returned_quantity:Number(i.returned_qty), reseller_price:i.reseller_price,
 total_credit:Number(i.returned_qty)*i.reseller_price
 })))
 }
 // Adjust invoice total
 const newTotal = Math.max(0, Number(invoice.total_amount||0) - totalCredit)
 await supabase.from('delivery_invoices').update({
 total_amount:newTotal, status:'delivered',
 notes:(invoice.notes?invoice.notes+' | ':'')+'Driver returns: '+today
 }).eq('id', invoice.id)
 // Check vs reseller portal returns for discrepancy
 const { data:resellerReturn } = await supabase.from('reseller_returns').select('*, reseller_return_items(*)').eq('invoice_id', invoice.id).neq('id', ret.id).maybeSingle()
 if (resellerReturn) {
 const driverTotal = validItems.reduce((s,i)=>s+Number(i.returned_qty||0),0)
 const resellerTotal = (resellerReturn.reseller_return_items||[]).reduce((s,i)=>s+Number(i.returned_quantity||0),0)
 if (Math.abs(driverTotal-resellerTotal)>0) {
 await supabase.from('suspicious_alerts').insert({ alert_type:'return_discrepancy', severity:'high', description:`Return discrepancy for ${invoice.reseller_name} Invoice ${invoice.invoice_number}. Driver reported ${driverTotal} pcs returned, Reseller reported ${resellerTotal} pcs.`, related_to:invoice.reseller_name })
 await createNotification(null,'System','alert',' Return Discrepancy Alert',`${invoice.reseller_name}: Driver says ${driverTotal} pcs returned, Reseller portal says ${resellerTotal} pcs. Please verify!`)
 showToast(` Returns saved but DISCREPANCY detected vs reseller portal! Check alerts.`)
 } else { showToast(` Returns saved! Credit: ${php(totalCredit)}. Matches reseller count `) }
 } else { showToast(` Returns saved! Credit: ${php(totalCredit)}`) }
 await logAudit('DRIVER RETURNS', adminRole, invoice.reseller_name, `${invoice.invoice_number} ${validItems.length} variants, credit: ${php(totalCredit)}`)
 setShowDriverReturnForm(null); setDriverReturnItems([])
 loadDeliveryInvoices(); refreshFoundationAfterDataChange('driver-return-saved')
 } catch(err) { showToast(' Failed: '+err.message,'red') }
 setSavingDriverReturn(false)
 }

 // Print Cash Collection Summary 
 function printCashCollection(date) {
 const dayInvoices = deliveryInvoices.filter(i=>i.delivery_date===date||i.paid_date===date)
 const pw = window.open('','_blank','width=700,height=600')
 const totalCollected = dayInvoices.reduce((s,i)=>s+Number(i.paid_amount||0),0)
 const totalReturns = dayInvoices.reduce((s,i)=>s+Math.max(0,(Number(i.original_amount||i.total_amount||0))-Number(i.total_amount||0)),0)
 const totalNet = dayInvoices.reduce((s,i)=>s+Number(i.total_amount||0),0)
 pw.document.write(`<!DOCTYPE html><html><head><title>Cash Collection</title>
 <style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,sans-serif;font-size:10px;width:150mm;}
 @media print{@page{size:150mm 210mm;margin:5mm;}html,body{width:150mm;}.no-print{display:none!important;}}
.wrap{padding:6mm;}h1{font-size:13px;color:#ca1b1b;}
 table{width:100%;border-collapse:collapse;margin:8px 0;}th{background:#2d8a4e;color:white;padding:5px 6px;font-size:9px;text-align:left;}
 td{padding:4px 6px;border-bottom:1px solid #eee;font-size:9px;}
.total{background:#fff9e6;font-weight:bold;border-top:2px solid #ca1b1b;}
.sig{border-top:1px solid #000;margin-top:28px;padding-top:4px;font-size:8px;text-align:center;}
 </style></head><body><div class="wrap">
 <div style="display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #ca1b1b;padding-bottom:6px;margin-bottom:8px;">
 <div><h1>Roma's Donuts</h1><div style="font-size:8px;color:#888;">DAILY CASH COLLECTION SUMMARY</div></div>
 <div style="text-align:right;font-size:8px;"><strong>${date}</strong></div>
 </div>
 <table>
 <tr><th>Reseller</th><th style="text-align:right">Invoice</th><th style="text-align:right">Returns</th><th style="text-align:right">Net Due</th><th style="text-align:right">Collected</th><th style="text-align:right">Balance</th><th>Mode</th></tr>
 ${dayInvoices.map(i=>{
 const orig = Number(i.original_amount||i.total_amount||0)
 const ret = Math.max(0,orig-Number(i.total_amount||0))
 const net = Number(i.total_amount||0)
 const collected = Number(i.paid_amount||0)
 const balance = net-collected
 return `<tr><td><strong>${i.reseller_name}</strong></td><td style="text-align:right"> ${orig.toFixed(2)}</td><td style="text-align:right;color:#ca1b1b">${ret>0?' '+ret.toFixed(2):' '}</td><td style="text-align:right;font-weight:bold"> ${net.toFixed(2)}</td><td style="text-align:right;color:#2d8a4e;font-weight:bold">${collected>0?' '+collected.toFixed(2):'___'}</td><td style="text-align:right;color:${balance>0?'#ca1b1b':'#2d8a4e'}">${balance>0?' '+balance.toFixed(2):' '}</td><td>${i.payment_method||'Cash'}</td></tr>`
 }).join('')}
 <tr class="total"><td>TOTAL</td><td style="text-align:right"> ${dayInvoices.reduce((s,i)=>s+Number(i.original_amount||i.total_amount||0),0).toFixed(2)}</td><td style="text-align:right"> ${totalReturns.toFixed(2)}</td><td style="text-align:right"> ${totalNet.toFixed(2)}</td><td style="text-align:right;color:#2d8a4e"> ${totalCollected.toFixed(2)}</td><td style="text-align:right;color:${totalNet-totalCollected>0?'#ca1b1b':'#2d8a4e'}"> ${(totalNet-totalCollected).toFixed(2)}</td><td></td></tr>
 </table>
 <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px;">
 <div class="sig">Prepared by (Admin)<br/><br/>_______________</div>
 <div class="sig">Checked by (Owner)<br/><br/>_______________</div>
 </div>
 <div class="no-print" style="text-align:center;margin-top:14px;"><button onclick="window.print()" style="padding:8px 20px;background:#2d8a4e;color:white;border:none;border-radius:6px;cursor:pointer;"> PRINT</button></div>
 </div></body></html>`)
 pw.document.close(); setTimeout(()=>{ pw.focus(); pw.print() },500)
 }

 function buildInvoiceSettlementRows(inv) {
 const items = inv?.delivery_invoice_items || []
 return items.map(item => {
 const qty = Math.max(0, safeNum(item.quantity, 0))
 const price = moneyRound(item.reseller_price ?? item.unit_price ?? 0)
 return { item_id:item.id || null, variant_id:item.variant_id || '', variant_name:item.variant_name || 'Unknown Variant', original_quantity:qty, actual_quantity:qty, returned_quantity:0, reseller_price:price, retail_price:moneyRound(item.retail_price ?? price) }
 })
 }

 async function openInvoiceSettlement(inv) {
 if (showPaymentFormMap[inv.id]) { setShowPaymentFormMap(p=>({...p,[inv.id]:false})); return }
 let rows = buildInvoiceSettlementRows(inv)
 try {
 const { data } = await supabase.from('reseller_returns').select('id, reseller_return_items(*)').eq('invoice_id', inv.id)
 const returned = {}
 ;(data || []).forEach(r => (r.reseller_return_items || []).forEach(i => {
 const key = String(i.variant_id || i.variant_name || '')
 returned[key] = safeNum(returned[key], 0) + safeNum(i.returned_quantity, 0)
 }))
 rows = rows.map(r => {
 const key = String(r.variant_id || r.variant_name || '')
 return {...r, returned_quantity:Math.min(safeNum(r.actual_quantity,0), safeNum(returned[key],0))}
 })
 } catch(e) { console.warn('openInvoiceSettlement existing returns:', e) }
 let crateDefaults = {
 delivered:safeNum(inv.crates_used ?? inv.crates ?? inv.crate_count ?? inv.total_crates, 0) || '',
 returned:'',
 coverDelivered:'',
 coverReturned:'',
 dispatcher:'',
 driver:'',
 notes:''
 }
 try {
 const { data:invoiceCrates, error:crateErr } = await supabase
 .from('crate_movements')
 .select('*')
 .eq('invoice_id', inv.id)
 .eq('is_deleted', false)
 if (!crateErr && Array.isArray(invoiceCrates) && invoiceCrates.length) {
 const releasedRows = invoiceCrates.filter(m => getCrateMovementSignedQty(m) > 0)
 const collectedRows = invoiceCrates.filter(m => getCrateMovementSignedQty(m) < 0)
 const crateReleasedRows = releasedRows.filter(m => getCrateAssetType(m) === 'crate')
 const crateCollectedRows = collectedRows.filter(m => getCrateAssetType(m) === 'crate')
 const coverReleasedRows = releasedRows.filter(m => getCrateAssetType(m) === 'cover')
 const coverCollectedRows = collectedRows.filter(m => getCrateAssetType(m) === 'cover')
 const delivered = crateReleasedRows.reduce((sum,m)=>sum + safeNum(m.quantity,0),0)
 const returned = crateCollectedRows.reduce((sum,m)=>sum + safeNum(m.quantity,0),0)
 const coverDelivered = coverReleasedRows.reduce((sum,m)=>sum + safeNum(m.quantity,0),0)
 const coverReturned = coverCollectedRows.reduce((sum,m)=>sum + safeNum(m.quantity,0),0)
 const latestReleased = releasedRows[0] || {}
 const latestCollected = collectedRows[0] || {}
 crateDefaults = {
 delivered:delivered || '',
 returned:returned || '',
 coverDelivered:coverDelivered || '',
 coverReturned:coverReturned || '',
 dispatcher:latestReleased.dispatcher_name || '',
 driver:latestCollected.driver_name || '',
 notes:[latestReleased.notes, latestCollected.notes].filter(Boolean).join(' | ').slice(0, 180)
 }
 }
 } catch(e) { console.warn('openInvoiceSettlement existing crates:', e) }
 setSettlementRows(p=>({...p,[inv.id]:rows}))
 setSettlementCrates(p=>({...p,[inv.id]:crateDefaults}))
 setPaymentAmount(p=>({...p,[inv.id]:p[inv.id] || ''}))
 setPaymentMethod(p=>({...p,[inv.id]:p[inv.id] || 'Cash'}))
 setPaymentNotes(p=>({...p,[inv.id]:p[inv.id] || ''}))
 setShowPaymentFormMap(p=>({...p,[inv.id]:true}))
 }

 function updateSettlementRow(invoiceId, idx, field, value) {
 setSettlementRows(prev => {
 const rows = [...(prev[invoiceId] || [])]
 const row = {...rows[idx], [field]:value}
 const actual = Math.max(0, safeNum(field === 'actual_quantity'? value: row.actual_quantity, 0))
 const returned = Math.max(0, safeNum(field === 'returned_quantity'? value: row.returned_quantity, 0))
 if (field === 'actual_quantity' && returned > actual) row.returned_quantity = actual
 if (field === 'returned_quantity' && returned > actual) row.returned_quantity = actual
 rows[idx] = row
 return {...prev, [invoiceId]:rows}
 })
 }

 function updateSettlementCrates(invoiceId, field, value) {
 setSettlementCrates(prev => {
 const current = prev[invoiceId] || { delivered:'', returned:'', coverDelivered:'', coverReturned:'', dispatcher:'', driver:'', notes:'' }
 return {...prev, [invoiceId]:{...current, [field]:value }}
 })
 }

 function getSettlementCrateSummary(inv) {
 const data = settlementCrates[inv.id] || {}
 const delivered = Math.max(0, safeNum(data.delivered, 0))
 const returned = Math.max(0, safeNum(data.returned, 0))
 const coverDelivered = Math.max(0, safeNum(data.coverDelivered, 0))
 const coverReturned = Math.max(0, safeNum(data.coverReturned, 0))
 const variance = moneyRound(delivered - returned)
 const coverVariance = moneyRound(coverDelivered - coverReturned)
 const invoiceMovements = (crateMovements || []).filter(m => String(m.invoice_id || '') === String(inv.id) && m.is_deleted !== true)
 const existingNet = invoiceMovements.filter(m => getCrateAssetType(m) === 'crate').reduce((sum,m)=>sum + getCrateMovementSignedQty(m),0)
 const existingCoverNet = invoiceMovements.filter(m => getCrateAssetType(m) === 'cover').reduce((sum,m)=>sum + getCrateMovementSignedQty(m),0)
 const resellerRow = getCrateBalanceRows(true).find(r => String(r.reseller_id) === String(inv.reseller_id || ''))
 const currentBalance = safeNum(resellerRow?.crateBalance ?? resellerRow?.balance, 0)
 const currentCoverBalance = safeNum(resellerRow?.coverBalance, 0)
 const projectedBalance = moneyRound(currentBalance - existingNet + variance)
 const projectedCoverBalance = moneyRound(currentCoverBalance - existingCoverNet + coverVariance)
 const statusParts = []
 statusParts.push(variance > 0 ? `${variance} crates unreturned` : variance < 0 ? `${Math.abs(variance)} extra crates returned` : 'Crates clear')
 statusParts.push(coverVariance > 0 ? `${coverVariance} covers unreturned` : coverVariance < 0 ? `${Math.abs(coverVariance)} extra covers returned` : 'Covers clear')
 return {
 delivered,
 returned,
 coverDelivered,
 coverReturned,
 variance,
 coverVariance,
 existingNet,
 existingCoverNet,
 currentBalance,
 currentCoverBalance,
 projectedBalance,
 projectedCoverBalance,
 hasEntry:delivered > 0 || returned > 0 || coverDelivered > 0 || coverReturned > 0,
 status:statusParts.join(' / ')
 }
 }

 async function syncInvoiceSettlementCrates(inv) {
 const data = settlementCrates[inv.id] || {}
 const summary = getSettlementCrateSummary(inv)
 if (!summary.hasEntry) return { ok:true, saved:false }
 if (!inv.reseller_id && !inv.reseller_name) return { ok:false, saved:false, error:'Invoice has no reseller link.' }
 const reseller = getResellerRecordById(inv.reseller_id) || { id:inv.reseller_id || null, name:inv.reseller_name || 'Customer' }
 const deliveryDate = String(inv.delivery_date || inv.invoice_date || today).slice(0,10)
 const staffName = adminEmployee?.full_name || adminRole || 'Admin'
 const baseNotes = String(data.notes || '').trim()
 const replaceNote = `Replaced by one-click settlement on ${today}`

 const { error:oldErr } = await supabase
 .from('crate_movements')
 .update({ is_deleted:true, notes:replaceNote })
 .eq('invoice_id', inv.id)
 .in('movement_type', ['dispatch','collection','released','returned','return','settlement_dispatch','settlement_collection'])
 .eq('is_deleted', false)
 if (oldErr) throw oldErr

 const base = {
 related_delivery_date:deliveryDate,
 reseller_id:reseller.id || null,
 reseller_name:reseller.name || inv.reseller_name || '',
 invoice_id:inv.id,
 invoice_number:inv.invoice_number || '',
 recorded_by:staffName,
 is_deleted:false
 }
 const payloads = []
 if (summary.delivered > 0) payloads.push({
 ...base,
 movement_date:deliveryDate,
 movement_type:'settlement_dispatch',
 direction:'out',
 quantity:summary.delivered,
 asset_type:'crate',
 dispatcher_name:String(data.dispatcher || '').trim(),
 driver_name:'',
 notes:[`One-click settlement: crates delivered/released for ${inv.invoice_number || 'invoice'}.`, baseNotes].filter(Boolean).join(' ')
 })
 if (summary.returned > 0) payloads.push({
 ...base,
 movement_date:today,
 movement_type:'settlement_collection',
 direction:'in',
 quantity:summary.returned,
 asset_type:'crate',
 dispatcher_name:'',
 driver_name:String(data.driver || '').trim(),
 notes:[`One-click settlement: crates returned/collected for ${inv.invoice_number || 'invoice'}.`, baseNotes].filter(Boolean).join(' ')
 })
 if (summary.coverDelivered > 0) payloads.push({
 ...base,
 movement_date:deliveryDate,
 movement_type:'settlement_dispatch',
 direction:'out',
 quantity:summary.coverDelivered,
 asset_type:'cover',
 dispatcher_name:String(data.dispatcher || '').trim(),
 driver_name:'',
 notes:[`One-click settlement: crate covers delivered/released for ${inv.invoice_number || 'invoice'}.`, baseNotes].filter(Boolean).join(' ')
 })
 if (summary.coverReturned > 0) payloads.push({
 ...base,
 movement_date:today,
 movement_type:'settlement_collection',
 direction:'in',
 quantity:summary.coverReturned,
 asset_type:'cover',
 dispatcher_name:'',
 driver_name:String(data.driver || '').trim(),
 notes:[`One-click settlement: crate covers returned/collected for ${inv.invoice_number || 'invoice'}.`, baseNotes].filter(Boolean).join(' ')
 })
 if (!payloads.length) return { ok:true, saved:false }
 const { error:insertErr } = await supabase.from('crate_movements').insert(payloads)
 if (insertErr) throw insertErr
 return { ok:true, saved:true, summary }
 }

 function getSettlementSummary(inv, rowsArg = null) {
 const rows = rowsArg || settlementRows[inv.id] || buildInvoiceSettlementRows(inv)
 const out = { originalQty:0, actualQty:0, returnedQty:0, billableQty:0, originalGross:0, adjustedGross:0, returnsCredit:0, finalTotal:0 }
 rows.forEach(row => {
 const originalQty = Math.max(0, safeNum(row.original_quantity, 0))
 const actualQty = Math.max(0, safeNum(row.actual_quantity, 0))
 const returnedQty = Math.min(actualQty, Math.max(0, safeNum(row.returned_quantity, 0)))
 const billableQty = Math.max(0, actualQty - returnedQty)
 const price = moneyRound(row.reseller_price || 0)
 out.originalQty += originalQty
 out.actualQty += actualQty
 out.returnedQty += returnedQty
 out.billableQty += billableQty
 out.originalGross = moneyRound(out.originalGross + originalQty * price)
 out.adjustedGross = moneyRound(out.adjustedGross + actualQty * price)
 out.returnsCredit = moneyRound(out.returnsCredit + returnedQty * price)
 out.finalTotal = moneyRound(out.finalTotal + billableQty * price)
 })
 const alreadyPaid = moneyRound(inv.paid_amount || 0)
 const cashReceived = moneyRound(paymentAmount[inv.id] || 0)
 const dueBeforeCash = moneyRound(Math.max(0, out.finalTotal - alreadyPaid))
 const newPaidTotal = moneyRound(Math.min(out.finalTotal, alreadyPaid + cashReceived))
 const finalBalance = moneyRound(Math.max(0, out.finalTotal - newPaidTotal))
 const newStatus = finalBalance <= 0 ? 'paid' : newPaidTotal > 0 ? 'partial' : (String(inv.status || '').toLowerCase() === 'delivered' ? 'delivered' : 'unpaid')
 return {...out, alreadyPaid, cashReceived, dueBeforeCash, newPaidTotal, finalBalance, newStatus}
 }

 async function saveInvoiceSettlement(inv) {
 const rows = (settlementRows[inv.id] || buildInvoiceSettlementRows(inv)).map(row => {
 const actual = Math.max(0, safeNum(row.actual_quantity, 0))
 const returned = Math.min(actual, Math.max(0, safeNum(row.returned_quantity, 0)))
 const price = moneyRound(row.reseller_price || 0)
 return {...row, actual_quantity:actual, returned_quantity:returned, billable_quantity:Math.max(0, actual - returned), total_price:moneyRound(actual * price), return_credit:moneyRound(returned * price)}
 })
 if (!rows.length) { showToast(' No invoice items found for settlement.', 'red'); return }
 const summary = getSettlementSummary(inv, rows)
 const crateSummary = getSettlementCrateSummary(inv)
 if (summary.cashReceived - summary.dueBeforeCash > 0.01) { showToast(` Cash received exceeds final balance of ${php(summary.dueBeforeCash)}.`, 'red'); return }
 setSettlementSaving(p=>({...p,[inv.id]:true}))
 let paymentId = null
 let crateSyncResult = { ok:true, saved:false }
 try {
 const { data:oldReturns } = await supabase.from('reseller_returns').select('id').eq('invoice_id', inv.id)
 const oldIds = (oldReturns || []).map(r => r.id).filter(Boolean)
 if (oldIds.length) { await supabase.from('reseller_return_items').delete().in('return_id', oldIds); await supabase.from('reseller_returns').delete().in('id', oldIds) }
 const returnedRows = rows.filter(r => safeNum(r.returned_quantity,0) > 0)
 if (returnedRows.length) {
 const { data:ret, error:retErr } = await supabase.from('reseller_returns').insert({ invoice_id:inv.id, reseller_id:inv.reseller_id, reseller_name:inv.reseller_name, return_date:today, total_returned_amount:summary.returnsCredit, recorded_by:adminRole, notes:`Recorded inside payment settlement. Actual ${summary.actualQty} pcs, returns ${summary.returnedQty} pcs.` }).select().single()
 if (retErr) throw retErr
 const { error:itemRetErr } = await supabase.from('reseller_return_items').insert(returnedRows.map(r => ({ return_id:ret.id, variant_id:r.variant_id || null, variant_name:r.variant_name, returned_quantity:safeNum(r.returned_quantity,0), reseller_price:safeNum(r.reseller_price,0), total_credit:safeNum(r.return_credit,0) })))
 if (itemRetErr) throw itemRetErr
 }
 for (const row of rows) {
 if (!row.item_id) continue
 const { error:itemErr } = await supabase.from('delivery_invoice_items').update({ quantity:safeNum(row.actual_quantity,0), total_price:safeNum(row.total_price,0) }).eq('id', row.item_id)
 if (itemErr) throw itemErr
 }
 if (summary.cashReceived > 0) {
 const { data:payRows, error:payErr } = await supabase.from('reseller_payments').insert({ reseller_id:inv.reseller_id, reseller_name:inv.reseller_name, invoice_id:inv.id, amount:summary.cashReceived, payment_date:today, payment_method:paymentMethod[inv.id] || 'Cash', notes:paymentNotes[inv.id] || `Settlement for ${inv.invoice_number}`, recorded_by:adminRole }).select('id')
 if (payErr) throw payErr
 paymentId = Array.isArray(payRows) ? payRows[0]?.id : payRows?.id
 }
 const note = `Settlement ${today}: actual delivered ${summary.actualQty} pcs, returns ${summary.returnedQty} pcs, final payable ${php(summary.finalTotal)}, cash received ${php(summary.cashReceived)}, balance ${php(summary.finalBalance)}.`
 const invoiceUpdate = { subtotal:summary.adjustedGross, total_amount:summary.finalTotal, paid_amount:summary.newPaidTotal, paid_date:summary.newStatus === 'paid' ? today : null, status:summary.newStatus, returns_amount:summary.returnsCredit, returns_qty:summary.returnedQty, notes:[inv.notes, note].filter(Boolean).join(' | ') }
 let { error:invoiceErr } = await supabase.from('delivery_invoices').update(invoiceUpdate).eq('id', inv.id)
 if (invoiceErr && String(invoiceErr.message || '').toLowerCase().includes('column')) {
 const fallback = {...invoiceUpdate}; delete fallback.returns_amount; delete fallback.returns_qty
 ;({ error:invoiceErr } = await supabase.from('delivery_invoices').update(fallback).eq('id', inv.id))
 }
 if (invoiceErr) throw invoiceErr
 if (crateSummary.hasEntry) {
 try {
 crateSyncResult = await syncInvoiceSettlementCrates(inv)
 } catch(crateErr) {
 console.warn('syncInvoiceSettlementCrates:', crateErr)
 crateSyncResult = { ok:false, saved:false, error:crateErr?.message || String(crateErr) }
 }
 }
 const crateAuditText = crateSummary.hasEntry ? `, crates delivered ${crateSummary.delivered}, crates returned ${crateSummary.returned}, crate variance ${crateSummary.variance}` : ''
 await logAudit('INVOICE SETTLED', adminRole, inv.reseller_name, `${inv.invoice_number} actual ${summary.actualQty} pcs, returns ${summary.returnedQty} pcs, final ${php(summary.finalTotal)}, cash ${php(summary.cashReceived)}, balance ${php(summary.finalBalance)}, status ${summary.newStatus}${crateAuditText}${crateSyncResult.ok === false ? ', CRATES NOT SYNCED' : ''}`)
 const settlementMessage = summary.newStatus === 'paid' ? ` Settlement saved. ${inv.reseller_name} is fully paid.` : ` Settlement saved. Remaining balance: ${php(summary.finalBalance)}`
 const crateMessage = crateSyncResult.saved ? ` Crates inventory updated: delivered ${crateSummary.delivered}, returned ${crateSummary.returned}, variance ${crateSummary.variance}.` : crateSyncResult.ok === false ? ' Payment saved, but crates inventory was not updated. Please check crate_movements SQL setup.' : ''
 showToast(settlementMessage + crateMessage, crateSyncResult.ok === false ? 'orange' : 'green')
 setShowPaymentFormMap(p=>({...p,[inv.id]:false}))
 setPaymentAmount(p=>({...p,[inv.id]:''}))
 setPaymentMethod(p=>({...p,[inv.id]:'Cash'}))
 setPaymentNotes(p=>({...p,[inv.id]:''}))
 setSettlementRows(p=>({...p,[inv.id]:[]}))
 setSettlementCrates(p=>({...p,[inv.id]:{ delivered:'', returned:'', dispatcher:'', driver:'', notes:'' }}))
 if (crateSyncResult.saved) loadCrateMovements()
 if (summary.newStatus === 'paid') setInvoiceFilter('paid')
 else if (summary.newStatus === 'partial') setInvoiceFilter('partial')
 await loadDeliveryInvoices()
 await loadOnlinePayments()
 refreshFoundationAfterDataChange('invoice-settlement-saved')
 } catch(err) {
 if (paymentId) await supabase.from('reseller_payments').delete().eq('id', paymentId)
 showToast(' Settlement was not saved: '+(err?.message || err), 'red')
 } finally { setSettlementSaving(p=>({...p,[inv.id]:false})) }
 }


 // Record Payment with Partial Support 
 async function recordPaymentNew(inv) {
 const amount = moneyRound(paymentAmount[inv.id]||0)
 if (!amount || amount<=0) { showToast(' Enter payment amount.','red'); return }

 const method = paymentMethod[inv.id]||'Cash'
 const notes = paymentNotes[inv.id]||''
 const totalDue = moneyRound(inv.total_amount||0)
 const alreadyPaid = moneyRound(inv.paid_amount||0)
 const currentBalance = getInvoiceBalance(inv)

 if (amount - currentBalance > 0.01) {
 showToast(` Amount exceeds balance. Balance is only ${php(currentBalance)}.`, 'red')
 return
 }

 const newPaidTotal = moneyRound(Math.min(totalDue, alreadyPaid + amount))
 const balance = getInvoiceBalance({ total_amount:totalDue, paid_amount:newPaidTotal })
 const newStatus = balance<=0?'paid':'partial'

 // Save a payment ledger entry first. If the invoice update fails, rollback this entry.
 const { data:paymentRows, error:paymentError } = await supabase
.from('reseller_payments')
.insert({
 reseller_id:inv.reseller_id,
 reseller_name:inv.reseller_name,
 invoice_id:inv.id,
 amount,
 payment_date:today,
 payment_method:method,
 notes:notes||null,
 recorded_by:adminRole
 })
.select('id')

 if (paymentError) {
 showToast(' Payment was not saved: '+paymentError.message, 'red')
 return
 }

 // IMPORTANT: Do not update delivery_invoices.payment_method here.
 // Some databases do not have that column. Payment method belongs in reseller_payments.
 const { error:invoiceError } = await supabase
.from('delivery_invoices')
.update({
 paid_amount:newPaidTotal,
 paid_date:newStatus==='paid'?today:null,
 status:newStatus
 })
.eq('id',inv.id)

 if (invoiceError) {
 const paymentId = Array.isArray(paymentRows)? paymentRows[0]?.id: paymentRows?.id
 if (paymentId) await supabase.from('reseller_payments').delete().eq('id', paymentId)
 showToast(' Invoice payment status was not updated: '+invoiceError.message, 'red')
 return
 }

 await logAudit('PAYMENT RECORDED', adminRole, inv.reseller_name, `${inv.invoice_number} ${php(amount)} via ${method}. Status: ${newStatus}. Balance: ${php(balance)}`)
 showToast(newStatus==='paid'?` ${inv.reseller_name} Fully paid! ${php(newPaidTotal)}`:` ${php(amount)} recorded. Outstanding balance: ${php(balance)}`)
 setShowPaymentFormMap(p=>({...p,[inv.id]:false}))
 setPaymentAmount(p=>({...p,[inv.id]:''}))
 setPaymentMethod(p=>({...p,[inv.id]:'Cash'}))
 setPaymentNotes(p=>({...p,[inv.id]:''}))
 if (newStatus === 'paid') setInvoiceFilter('paid')
 else setInvoiceFilter('partial')
 await loadDeliveryInvoices()
 refreshFoundationAfterDataChange('reseller-payment-recorded')
 }

 async function loadCashReconciliations() {
 const { data } = await supabase.from('cash_reconciliations').select('*').order('reconciliation_date', { ascending:false }).limit(30)
 setCashReconciliations(data||[])
 }
 async function saveReconciliation(expectedCash) {
 if (!actualCash && actualCash!=='0') { showToast(' Enter actual cash count.','red'); return }
 setSavingReconciliation(true)
 const actual = Number(actualCash)
 const expected = Number(expectedCash)
 const variance = actual - expected
 const { error } = await supabase.from('cash_reconciliations').upsert({
 reconciliation_date: reconciliationDate,
 expected_cash: expected,
 actual_cash: actual,
 variance,
 notes: reconciliationNotes||null,
 submitted_by: adminRole
 }, { onConflict:'reconciliation_date' })
 if (error) { showToast(' Failed: '+error.message,'red'); setSavingReconciliation(false); return }
 await logAudit('CASH RECONCILIATION', adminRole, 'Finance', `${reconciliationDate} Expected: ${php(expected)}, Actual: ${php(actual)}, Variance: ${php(variance)}`)
 showToast(variance===0?' Balanced! No variance.':variance>0?` Saved Overage: ${php(Math.abs(variance))}`:` Saved Shortage: ${php(Math.abs(variance))}`)
 setActualCash(''); setReconciliationNotes(''); loadCashReconciliations(); refreshFoundationAfterDataChange('cash-reconciliation-saved')
 setSavingReconciliation(false)
 }

 // FEATURE 2: Inventory Auto-Deduction 
 async function autoDeductInventory(productionLogId, items) {
 // items = [{variant_name, pieces}]
 // For each variant, find its recipe ingredients and deduct from inventory
 let deducted = []
 for (const item of items) {
 const { data:variant } = await supabase.from('donut_variants').select('id').eq('name', item.variant_name).single()
 if (!variant) continue
 const { data:recipe } = await supabase.from('variant_recipes').select('*').eq('variant_id', variant.id)
 if (!recipe || recipe.length === 0) continue
 for (const ing of recipe) {
 const totalQty = ing.quantity_per_batch? (ing.quantity_per_batch * item.pieces / (variant.pieces_per_batch||12)): (ing.quantity * item.pieces)
 const { data:invItem } = await supabase.from('inventory_items').select('*').ilike('name', `%${ing.ingredient_name}%`).single()
 if (invItem) {
 const newStock = Math.max(0, Number(invItem.current_stock||0) - totalQty)
 await supabase.from('inventory_items').update({ current_stock: newStock }).eq('id', invItem.id)
 deducted.push({ item: ing.ingredient_name, deducted: totalQty.toFixed(2), unit: ing.unit, remaining: newStock.toFixed(2) })
 if (newStock <= Number(invItem.min_stock||0)) {
 await createNotification(null, 'System', 'inventory', ` Low Stock: ${invItem.name}`, `${invItem.name} is below minimum stock level. Remaining: ${newStock.toFixed(2)} ${invItem.unit}`)
 }
 }
 }
 }
 if (deducted.length > 0) showToast(` Inventory auto-deducted: ${deducted.length} ingredient(s) updated`)
 return deducted
 }

