 async function confirmTimeOut() {
 if (!capturedPhoto) { alert('Please take a selfie first.'); return }
 if (!todayLog?.id) { alert('No active attendance log found. Please reload and try again.'); return }
 setLoading(true)

 // Re-read the attendance row immediately before Time Out. A stale browser tab
 // must never overwrite an Absent, deleted, malformed, or completed record.
 const { data:verifiedLog, error:verifyLogError } = await supabase
  .from('attendance_logs')
  .select('*')
  .eq('id', todayLog.id)
  .eq('employee_id', employee.id)
  .maybeSingle()
 if (verifyLogError || !isAttendanceLogEligibleForActiveShift(verifiedLog)) {
  setLoading(false)
  setCameraMode(null)
  setCapturedPhoto(null)
  await loadTodayLog(employee)
  const reason = isAbsentAttendanceLog(verifiedLog)
   ? 'This attendance date is marked Absent.'
   : verifiedLog?.time_out
    ? 'This attendance record already has a Time Out.'
    : !verifiedLog?.time_in
     ? 'This attendance record has no valid Time In.'
     : 'The active attendance record could not be verified.'
  alert(`Time Out blocked: ${reason} Please reload or ask the admin to review the attendance record.`)
  return
 }

 const { data:verifiedBreakRows, error:verifiedBreakError } = await supabase
  .from('break_logs')
  .select('*')
  .eq('attendance_log_id', verifiedLog.id)
  .order('created_at')
 const effectiveBreakRows = verifiedBreakError ? todayBreaks : (verifiedBreakRows || [])
 const openVerifiedBreak = effectiveBreakRows.find(row => !row?.break_in)
 if (openVerifiedBreak) {
  setLoading(false)
  alert('Please Break In first before timing out.')
  return
 }

 const timeIn = verifiedLog.time_in
 const timeOut = nowTime()
 const activeAttendanceDate = verifiedLog.attendance_date || today
 const undertimeDeductionApplicable = employeeRuleEnabled(employee.undertime_deduction_applicable, true)
 const overtimePayEligible = employeeRuleEnabled(employee.overtime_pay_eligible, true)
 const nightDifferentialPayEligible = employeeRuleEnabled(employee.night_differential_pay_eligible, true)

 let undertimeMinutes=0, rawUndertimeMinutes=0, overtimeMinutes=0, rawOvertimeMinutes=0, status=verifiedLog.late_minutes>0?'Late':'Completed'
 const totalBreakMins = effectiveBreakRows.reduce((s,b)=>s+Number(b.break_minutes||0),0)
 const excessBreakMins = Math.max(0, totalBreakMins-ALLOWED_BREAK_MINUTES)
 const attendanceMetrics = getAttendanceDayWorkMetrics([{
  ...verifiedLog,
  time_in:timeIn,
  time_out:timeOut,
  total_break_minutes:totalBreakMins,
  status:'Completed'
 }])
 rawUndertimeMinutes = attendanceMetrics.rawUndertimeMinutes
 undertimeMinutes = undertimeDeductionApplicable ? attendanceMetrics.undertimeMinutes : 0

 // OT remains based on actual paid attendance after the meal-break rule.
 // UT is schedule-anchored separately from Late and Overbreak, so staying after
 // shift end cannot erase an early Time Out and no shortage is double-classified.
 rawOvertimeMinutes = Math.max(0, Math.round(attendanceMetrics.paidWorkedMinutes - REQUIRED_PAID_WORK_MINUTES))
 overtimeMinutes = overtimePayEligible ? roundPayableOvertimeMinutes(rawOvertimeMinutes) : 0
 if (undertimeMinutes>0) status='Undertime - Automatic Deduction'
 else if (overtimeMinutes>0) status='Overtime - Pending Filing'

 // Auto-compute Night Shift Differential (10PM - 6AM), including next-day time-out 
 const inM = minutesFromTime(timeIn)
 const outM = minutesFromTime(timeOut) < inM? minutesFromTime(timeOut) + 24*60: minutesFromTime(timeOut)
 const nsdStart = 22*60 // 10PM = 1320 mins
 const nsdEnd = 30*60 // 6AM next day = 1800 mins
 const os = Math.max(inM, nsdStart)
 const oe = Math.min(outM, nsdEnd)
 const rawNsdMinutes = oe > os? Math.round(oe - os): 0
 const nsdMinutes = nightDifferentialPayEligible ? rawNsdMinutes : 0
 // 

 let selfieUrl = null
 try { selfieUrl = await uploadSelfie(capturedPhoto, `timeout_${employee.id}_${activeAttendanceDate}.jpg`) } catch(e){}
 const { data, error } = await supabase.from('attendance_logs').update({
 time_out: timeOut,
 // Persist the policy-normalized late penalty so DTR, approval and payroll agree.
 late_minutes: attendanceMetrics.lateMinutes,
 undertime_minutes: undertimeMinutes,
 overtime_minutes: overtimeMinutes,
 status,
 selfie_out_url: selfieUrl,
 total_break_minutes: totalBreakMins,
 excess_break_minutes: excessBreakMins,
 overtime_approved: null,
 night_diff_minutes: nsdMinutes
 })
 .eq('id', verifiedLog.id)
 .eq('employee_id', employee.id)
 .not('time_in', 'is', null)
 .is('time_out', null)
 .select()
 .maybeSingle()
 setLoading(false)
 if (error) { alert('Time Out failed: '+error.message); return }
 if (!data) {
  await loadTodayLog(employee)
  alert('Time Out was not saved because the attendance record changed or is no longer active. Please reload and try again.')
  return
 }

 setTodayLog(data); setCameraMode(null); setCapturedPhoto(null)
 await logAudit('TIME OUT', employee.full_name, employee.full_name, `Timed out at ${timeOut} for attendance date ${activeAttendanceDate}${nsdMinutes>0?' | NSD: '+nsdMinutes+' mins':''}${undertimeMinutes>0?` | Automatic UT: ${undertimeMinutes} mins from ${rawUndertimeMinutes} actual shortage mins`:''}`)
 let msg = ' Time Out saved successfully!'
 if (activeAttendanceDate!== today) msg += `\n\n Night shift time-out saved under attendance date: ${activeAttendanceDate}.`
 if (nsdMinutes > 0) msg += `\n\n Night Shift Differential: ${nsdMinutes} minutes (${(nsdMinutes/60).toFixed(1)} hrs) will be computed in payroll at 10% premium.`
 if (overtimeMinutes>0) msg += `\n\n ${rawOvertimeMinutes} actual OT minute(s) detected. ${overtimeMinutes} minute(s) are payable in completed ${OVERTIME_BLOCK_MINUTES}-minute blocks. Please file an OT request.`
 if (undertimeMinutes>0) msg += `\n\n ${rawUndertimeMinutes} actual shortage minute(s) were detected. The system recorded ${undertimeMinutes} chargeable UT minute(s) under the ${UNDERTIME_BLOCK_MINUTES}-minute block policy and will deduct them automatically in payroll. No UT request or admin approval is required.`
 if (rawUndertimeMinutes>0 && !undertimeDeductionApplicable) msg += `\n\n Undertime exemption applied. No automatic UT deduction was created.`
 if (excessBreakMins>0) msg += `\n\n ${excessBreakMins} min excess break was recorded separately as Overbreak and was not rounded again into UT.`
 if (totalBreakMins===0) msg += `\n\n No meal break was recorded. The standard 60-minute deduction was applied. If you genuinely worked continuously without a meal break, file a No Meal Break exception for admin review before payroll; approval will recalculate automatic UT and any OT eligibility.`
  alert(msg)
 }
 async function toggleTimeAdjustmentFilingPanel() {
 const opening = !showOTRequest
 closeAllPanels()
 setShowOTRequest(opening)
 if (!opening) return

 setOtRequestReason('')
 setOtRequestReasonPreset('')
 setOtRequestMinutes('')
 setOtRequestFrom('')
 setOtRequestTo('')
 setMealBreakAttestation(false)
 setTimeAdjPreview({ loading:true, canSubmit:false, minutes:0, message:'Finding your latest completed attendance date...', code:'loading' })

 let defaultDate = today
 try {
  // Filing access must not depend on today's attendance. Find the latest completed
  // non-absent attendance row so employees can file one or more days later.
  const { data:recentAttendanceRows, error:recentAttendanceError } = await supabase
   .from('attendance_logs')
   .select('attendance_date,time_in,time_out,status,created_at')
   .eq('employee_id', employee.id)
   .not('time_in', 'is', null)
   .not('time_out', 'is', null)
   .lte('attendance_date', today)
   .order('attendance_date', { ascending:false })
   .order('created_at', { ascending:false })
   .limit(30)

  if (recentAttendanceError) throw recentAttendanceError
  const latestCompletedRow = (recentAttendanceRows || []).find(row => !isAbsentAttendanceLog(row))
  if (latestCompletedRow?.attendance_date) {
   defaultDate = String(latestCompletedRow.attendance_date).slice(0, 10)
  }
 } catch(error) {
  console.warn('Latest attendance date lookup failed; using today as the filing date:', error)
 }

 setOtRequestDate(defaultDate)
 await refreshTimeAdjustmentPreview(defaultDate, otRequestType, '', '')
}

 async function refreshTimeAdjustmentPreview(dateValue = otRequestDate, typeValue = otRequestType, fromValue = otRequestFrom, toValue = otRequestTo) {
 const targetDate = String(dateValue || '').slice(0, 10)
 const requestType = String(typeValue || 'overtime').toLowerCase()
 const overtimePayEligible = employeeRuleEnabled(employee?.overtime_pay_eligible, true)
 if (requestType === 'undertime') {
  const automaticPreview = { loading:false, canSubmit:false, minutes:0, message:`Undertime is attendance-detected and deducted automatically in ${UNDERTIME_BLOCK_MINUTES}-minute blocks. Employees do not file UT requests.`, code:'undertime_automatic' }
  setTimeAdjPreview(automaticPreview)
  setOtRequestType('overtime')
  setOtRequestMinutes('')
  setOtRequestFrom('')
  setOtRequestTo('')
  return automaticPreview
 }
 if (requestType === 'overtime' && !overtimePayEligible) {
  const exemptPreview = { loading:false, canSubmit:false, minutes:0, message:'Overtime filing is disabled for your employee payroll policy. No OT pay is created for this attendance date.', code:'overtime_exempt' }
  setTimeAdjPreview(exemptPreview)
  setOtRequestMinutes('')
  setOtRequestFrom('')
  setOtRequestTo('')
  return exemptPreview
 }
 if (targetDate && targetDate > today) {
  const futurePreview = { loading:false, canSubmit:false, minutes:0, message:'Future attendance dates cannot be filed. Select today or a completed past attendance date.', code:'future_date' }
  setTimeAdjPreview(futurePreview)
  setOtRequestMinutes('')
  setOtRequestFrom('')
  setOtRequestTo('')
  return futurePreview
 }
 if (!employee?.id || !targetDate) {
  const emptyPreview = { loading:false, canSubmit:false, minutes:0, message:'Select an attendance date to validate the time record.', code:'idle' }
  setTimeAdjPreview(emptyPreview)
  setOtRequestMinutes('')
  setOtRequestFrom('')
  setOtRequestTo('')
  return emptyPreview
 }

 setTimeAdjPreview({ loading:true, canSubmit:false, minutes:0, message:'Checking the attendance record...', code:'loading' })
 try {
  const validation = await fetchAttendanceDayValidation(employee.id, targetDate, { employeeCode:employee.employee_code, employeeName:employee.full_name })
  const { integrity } = validation
  const canonicalDate = String(validation.resolvedAttendanceDate || targetDate).slice(0,10)
  const guardDates = Array.from(new Set([targetDate, canonicalDate].filter(Boolean)))
  let minutes = requestType === 'overtime' ? validation.actualOvertimeMinutes : 0
  let canSubmit = false
  let message = ''
  let rangeValidation = null
  let mealBreakImpact = null

  let activeMealBreakRequests = []
  if (integrity.isValidCompleted) {
   const { data:mealRows, error:mealRowsError } = await supabase
    .from('time_adjustment_requests')
    .select('id,status,attendance_date,created_at')
    .eq('employee_id', employee.id)
    .in('attendance_date', guardDates)
    .eq('request_type', 'meal_break')
    .in('status', ['pending','approved'])
    .limit(10)
   if (mealRowsError) throw mealRowsError
   activeMealBreakRequests = mealRows || []
  }

  if (integrity.isAbsentOnly) {
   message = 'Request blocked: this date is marked absent.'
  } else if (integrity.isIncomplete) {
   message = `Request blocked: ${integrity.message} Submit a DTR correction first.`
  } else if (integrity.isInvalidShortPunch) {
   message = `Request blocked: ${integrity.message} Submit a DTR correction first.`
  } else if (!integrity.isValidCompleted) {
   message = 'Request blocked: no complete Time In and Time Out were found for this date.'
  } else if (requestType === 'meal_break') {
   setOtRequestFrom('')
   setOtRequestTo('')
   const activeMealBreak = activeMealBreakRequests[0]
   const recordedBreakMinutes = Math.max(0, Math.round(safeNum(validation.metrics.recordedBreakMinutes, 0)))
   const breakPunchEvidence = getAttendanceBreakPunchEvidence(validation)
   const alreadyApplied = validation.metrics.breakOverrideApplied === true
   const revisedMetrics = getAttendanceDayWorkMetrics(validation.integrity.completedLogs, validation.breakRowsByLogId, 0)
   const revisedOTMinutes = roundPayableOvertimeMinutes(Math.max(0, revisedMetrics.paidWorkedMinutes - REQUIRED_PAID_WORK_MINUTES))
   const revisedUTMinutes = Math.max(0, Math.round(safeNum(revisedMetrics.undertimeMinutes, 0)))
   mealBreakImpact = {
    recordedBreakMinutes,
    breakPunchEvidence,
    breakPunchCount:breakPunchEvidence.punchCount,
    completedBreakPunchCount:breakPunchEvidence.completedPunchCount,
    incompleteBreakPunchCount:breakPunchEvidence.incompletePunchCount,
    currentDeductedBreakMinutes:validation.metrics.deductedBreakMinutes,
    proposedDeductedBreakMinutes:0,
    revisedPaidWorkedMinutes:revisedMetrics.paidWorkedMinutes,
    revisedOTMinutes,
    revisedUTMinutes
   }

   if (activeMealBreak) {
    message = activeMealBreak.status === 'approved'
     ? `A No Meal Break exception is already approved for this attendance shift (${activeMealBreak.attendance_date}). Another filing is blocked unless the approved exception is voided first.`
     : `A No Meal Break filing is already pending for this attendance shift (${activeMealBreak.attendance_date}). Please wait for admin review instead of filing another request.`
   } else if (alreadyApplied) {
    message = 'A No Meal Break exception is already applied to this attendance record. Another filing is not allowed.'
   } else if (breakPunchEvidence.hasBreakEvidence) {
    message = getNoMealBreakBreakConflictMessage(breakPunchEvidence, 'No Meal Break filing')
   } else {
    const { data:approvedTimeRows, error:approvedTimeError } = await supabase
     .from('time_adjustment_requests')
     .select('id,request_type,minutes,attendance_date')
     .eq('employee_id', employee.id)
     .in('attendance_date', guardDates)
     .eq('request_type', 'overtime')
     .eq('status', 'approved')
     .limit(10)
    if (approvedTimeError) throw approvedTimeError
    if (approvedTimeRows?.length) {
     message = 'No Meal Break filing is blocked because OT is already approved for this attendance shift. Ask the admin to undo that OT approval first, then file the break exception so all minutes can be recalculated in the correct order.'
    } else {
     canSubmit = true
     message = `No break was recorded. The standard ${validation.metrics.deductedBreakMinutes}-minute deduction remains active unless this filing is approved. If approved, paid work becomes ${revisedMetrics.paidWorkedMinutes} minute(s), resulting in ${revisedOTMinutes} OT minute(s) and ${revisedUTMinutes} UT minute(s).`
    }
   }
  } else if (activeMealBreakRequests.some(row => row.status === 'pending')) {
   message = 'OT filing is blocked while a No Meal Break request is pending for this attendance shift. The break decision must be reviewed first because it changes the final paid-work, OT, and automatic UT minutes.'
  } else if (requestType === 'overtime' && minutes <= 0) {
   message = 'No overtime can be filed. The attendance record has no payable minutes beyond eight paid work hours after the approved break treatment.'
  } else if (requestType === 'overtime') {
   const lockedFrom = normalizeTimeInputValue(validation?.overtimeWindow?.verifiedFrom)
   const lockedTo = normalizeTimeInputValue(validation?.overtimeWindow?.verifiedTo)
   setOtRequestFrom(lockedFrom)
   setOtRequestTo(lockedTo)
   rangeValidation = validateFiledOvertimeRange(validation, lockedFrom, lockedTo)
   canSubmit = rangeValidation.canSubmit
   minutes = rangeValidation.filedMinutes || validation.actualOvertimeMinutes
   message = canSubmit
    ? `System-locked actual OT range: ${formatClockTimeForDisplay(lockedFrom)} to ${formatClockTimeForDisplay(lockedTo)} (${rangeValidation.filedRawMinutes} raw minute(s)). Payable OT is ${minutes} minute(s) in completed ${OVERTIME_BLOCK_MINUTES}-minute blocks. OT To is capped at the actual Time Out and cannot be extended.`
    : rangeValidation.message
  }

  if (requestType === 'overtime' && !canSubmit) {
   setOtRequestFrom('')
   setOtRequestTo('')
  }
  if (validation.resolvedFromPreviousDay) {
   message = `${message} ${validation.resolutionMessage}`.trim()
  }
  const preview = { loading:false, canSubmit, minutes, message, code:integrity.code, validation, rangeValidation, mealBreakImpact }
  setTimeAdjPreview(preview)
  setOtRequestMinutes(requestType === 'meal_break' ? '0' : canSubmit ? String(minutes) : '')
  return preview
 } catch(err) {
  const preview = { loading:false, canSubmit:false, minutes:0, message:'Attendance validation failed: ' + (err?.message || err), code:'error' }
  setTimeAdjPreview(preview)
  setOtRequestMinutes('')
  setOtRequestFrom('')
  setOtRequestTo('')
  return preview
 }
}

 async function submitTimeAdjRequest() {
 if (timeAdjSubmitLockRef.current) return
 if (otRequestType === 'undertime') {
  alert(`Undertime cannot be filed. It is calculated from verified attendance and deducted automatically in ${UNDERTIME_BLOCK_MINUTES}-minute blocks.`)
  setOtRequestType('overtime')
  return
 }
 if (!otRequestReason || !otRequestDate) { alert('Please select a date and enter a reason.'); return }
 if (otRequestType === 'meal_break' && !mealBreakAttestation) {
  alert('Please confirm that you actually worked continuously and did not take a meal break for this attendance shift.')
  return
 }
 timeAdjSubmitLockRef.current = true
 setSubmittingTimeAdjRequest(true)
 try {
  const preview = await refreshTimeAdjustmentPreview(otRequestDate, otRequestType, otRequestFrom, otRequestTo)
  const requiresPositiveMinutes = otRequestType !== 'meal_break'
  if (!preview?.canSubmit || (requiresPositiveMinutes && safeNum(preview?.minutes, 0) <= 0)) {
   alert(preview?.message || 'This request is not supported by the attendance record.')
   return
  }

  const exactMinutes = otRequestType === 'meal_break' ? 0 : Math.max(0, Math.round(safeNum(preview.minutes, 0)))
  const lockedOTFrom = normalizeTimeInputValue(preview?.rangeValidation?.filedFrom || preview?.validation?.overtimeWindow?.verifiedFrom)
  const lockedOTTo = normalizeTimeInputValue(preview?.rangeValidation?.filedTo || preview?.validation?.overtimeWindow?.verifiedTo)
  if (otRequestType === 'overtime' && (!lockedOTFrom || !lockedOTTo)) {
   alert('Overtime filing is blocked because the verified attendance-supported OT window could not be determined.')
   return
  }

  const canonicalAttendanceDate = String(preview?.validation?.resolvedAttendanceDate || otRequestDate).slice(0, 10)
  const duplicateDates = Array.from(new Set([
   String(otRequestDate || '').slice(0, 10),
   canonicalAttendanceDate
  ].filter(Boolean)))
  const { data:existingRequests, error:existingError } = await supabase
   .from('time_adjustment_requests')
   .select('id,status,attendance_date')
   .eq('employee_id', employee.id)
   .in('attendance_date', duplicateDates)
   .eq('request_type', otRequestType)
   .in('status', ['pending', 'approved'])
   .limit(10)
  if (existingError) { alert('Failed checking existing request: '+existingError.message); return }
  if (existingRequests?.length) {
   const existingDateText = Array.from(new Set(existingRequests.map(row => String(row.attendance_date || '').slice(0,10)).filter(Boolean))).join(', ')
   alert(`You already have an active ${getTimeAdjustmentRequestLabel(otRequestType)} request for this attendance shift${existingDateText ? ` (${existingDateText})` : ''}. Please wait for admin review instead of filing another one.`)
   return
  }

  if (otRequestType === 'meal_break') {
   const { data:approvedTimeRows, error:approvedTimeError } = await supabase
    .from('time_adjustment_requests')
    .select('id,request_type,attendance_date')
    .eq('employee_id', employee.id)
    .in('attendance_date', duplicateDates)
    .eq('request_type', 'overtime')
    .eq('status', 'approved')
    .limit(10)
   if (approvedTimeError) { alert('Failed checking approved OT: '+approvedTimeError.message); return }
   if (approvedTimeRows?.length) {
    alert('No Meal Break filing is blocked because OT is already approved for this shift. Ask the admin to undo the approved OT first, then file the break exception.')
    return
   }
  }

  let employeeReason = otRequestReason
  if (otRequestType === 'overtime') {
   const window = preview?.rangeValidation?.window || preview?.validation?.overtimeWindow || {}
   employeeReason = buildTimeAdjustmentEmployeeReason(otRequestReason, {
    filedFrom:lockedOTFrom,
    filedTo:lockedOTTo,
    filedMinutes:exactMinutes,
    filedRawMinutes:safeNum(preview?.rangeValidation?.filedRawMinutes, window.rawMinutes),
    verifiedFrom:window.verifiedFrom || '',
    verifiedTo:window.verifiedTo || '',
    verifiedMinutes:safeNum(window.payableMinutes ?? window.minutes, exactMinutes),
    verifiedRawMinutes:safeNum(window.rawMinutes, 0),
    excludedMinutes:safeNum(window.excludedMinutes, 0),
    actualTimeIn:window.actualTimeIn || '',
    actualTimeOut:window.actualTimeOut || '',
    shiftStart:window.shiftStart || '',
    shiftEnd:window.shiftEnd || '',
    attendanceDate:canonicalAttendanceDate,
    employeeSelectedDate:otRequestDate
   })
  } else if (otRequestType === 'meal_break') {
   const impact = preview?.mealBreakImpact || {}
   employeeReason = buildMealBreakExceptionEmployeeReason(otRequestReason, {
    attendanceDate:canonicalAttendanceDate,
    employeeSelectedDate:otRequestDate,
    recordedBreakMinutes:safeNum(impact.recordedBreakMinutes, 0),
    breakPunchCount:safeNum(impact.breakPunchCount, 0),
    completedBreakPunchCount:safeNum(impact.completedBreakPunchCount, 0),
    incompleteBreakPunchCount:safeNum(impact.incompleteBreakPunchCount, 0),
    defaultDeductedBreakMinutes:safeNum(impact.currentDeductedBreakMinutes, ALLOWED_BREAK_MINUTES),
    requestedUnpaidBreakMinutes:0,
    rawSpanMinutes:safeNum(preview?.validation?.metrics?.rawSpanMinutes, 0),
    proposedPaidWorkedMinutes:safeNum(impact.revisedPaidWorkedMinutes, 0),
    proposedOvertimeMinutes:safeNum(impact.revisedOTMinutes, 0),
    proposedUndertimeMinutes:safeNum(impact.revisedUTMinutes, 0),
    employeeAttested:true,
    filedAt:new Date().toISOString()
   })
  }

  const { error } = await supabase.from('time_adjustment_requests').insert({
   employee_id:employee.id,
   employee_code:employee.employee_code,
   employee_name:employee.full_name,
   attendance_date:canonicalAttendanceDate,
   request_type:otRequestType,
   minutes:exactMinutes,
   employee_reason:employeeReason,
   status:'pending'
  })
  if (error) {
   const duplicateMessage = String(error.message || '').toLowerCase().includes('duplicate')
   if (isNoMealBreakBreakGuardError(error)) {
    alert('No Meal Break filing blocked: a Break Out or Break In punch exists for this attendance shift. This remains blocked even when the saved break duration is 0 minutes. Correct the DTR first if the punch is wrong.')
   } else {
    alert(duplicateMessage ? 'An active request already exists for this employee and attendance shift. Refresh and wait for admin review.' : 'Failed: '+error.message)
   }
   return
  }
  alert(otRequestType === 'overtime'
   ? `Overtime request filed for the system-locked actual range ${formatClockTimeForDisplay(lockedOTFrom)} to ${formatClockTimeForDisplay(lockedOTTo)}. ${safeNum(preview?.rangeValidation?.filedRawMinutes, exactMinutes)} actual minute(s) convert to ${exactMinutes} payable minute(s) under the completed ${OVERTIME_BLOCK_MINUTES}-minute policy, under attendance date ${canonicalAttendanceDate}.${canonicalAttendanceDate !== otRequestDate ? ` Your selected date ${otRequestDate} was correctly matched to the previous-day overnight shift.` : ''} OT To is capped at the actual Time Out. The request is waiting for admin approval.`
   : `No Meal Break exception filed for attendance date ${canonicalAttendanceDate}. The standard 60-minute deduction remains active while the request is pending. If approved, the system will recalculate automatic UT and any OT eligibility from actual attendance.`
  )
  setOtRequestReason('')
  setOtRequestReasonPreset('')
  setOtRequestMinutes('')
  setOtRequestDate('')
  setOtRequestFrom('')
  setOtRequestTo('')
  setMealBreakAttestation(false)
  setTimeAdjPreview({ loading:false, canSubmit:false, minutes:0, message:'Select an attendance date to validate the time record.', code:'idle' })
  setShowOTRequest(false)
 } catch(error) {
  alert('Failed to file the request: ' + (error?.message || error))
 } finally {
  timeAdjSubmitLockRef.current = false
  setSubmittingTimeAdjRequest(false)
 }
}
 async function submitLeaveRequest() {
 if (!leaveStartDate ||!leaveEndDate ||!leaveReason) {
 alert('Please complete all fields')
 return
 }

 const filingInfo = getLeaveFilingTypeInfo(leaveFilingType)
 const emergencyFiling = isEmergencyLeaveFiling(leaveFilingType)
 const todayMid = parseLocalDate(today)
 const startD = parseLocalDate(leaveStartDate)

 if (!startD ||!todayMid) {
 alert('Invalid leave start date.')
 return
 }

 if (!emergencyFiling && (startD.getTime() - todayMid.getTime()) / (1000 * 60 * 60 * 24) < 2) {
 alert('Planned leave must be filed at least 3 days in advance. For sudden illness or emergency, choose Emergency Sick Leave or Emergency Personal Leave.')
 return
 }

 const dur = daysInclusive(leaveStartDate, leaveEndDate)
 if (dur <= 0) {
 alert('Invalid leave date range.')
 return
 }

 const syncResult = await syncEmployeeSIL(employee, { silent:true })
 const activeEmployee = syncResult?.employee || employee
 const leaveInfo = getEmployeeLeaveInfo(activeEmployee)

 if (leaveInfo.type === 'SIL' && dur > leaveInfo.silBalance) {
 alert(`Only ${leaveInfo.silBalance} SIL day(s) remaining. Please adjust the dates or file unpaid leave after your SIL is fully used.`)
 return
 }

 const cleanReason = String(leaveReason || '').trim()
 const reasonWithFilingType = `[${filingInfo.label}] ${cleanReason}`

 const { error } = await supabase.from('leave_requests').insert({
 employee_id: activeEmployee.id,
 employee_code: activeEmployee.employee_code,
 employee_name: activeEmployee.full_name,
 leave_start: leaveStartDate,
 leave_end: leaveEndDate,
 duration_days: dur,
 leave_type: leaveInfo.type,
 reason: reasonWithFilingType,
 status: 'pending',
 is_paid: leaveInfo.isPaid
 })

 if (error) {
 alert(error.message)
 return
 }

 alert(`${filingInfo.label} request submitted! ${leaveInfo.isPaid? 'If approved, it will be charged as paid SIL.': 'If approved, it will be treated as unpaid excused leave.'} Waiting for admin approval.`)

 setEmployee(activeEmployee)
 setLeaveStartDate('')
 setLeaveEndDate('')
 setLeaveType('')
 setLeaveFilingType('planned')
 setLeaveReason('')
 setShowLeaveRequest(false)
 loadMyLeaveBalance(activeEmployee)
 }
 async function submitCashAdvanceRequest() {
 if (submittingCashAdvanceRequest) return
 const cleanReason = String(requestCashReason || '').trim()
 if (!requestCashAmount || !cleanReason) { alert('Please enter amount and reason.'); return }
 const amount = Number(requestCashAmount)
 if (!amount || amount <= 0) { alert('Amount must be greater than 0.'); return }
 if (!employeeCashAdvanceSessionToken) { alert('Your secure cash-advance session has expired. Please log out and log in again.'); return }
 setSubmittingCashAdvanceRequest(true)
 try {
  const { error } = await supabase.rpc('employee_submit_cash_advance', {
   p_session_token:employeeCashAdvanceSessionToken,
   p_amount:amount,
   p_reason:cleanReason
  })

  if (error) {
   const msg = String(error.message || '').toLowerCase()
   if (error.code === '23505' || msg.includes('already have a pending') || msg.includes('duplicate') || msg.includes('unique')) {
    alert('Cash advance request already submitted. Please wait for admin review instead of submitting again.')
    setShowCashAdvanceRequest(false)
    loadMyCashAdvances(employee)
    return
   }
   alert('Failed: '+error.message)
   return
  }

  alert('Request submitted! Waiting for admin approval.')
  setRequestCashAmount(''); setRequestCashReason(''); setRequestCashReasonPreset(''); setShowCashAdvanceRequest(false); loadMyCashAdvances(employee)
 } finally {
  setSubmittingCashAdvanceRequest(false)
 }
 }
 async function agreePayslip(payId) {
 const { error } = await supabase.from('payroll_records').update({ employee_acknowledgement:'agreed' }).eq('id', payId)
 if (error) { alert('Failed: '+error.message); return }
 alert('Payslip acknowledged!'); loadMyPayslips(employee)
 }
 async function submitPayslipDispute(pay) {
 const payId = pay?.id
 if (!payId || submittingPayslipDisputes[payId]) return
 const reason = disputeReasons[payId]
 if (!reason?.trim()) { alert('Please enter your reason.'); return }
 setSubmittingPayslipDisputes(p=>({...p,[payId]:true}))
 try {
  const { data:existing, error:existingError } = await supabase
   .from('payslip_disputes')
   .select('id,status')
   .eq('payroll_record_id', String(payId))
   .eq('employee_id', employee.id)
   .eq('status','pending')
   .limit(1)

  if (existingError) console.warn('Existing payslip dispute check failed:', existingError)

  if ((existing || []).length > 0 || normalizePayrollAcknowledgement(pay.employee_acknowledgement) === 'disputed') {
   await supabase.from('payroll_records').update({ employee_acknowledgement:'disputed' }).eq('id', payId)
   alert('Dispute already submitted. It is now waiting for admin review.')
   setShowDisputeBox(p=>({...p,[payId]:false}))
   setDisputeReasons(p=>({...p,[payId]:''}))
   setDisputeReasonPresets(p=>({...p,[payId]:''}))
   loadMyPayslips(employee)
   return
  }

  const { error } = await supabase.from('payslip_disputes').insert({
   employee_id:employee.id,
   employee_code:employee.employee_code,
   employee_name:employee.full_name,
   payroll_record_id:String(payId),
   payroll_start:pay.payroll_start,
   payroll_end:pay.payroll_end,
   reason,
   status:'pending'
  })
  if (error) { alert('Failed: '+error.message); return }
  await supabase.from('payroll_records').update({ employee_acknowledgement:'disputed' }).eq('id', payId)
  alert('Dispute submitted. Waiting for admin review.')
  setShowDisputeBox(p=>({...p,[payId]:false}))
  setDisputeReasons(p=>({...p,[payId]:''}))
  setDisputeReasonPresets(p=>({...p,[payId]:''}))
  loadMyPayslips(employee)
 } finally {
  setSubmittingPayslipDisputes(p=>({...p,[payId]:false}))
 }
 }

 // Admin Functions 
function canAccess(tab) {
const role = normalizeAdminRole(adminRole)
if (tab === 'sales' && (invoiceDeletionAccess.can_request || invoiceDeletionAccess.can_review)) return true
if (role === 'owner') return true
 if (role === 'manager') return ['dashboard','tomorrowForecast','attendance','employees','schedule','holidays','leaveRequests','overtime','disputes','announcements','auditTrail','contracts','inventory','sops','recipes','sales','analytics','foundation','franchise','posMonitor'].includes(tab)
 if (role === 'admin') return ['tomorrowForecast','posMonitor'].includes(tab)
 if (role === 'pos_admin') return ['posMonitor'].includes(tab)
 if (role === 'hr') return ['dashboard','attendance','employees','schedule','holidays','leaveRequests','cashRequests','overtime','disputes','announcements','contracts','sops','posMonitor'].includes(tab)
 if (role === 'payroll') return ['dashboard','payroll','cashAdvanceCoverage','thirteenth','finalpay','adjustment','payrollHistory','remittance','dtr','bankDisbursement','posMonitor'].includes(tab)
 if (role === 'supervisor') return ['dashboard','tomorrowForecast','attendance','overtime','schedule','inventory','sops','posMonitor'].includes(tab)
 if (role === 'asst_supervisor') return ['dashboard','tomorrowForecast','attendance','overtime','schedule','inventory','sops','posMonitor'].includes(tab)
 return false
 }

 async function logAudit(action, by, target, details) {
 try { await supabase.from('audit_logs').insert({ action, performed_by:by, target_employee:target, details }) } catch(e) {}
 }

 // SOP Library Functions
 function canManageSops() {
 const role = normalizeAdminRole(adminRole)
 return role === 'owner' || role === 'manager'
 }

 function resetSopForm() {
 setEditingSopId(null)
 setSopForm({
 sop_code:'',
 title:'',
 department:'Production',
 category:'Operations',
 version:'1.0',
 effective_date:today,
 status:'draft',
 access_roles:'owner,manager,hr,supervisor,asst_supervisor',
 acknowledgement_required:true,
 purpose:'',
 procedure:'',
 required_records:'',
 approved_by:'Owner',
 notes:''
 })
 }

 function openNewSopForm() {
 resetSopForm()
 setShowSopForm(true)
 setSopView('library')
 }

 function openEditSop(sop) {
 if (!canManageSops()) { showToast('Only Owner or Manager can edit SOPs.', 'red'); return }
 setEditingSopId(sop.id)
 setSopForm({
 sop_code:sop.sop_code || '',
 title:sop.title || '',
 department:sop.department || 'Production',
 category:sop.category || 'Operations',
 version:sop.version || '1.0',
 effective_date:String(sop.effective_date || today).slice(0,10),
 status:sop.status || 'draft',
 access_roles:sop.access_roles || 'owner,manager,hr,supervisor,asst_supervisor',
 acknowledgement_required:sop.acknowledgement_required !== false,
 purpose:sop.purpose || '',
 procedure:sop.procedure || '',
 required_records:sop.required_records || '',
 approved_by:sop.approved_by || 'Owner',
 notes:sop.notes || ''
 })
 setShowSopForm(true)
 setSopView('library')
 window.scrollTo?.({ top:0, behavior:'smooth' })
 }

 function getSopAccessRoles(sop) {
 return String(sop?.access_roles || '').split(',').map(r => r.trim().toLowerCase()).filter(Boolean)
 }

 function canViewSop(sop) {
 const role = normalizeAdminRole(adminRole)
 if (role === 'owner') return true
 const roles = getSopAccessRoles(sop)
 return roles.length === 0 || roles.includes(role)
 }

 async function loadSops() {
 setSopsLoading(true)
 setSopLoadError('')
 try {
 const { data, error } = await supabase
 .from('sop_documents')
 .select('*')
 .order('sop_code', { ascending:true })

 if (error) {
 setSops([])
 setSopLoadError(error.message || 'Unable to load SOP Library. Run the SOP Supabase setup SQL first.')
 return
 }

 setSops(data || [])
 } catch(e) {
 setSops([])
 setSopLoadError(e?.message || 'Unable to load SOP Library. Run the SOP Supabase setup SQL first.')
 } finally {
 setSopsLoading(false)
 }
 }

 async function loadSopAcknowledgements() {
 setSopAckLoading(true)
 try {
 const { data, error } = await supabase
 .from('sop_acknowledgements')
 .select('*')
 .order('acknowledged_at', { ascending:false })
 .limit(500)
 if (error) {
 setSopAcknowledgements([])
 return
 }
 setSopAcknowledgements(data || [])
 } catch(e) {
 setSopAcknowledgements([])
 } finally {
 setSopAckLoading(false)
 }
 }

 async function refreshSopLibrary(options = {}) {
 const silent = options?.silent === true
 await Promise.all([loadSops(), loadSopAcknowledgements(), loadEmployees()])
 if (!silent) showToast('SOP Library refreshed.')
 }

 function isSopAcknowledgedByEmployee(sop, emp, records = sopAcknowledgements) {
 if (!sop?.id || !emp?.id) return false
 return (records || []).some(row =>
 String(row.sop_id || '') === String(sop.id) &&
 String(row.employee_id || '') === String(emp.id) &&
 String(row.version || '') === String(sop.version || '') &&
 String(row.status || 'acknowledged').toLowerCase() === 'acknowledged'
 )
 }

 function getEmployeeSopAckRecord(sop, records = mySopAckRecords) {
 if (!sop?.id || !employee?.id) return null
 return (records || []).find(row =>
 String(row.sop_id || '') === String(sop.id) &&
 String(row.employee_id || '') === String(employee.id) &&
 String(row.version || '') === String(sop.version || '') &&
 String(row.status || 'acknowledged').toLowerCase() === 'acknowledged'
 ) || null
 }

 async function loadMySops(emp = employee) {
 if (!emp?.id) return
 setMySopsLoading(true)
 try {
 const { data:sopData, error:sopError } = await supabase
 .from('sop_documents')
 .select('*')
 .eq('status', 'active')
 .eq('acknowledgement_required', true)
 .order('sop_code', { ascending:true })
 if (sopError) throw sopError

 const { data:ackData, error:ackError } = await supabase
 .from('sop_acknowledgements')
 .select('*')
 .eq('employee_id', emp.id)
 .order('acknowledged_at', { ascending:false })
 if (ackError) throw ackError

 setMySopDocuments(sopData || [])
 setMySopAckRecords(ackData || [])
 } catch(e) {
 console.warn('loadMySops:', e?.message || e)
 setMySopDocuments([])
 setMySopAckRecords([])
 } finally {
 setMySopsLoading(false)
 }
 }

 async function acknowledgeMySop(sop) {
 if (!employee?.id || !sop?.id) return
 if (String(sop.status || '').toLowerCase() !== 'active') { showToast('Only active SOPs can be acknowledged.', 'red'); return }
 setAcknowledgingSopId(sop.id)
 try {
 const existing = getEmployeeSopAckRecord(sop)
 const payload = {
 sop_id:sop.id,
 sop_code:sop.sop_code || '',
 version:sop.version || '1.0',
 employee_id:employee.id,
 employee_code:employee.employee_code || '',
 employee_name:employee.full_name || '',
 role:employee.position || employee.department || 'Employee',
 status:'acknowledged',
 acknowledged_at:new Date().toISOString(),
 remarks:'Employee acknowledged through employee portal.'
 }

 let error
 if (existing?.id) {
 ;({ error } = await supabase.from('sop_acknowledgements').update(payload).eq('id', existing.id))
 } else {
 ;({ error } = await supabase.from('sop_acknowledgements').insert(payload))
 }
 if (error) throw error

 await logAudit('SOP ACKNOWLEDGED', employee.full_name || employee.employee_code || 'Employee', sop.sop_code || '', sop.title || '')
 showToast('SOP acknowledged successfully.')
 await loadMySops(employee)
 await loadSopAcknowledgements()
 setViewingMySop(null)
 } catch(e) {
 showToast('SOP acknowledgement failed: ' + (e?.message || 'Unknown error'), 'red')
 } finally {
 setAcknowledgingSopId(null)
 }
 }

 async function saveSopDocument() {
 if (!canManageSops()) { showToast('Only Owner or Manager can save SOPs.', 'red'); return }
 if (!sopForm.sop_code.trim() || !sopForm.title.trim()) {
 showToast('SOP code and title are required.', 'red')
 return
 }

 setSavingSop(true)
 try {
 const payload = {
 sop_code:sopForm.sop_code.trim(),
 title:sopForm.title.trim(),
 department:sopForm.department || 'Production',
 category:sopForm.category || 'Operations',
 version:sopForm.version || '1.0',
 effective_date:sopForm.effective_date || today,
 status:sopForm.status || 'draft',
 access_roles:sopForm.access_roles || 'owner,manager,hr,supervisor,asst_supervisor',
 acknowledgement_required:sopForm.acknowledgement_required !== false,
 purpose:sopForm.purpose || '',
 procedure:sopForm.procedure || '',
 required_records:sopForm.required_records || '',
 approved_by:sopForm.approved_by || currentAdminLabel,
 notes:sopForm.notes || '',
 updated_by:currentAdminLabel
 }

 let error
 if (editingSopId) {
 ;({ error } = await supabase.from('sop_documents').update(payload).eq('id', editingSopId))
 } else {
 ;({ error } = await supabase.from('sop_documents').insert({ ...payload, created_by:currentAdminLabel }))
 }

 if (error) throw error

 await logAudit(editingSopId? 'SOP UPDATED':'SOP CREATED', currentAdminLabel, payload.sop_code, payload.title)
 showToast(editingSopId? 'SOP updated successfully.':'SOP created successfully.')
 setShowSopForm(false)
 resetSopForm()
 loadSops()
 } catch(e) {
 showToast('SOP save failed: ' + (e?.message || 'Unknown error'), 'red')
 } finally {
 setSavingSop(false)
 }
 }

