 function getPayrollReadinessBlockMessage(readiness = payrollReadiness) {
  if (!readiness) return 'Payroll readiness has not been checked.'
  const parts = []
  if ((readiness.attendanceExceptions || []).length > 0) parts.push(`${readiness.attendanceExceptions.length} unresolved attendance exception(s)`)
  if ((readiness.missingEmployees || []).length > 0) parts.push(`${readiness.missingEmployees.length} active employee(s) missing a payroll row`)
  if ((readiness.duplicateEmployees || []).length > 0) parts.push(`${readiness.duplicateEmployees.length} duplicate employee payroll row(s)`)
  return parts.length > 0 ? `Payroll is not ready: ${parts.join(', ')}.` : 'Payroll is ready.'
 }

 async function inspectPayrollReadiness(start = payrollStart, end = payrollEnd, options = {}) {
  const updateState = options.updateState !== false
  if (!start || !end || parseLocalDate(end) < parseLocalDate(start)) {
   const invalid = { ready:false, attendanceExceptions:[], missingEmployees:[], duplicateEmployees:[], activeEmployeeCount:0, payrollRecordCount:0, error:'Invalid payroll period.' }
   if (updateState) setPayrollReadiness(invalid)
   return invalid
  }

  if (updateState) setPayrollReadinessLoading(true)
  try {
   const { data:activeEmployees, error:employeeError } = await supabase
    .from('employees')
    .select('id,employee_code,full_name,position,is_active')
    .eq('is_active', true)
    .order('full_name')
   if (employeeError) throw employeeError

   const activeList = activeEmployees || []
   const employeeIds = activeList.map(emp => emp.id).filter(Boolean)
   let attendanceRows = []
   if (employeeIds.length > 0) {
    const { data, error } = await supabase
     .from('attendance_logs')
     .select('*')
     .in('employee_id', employeeIds)
     .gte('attendance_date', start)
     .lte('attendance_date', end)
     .order('attendance_date')
     .limit(5000)
    if (error) throw error
    attendanceRows = data || []
   }

   const { data:payrollRows, error:payrollError } = await supabase
    .from('payroll_records')
    .select('id,employee_id,employee_code,employee_name,payroll_approved,approved_at,employee_acknowledgement,payroll_status')
    .eq('payroll_start', start)
    .eq('payroll_end', end)
    .limit(5000)
   if (payrollError) throw payrollError

   const logsByEmployee = {}
   ;(attendanceRows || []).forEach(log => {
    const key = String(log?.employee_id || '')
    if (!key) return
    if (!logsByEmployee[key]) logsByEmployee[key] = []
    logsByEmployee[key].push(log)
   })

   const attendanceExceptions = []
   activeList.forEach(emp => {
    const grouped = groupDTRLogsByDate(logsByEmployee[String(emp.id)] || [])
    Object.entries(grouped).forEach(([dateKey, dayLogs]) => {
     const integrity = getAttendanceDayIntegrity(dayLogs)
     if (integrity.isIncomplete || integrity.isInvalidShortPunch) {
      attendanceExceptions.push(buildPayrollAttendanceException(emp, dateKey, dayLogs, integrity))
     }
    })
   })

   const payrollRowsByEmployee = {}
   ;(payrollRows || []).forEach(row => {
    const key = String(row?.employee_id || '')
    if (!key) return
    if (!payrollRowsByEmployee[key]) payrollRowsByEmployee[key] = []
    payrollRowsByEmployee[key].push(row)
   })

   const missingEmployees = activeList
    .filter(emp => !(payrollRowsByEmployee[String(emp.id)] || []).length)
    .map(emp => ({ employeeId:emp.id, employeeCode:emp.employee_code || '', employeeName:emp.full_name || 'Employee', position:emp.position || '' }))
   const duplicateEmployees = activeList
    .map(emp => ({ employeeId:emp.id, employeeCode:emp.employee_code || '', employeeName:emp.full_name || 'Employee', count:(payrollRowsByEmployee[String(emp.id)] || []).length }))
    .filter(item => item.count > 1)

   const heldEmployeeIds = Array.from(new Set(attendanceExceptions.map(item => String(item.employeeId || '')).filter(Boolean)))
   const readiness = {
    start,
    end,
    checkedAt:new Date().toISOString(),
    activeEmployeeCount:activeList.length,
    payrollRecordCount:(payrollRows || []).length,
    readyPayrollEmployeeCount:activeList.length - missingEmployees.length,
    attendanceExceptions,
    heldEmployeeIds,
    missingEmployees,
    duplicateEmployees,
    ready:attendanceExceptions.length === 0 && missingEmployees.length === 0 && duplicateEmployees.length === 0 && (payrollRows || []).length > 0
   }
   if (updateState) setPayrollReadiness(readiness)
   if (!options.silent) showToast(getPayrollReadinessBlockMessage(readiness), readiness.ready ? 'green':'red')
   return readiness
  } catch(error) {
   console.error('Payroll readiness check failed:', error)
   const failed = { ready:false, attendanceExceptions:[], missingEmployees:[], duplicateEmployees:[], activeEmployeeCount:0, payrollRecordCount:0, error:error?.message || String(error) }
   if (updateState) setPayrollReadiness(failed)
   if (!options.silent) showToast('Payroll readiness check failed: ' + failed.error, 'red')
   return failed
  } finally {
   if (updateState) setPayrollReadinessLoading(false)
  }
 }

 async function openPayrollAttendanceExceptionDTR(issue = {}) {
  if (!issue?.employeeId || !issue?.attendanceDate) { showToast('Attendance exception details are incomplete.', 'red'); return }
  await openAttendanceReconciliationSourceDTR({
   employeeId:issue.employeeId,
   employeeName:issue.employeeName,
   sourceStart:payrollStart,
   sourceEnd:payrollEnd,
   dayDetails:[{ date:issue.attendanceDate, undertimeMinutes:1 }]
  }, issue.attendanceDate)
 }

 async function rebuildPayrollDraftAfterAttendanceCorrections() {
  if (!requireOwnerOrPayrollAction('rebuild payroll after attendance corrections')) return
  const readiness = await inspectPayrollReadiness(payrollStart, payrollEnd, { silent:true })
  if ((readiness.attendanceExceptions || []).length > 0) {
   showToast(`Rebuild blocked: ${readiness.attendanceExceptions.length} attendance exception(s) still require correction.`, 'red')
   return
  }
  if ((readiness.duplicateEmployees || []).length > 0) {
   showToast(`Rebuild blocked: ${readiness.duplicateEmployees.length} duplicate employee payroll row(s) must be corrected first.`, 'red')
   return
  }
  if ((readiness.missingEmployees || []).length === 0) {
   showToast('No employees are missing from this payroll draft. Refresh readiness or continue the payroll workflow.', 'green')
   return
  }

  const { data:records, error } = await supabase
   .from('payroll_records')
   .select('id,employee_name,employee_acknowledgement,payroll_approved,approved_at')
   .eq('payroll_start', payrollStart)
   .eq('payroll_end', payrollEnd)
   .limit(5000)
  if (error) { showToast('Failed to inspect the existing draft: ' + error.message, 'red'); return }
  if ((records || []).some(isReleasedPayrollRecord)) {
   showToast('Rebuild blocked: this payroll has already been released.', 'red')
   return
  }

  const reviewSentCount = (records || []).filter(isPayrollSentForEmployeeReview).length
  const warning = [
   `Rebuild payroll for ${payrollStart} to ${payrollEnd}?`,
   `${readiness.missingEmployees.length} corrected employee(s) are currently missing from the draft.`,
   'The existing unreleased draft will be deleted and every active employee will be recomputed using the corrected attendance.',
   reviewSentCount > 0 ? `${reviewSentCount} payslip(s) were already sent for review and will need to be sent again.` : ''
  ].filter(Boolean).join('\n')
  if (!window.confirm(warning)) return

  try {
   await supabase.from('payslip_disputes')
    .update({ status:'voided', admin_reason:`Payroll draft rebuilt after attendance correction by ${currentAdminLabel}`, reviewed_by:currentAdminLabel, reviewed_at:new Date().toISOString() })
    .eq('payroll_start', payrollStart)
    .eq('payroll_end', payrollEnd)
    .neq('status','resolved')
  } catch(error) { console.warn('Dispute voiding skipped during rebuild:', error) }

  const { error:deleteError } = await supabase.from('payroll_records')
   .delete()
   .eq('payroll_start', payrollStart)
   .eq('payroll_end', payrollEnd)
  if (deleteError) { showToast('Rebuild failed while removing the old draft: ' + deleteError.message, 'red'); return }
  try { await supabase.from('payroll_periods').delete().eq('payroll_start', payrollStart).eq('payroll_end', payrollEnd) } catch(error) {}

  setPayrollResults([])
  setPayrollSummary(null)
  setPayrollReadiness(null)
  setPayrollApproved(false)
  await logAudit('PAYROLL DRAFT REBUILD STARTED', currentAdminLabel, 'Payroll', `Period: ${payrollStart} to ${payrollEnd} | Corrected missing employees: ${readiness.missingEmployees.length}`)
  await computePayroll()
 }

 function mapSavedPayrollRecordToResult(record = {}, employeeLookup = {}) {
 const emp = employeeLookup[String(record.employee_id || '')] || {}
 const dailyRate = safeNum(emp.daily_rate, 0)
 const ack = record.employee_acknowledgement || 'draft'
 const status = record.payroll_status || (isReleasedPayrollRecord(record)? 'released': (ack === 'draft'? 'draft':'under_review'))
 return {
  id: record.id,
  savedRecordId: record.id,
  employeeId: record.employee_id,
  employeeCode: record.employee_code || emp.employee_code || '',
  employeeName: record.employee_name || emp.full_name || '',
  position: emp.position || record.position || '',
  workedDays: safeNum(record.worked_days, 0),
  absentDays: safeNum(record.absent_days, 0),
  paidLeaveDays: safeNum(record.paid_leave_days, 0),
  unpaidLeaveDays: safeNum(record.unpaid_leave_days, 0),
  paidLeavePay: safeNum(record.paid_leave_pay, 0),
  workedBasicPay: safeNum(record.worked_basic_pay ?? record.basic_pay, 0),
  totalWorkedMinutes: safeNum(record.total_worked_minutes, 0),
  regularPaidMinutes: safeNum(record.regular_paid_minutes, safeNum(record.worked_days, 0) * 8 * 60),
  hourlyRate: dailyRate > 0? dailyRate / 8: 0,
  basicPay: safeNum(record.basic_pay, 0),
  birthdayPay: safeNum(record.birthday_pay, 0),
  overtimePay: safeNum(record.overtime_pay, 0),
  overtimeMinutes: safeNum(record.overtime_minutes, 0),
  nightDiffPay: safeNum(record.night_diff_pay, 0),
  nightDiffMinutes: safeNum(record.night_diff_minutes, 0),
  holidayPay: safeNum(record.holiday_pay, 0),
  adjustmentEarnings: safeNum(record.other_earnings, 0),
  adjustmentItems:getPayslipAdjustmentItems(record),
  totalEarnings: safeNum(record.total_earnings, 0),
  cashAdvanceDeduction: safeNum(record.cash_advance_deduction, 0),
  cashAdvanceItems:getPayslipCashAdvanceItems(record),
  requestedCashAdvanceDeduction: safeNum(record.requested_cash_advance_deduction, safeNum(record.cash_advance_deduction, 0)),
  deferredCADeduction: safeNum(record.deferred_cash_advance_deduction, 0),
  nonCADeductionOverflow: safeNum(record.non_ca_deduction_overflow, Math.max(0, safeNum(record.total_deductions,0)-safeNum(record.total_earnings,0))),
  sssDeduction: safeNum(record.sss_deduction, 0),
  pagibigDeduction: safeNum(record.pagibig_deduction, 0),
  philhealthDeduction: safeNum(record.philhealth_deduction, 0),
  lateDeduction: safeNum(record.late_deduction, 0),
  undertimeDeduction: safeNum(record.undertime_deduction, 0),
  adjustmentDeductions: safeNum(record.other_deductions, 0),
  absenceDeduction:safeNum(record.absence_deduction, 0),
  totalDeductions: safeNum(record.total_deductions, 0),
  netPay: safeNum(record.net_pay, 0),
  lateMinutes: safeNum(record.late_minutes, 0),
  undertimeMinutes: safeNum(record.undertime_minutes, 0),
  payrollCostType: record.payroll_cost_type || 'auto',
  payrollCostLabel: record.payroll_cost_label || '',
  bankName: emp.bank_name || '',
  bankAccount: emp.bank_account_number || '',
  bankAccountName: emp.bank_account_name || '',
  mobileNumber: emp.contact_number || '',
  payslipSerial: record.payslip_serial || '',
  employeeAcknowledgement: ack,
  payrollStatus: status,
  reviewSentAt: record.review_sent_at || null,
  reviewSentBy: record.review_sent_by || '',
  payrollApproved: record.payroll_approved === true,
  approvedAt: record.approved_at || null
 }
 }

 async function loadSavedPayrollForPeriod(start = payrollStart, end = payrollEnd, options = {}) {
 if (!start ||!end) { showToast('Please select payroll start and end dates.', 'red'); return [] }
 if (parseLocalDate(end) < parseLocalDate(start)) { showToast('Payroll end date must be after start date.', 'red'); return [] }

 setPayrollComputing(true)
 try {
  const { data:records, error } = await supabase
  .from('payroll_records')
  .select('*')
  .eq('payroll_start', start)
  .eq('payroll_end', end)
  .order('employee_name', { ascending:true })

  if (error) throw error
  if (!records || records.length === 0) {
   setPayrollResults([])
   setPayrollSummary(null)
   if (!options.silent) showToast('No saved payroll found for this exact period. Check the From/To dates or open Payroll History.', 'red')
   return []
  }

  const employeeIds = [...new Set(records.map(r=>r.employee_id).filter(Boolean))]
  let employeeLookup = {}
  if (employeeIds.length > 0) {
   const { data:empRows, error:empError } = await supabase
   .from('employees')
   .select(EMPLOYEE_SELECT_FIELDS)
   .in('id', employeeIds)
   if (!empError) {
    ;(empRows || []).forEach(emp => { employeeLookup[String(emp.id)] = emp })
   }
  }

  const enrichedRecords = await enrichPayrollRecordsWithPayslipBreakdowns(records)
  const results = enrichedRecords.map(r => mapSavedPayrollRecordToResult(r, employeeLookup))
  const uniqueEmployees = new Set(results.map(r=>String(r.employeeId || r.employeeCode || r.employeeName))).size
  const duplicateCount = results.length - uniqueEmployees

  setPayrollStart(start)
  setPayrollEnd(end)
  setPayrollResults(results)
  setPayrollSummary(buildPayrollSummaryFromResults(results))
  setPayrollApproved(results.some(r=>r.payrollApproved || !!r.approvedAt))
  await inspectPayrollReadiness(start, end, { silent:true })

  if (!options.silent) {
   showToast(`Saved payroll loaded: ${results.length} payslip${results.length === 1? '': 's'} for ${start} to ${end}.${duplicateCount > 0? ' Warning: duplicate employee payslips detected.': ''}`, duplicateCount > 0? 'red':'green')
  }
  return results
 } catch(err) {
  console.error('Saved payroll load failed:', err)
  setPayrollResults([])
  setPayrollSummary(null)
  setPayrollReadiness(null)
  showToast('Failed to load saved payroll: ' + (err?.message || err), 'red')
  return []
 } finally {
  setPayrollComputing(false)
 }
 }


 function normalizePayrollBankName(value = '') {
  const raw = String(value || '').trim()
  const key = raw.toLowerCase().replace(/[^a-z0-9]/g, '')
  if (!key) return ''
  if (key === 'rcbc' || key.includes('rizalcommercialbank')) return 'RCBC'
  if (key === 'bdo' || key.includes('bancodeoro')) return 'BDO'
  if (key === 'bpi' || key.includes('bankofthephilippineislands')) return 'BPI'
  if (key.includes('unionbank')) return 'UnionBank'
  if (key.includes('landbank')) return 'Landbank'
  if (key.includes('gcash')) return 'GCash'
  if (key.includes('metrobank')) return 'Metrobank'
  if (key === 'pnb' || key.includes('philippinenationalbank')) return 'PNB'
  if (key.includes('securitybank')) return 'Security Bank'
  if (key.includes('maya')) return 'Maya'
  return raw
 }

 function normalizeBankAccountForExport(value = '') {
  return String(value || '').trim().replace(/[\s-]+/g, '')
 }

 function getRCBCExportRowError(row = {}) {
  const accountNumber = normalizeBankAccountForExport(row.bankAccount)
  const accountName = String(row.bankAccountName || row.employeeName || '').trim()
  const netPay = Number(row.netPay)

  if (!accountNumber) return 'missing account number'
  if (!/^\d+$/.test(accountNumber)) return 'account number must contain digits only'
  if (!/^(?:\d{10}|\d{16})$/.test(accountNumber)) return 'account number must be 10 or 16 digits'
  if (!accountName) return 'missing account name'
  if (!Number.isFinite(netPay) || netPay <= 0) return 'net pay must be a positive amount'
  if (Math.abs(moneyRound(netPay) - netPay) > 0.000001) return 'net pay must have no more than two decimal places'
  return ''
 }

 function getRCBCExportValidation(rows = []) {
  const invalidRows = (rows || []).map(row => ({ row, error:getRCBCExportRowError(row) })).filter(item => item.error)
  const validRows = (rows || []).filter(row => !getRCBCExportRowError(row))
  const duplicateNames = getDuplicateBankAccountNames(validRows, 'RCBC')
  return {
   invalidRows,
   validRows,
   duplicateNames,
   valid:invalidRows.length === 0 && duplicateNames.length === 0
  }
 }

 function getRCBCExportReadiness(rows = []) {
  const validation = getRCBCExportValidation(rows)
  const missingAccountRows = validation.invalidRows.filter(item => item.error === 'missing account number')
  const blockingInvalidRows = validation.invalidRows.filter(item => item.error !== 'missing account number')
  return {
   ...validation,
   missingAccountRows,
   blockingInvalidRows,
   canExport:validation.validRows.length > 0 && blockingInvalidRows.length === 0 && validation.duplicateNames.length === 0
  }
 }

 function confirmRCBCMissingAccountExclusions(missingAccountRows = []) {
  if (!missingAccountRows.length) return true
  const names = missingAccountRows.map(({ row }) => row.employeeName || row.employeeCode || 'Employee')
  const excludedTotal = missingAccountRows.reduce((sum, { row }) => sum + safeNum(row.netPay, 0), 0)
  return window.confirm(
   `RCBC EXPORT WARNING\n\n${missingAccountRows.length} employee(s) have no bank account and will NOT be included in this RCBC file:\n\n${names.join('\n')}\n\nExcluded net pay: ${php(excludedTotal)}\n\nPay these employees separately. Continue with the employees who have valid RCBC accounts?`
  )
 }

 function buildEmployeeBankDraft(row = {}) {
  return {
   bankName:normalizePayrollBankName(row.bank_name || ''),
   accountName:String(row.bank_account_name || row.full_name || '').trim(),
   accountNumber:String(row.bank_account_number || '').trim()
  }
 }

 function getEmployeeBankDraft(row = {}) {
  return employeeBankDrafts[String(row?.id || '')] || buildEmployeeBankDraft(row)
 }

 function updateEmployeeBankDraft(employeeId = '', field = '', value = '') {
  setEmployeeBankDrafts(prev => ({
   ...prev,
   [String(employeeId)]:{
    ...(prev[String(employeeId)] || buildEmployeeBankDraft(employeeBankRows.find(row => String(row.id) === String(employeeId)) || {})),
    [field]:value
   }
  }))
 }

 function isEmployeeBankDraftChanged(row = {}) {
  const draft = getEmployeeBankDraft(row)
  const saved = buildEmployeeBankDraft(row)
  return normalizePayrollBankName(draft.bankName) !== normalizePayrollBankName(saved.bankName)
   || String(draft.accountName || '').trim() !== String(saved.accountName || '').trim()
   || String(draft.accountNumber || '').trim() !== String(saved.accountNumber || '').trim()
 }

 function getEmployeeBankDraftValidation(rows = employeeBankRows) {
  const accountOwnerByKey = {}
  const duplicateRows = []
  ;(rows || []).forEach(row => {
   const draft = getEmployeeBankDraft(row)
   const bankName = normalizePayrollBankName(draft.bankName)
   const accountNumber = normalizeBankAccountForExport(draft.accountNumber)
   if (!bankName || !accountNumber) return
   const key = `${bankName.toLowerCase()}|${accountNumber}`
   if (accountOwnerByKey[key] && String(accountOwnerByKey[key].id) !== String(row.id)) {
    duplicateRows.push(accountOwnerByKey[key], row)
   } else {
    accountOwnerByKey[key] = row
   }
  })
  const uniqueDuplicateRows = [...new Map(duplicateRows.map(row => [String(row.id), row])).values()]
  return { duplicateRows:uniqueDuplicateRows, valid:uniqueDuplicateRows.length === 0 }
 }

 async function loadEmployeeBankAccounts(options = {}) {
  setEmployeeBankLoading(true)
  try {
   const { data, error } = await supabase
    .from('employees')
    .select('id,employee_code,full_name,position,department,contact_number,bank_name,bank_account_name,bank_account_number')
    .eq('is_active', true)
    .order('full_name', { ascending:true })
   if (error) throw error
   const rows = data || []
   setEmployeeBankRows(rows)
   setEmployeeBankDrafts(Object.fromEntries(rows.map(row => [String(row.id), buildEmployeeBankDraft(row)])))
   if (!options.silent) showToast(`Loaded ${rows.length} active employee bank profile(s).`)
   return rows
  } catch(error) {
   console.error('Employee bank-account load failed:', error)
   if (!options.silent) showToast('Failed to load employee bank accounts: ' + (error?.message || error), 'red')
   return []
  } finally {
   setEmployeeBankLoading(false)
  }
 }

 async function saveEmployeeBankAccount(row = {}, options = {}) {
  if (!row?.id) return false
  if (!requireOwnerOrPayrollAction('save employee payroll bank details')) return false

  const validation = getEmployeeBankDraftValidation()
  if (!validation.valid) {
   showToast(`Duplicate bank account blocked. Check: ${validation.duplicateRows.map(item => item.full_name).join(', ')}`, 'red')
   return false
  }

  const draft = getEmployeeBankDraft(row)
  const payload = {
   bank_name:normalizePayrollBankName(draft.bankName),
   bank_account_name:String(draft.accountName || row.full_name || '').trim(),
   bank_account_number:String(draft.accountNumber || '').trim()
  }

  if (!options.skipLoading) setEmployeeBankSavingIds(prev => ({ ...prev, [row.id]:true }))
  try {
   const { data, error } = await supabase
    .from('employees')
    .update(payload)
    .eq('id', row.id)
    .select('id,employee_code,full_name,position,department,contact_number,bank_name,bank_account_name,bank_account_number')
    .single()
   if (error) throw error

   setEmployeeBankRows(prev => prev.map(item => String(item.id) === String(row.id) ? { ...item, ...data } : item))
   setEmployeeBankDrafts(prev => ({ ...prev, [String(row.id)]:buildEmployeeBankDraft({ ...row, ...data }) }))
   setPayrollResults(prev => prev.map(item => String(item.employeeId) === String(row.id) ? {
    ...item,
    bankName:data.bank_name || '',
    bankAccount:data.bank_account_number || '',
    bankAccountName:data.bank_account_name || data.full_name || item.employeeName || ''
   } : item))

   if (!options.silent) {
    await logAudit('EMPLOYEE PAYROLL BANK UPDATED', currentAdminLabel, row.full_name || row.employee_code || 'Employee', `Bank: ${payload.bank_name || 'Not assigned'} | Account details ${payload.bank_account_number ? 'saved' : 'cleared'}`)
    showToast(`${row.full_name} bank details saved.`)
   }
   return true
  } catch(error) {
   console.error('Employee bank-account save failed:', error)
   if (!options.silent) showToast(`Failed to save ${row.full_name}: ${error?.message || error}`, 'red')
   return false
  } finally {
   if (!options.skipLoading) setEmployeeBankSavingIds(prev => ({ ...prev, [row.id]:false }))
  }
 }

 async function saveAllEmployeeBankAccounts() {
  if (!requireOwnerOrPayrollAction('save all employee payroll bank details')) return
  const validation = getEmployeeBankDraftValidation()
  if (!validation.valid) {
   showToast(`Duplicate bank account blocked. Check: ${validation.duplicateRows.map(item => item.full_name).join(', ')}`, 'red')
   return
  }

  const changedRows = employeeBankRows.filter(isEmployeeBankDraftChanged)
  if (changedRows.length === 0) {
   showToast('No bank-account changes to save.', 'orange')
   return
  }

  setEmployeeBankSavingAll(true)
  const failed = []
  try {
   for (const row of changedRows) {
    const ok = await saveEmployeeBankAccount(row, { silent:true, skipLoading:true })
    if (!ok) failed.push(row.full_name || row.employee_code || 'Employee')
   }
   await logAudit('EMPLOYEE PAYROLL BANK MASTER UPDATED', currentAdminLabel, 'Payroll Bank Accounts', `Changed profiles: ${changedRows.length} | Failed: ${failed.length}`)
   if (failed.length > 0) showToast(`Saved ${changedRows.length - failed.length}; failed: ${failed.join(', ')}`, 'red')
   else showToast(`${changedRows.length} employee bank profile(s) saved.`)
  } finally {
   setEmployeeBankSavingAll(false)
  }
 }

 async function loadBankDisbursementPeriod() {
  if (!payrollStart || !payrollEnd) { showToast('Select a payroll From and To date.', 'red'); return }
  if (parseLocalDate(payrollEnd) < parseLocalDate(payrollStart)) { showToast('Payroll end date must be after the start date.', 'red'); return }

  try {
   const { data:records, error } = await supabase
    .from('payroll_records')
    .select('id,employee_id,employee_name,employee_code,worked_days,net_pay,basic_pay,birthday_pay,overtime_pay,total_earnings,total_deductions,payroll_approved,approved_at')
    .eq('payroll_start', payrollStart)
    .eq('payroll_end', payrollEnd)
    .order('employee_name', { ascending:true })
   if (error) throw error
   if (!(records || []).length) {
    setPayrollResults([])
    showToast('No payroll records found for this period. Compute payroll first.', 'red')
    return
   }

   const employeeIds = [...new Set((records || []).map(row => row.employee_id).filter(Boolean))]
   let employeeLookup = {}
   if (employeeIds.length > 0) {
    const { data:employeeRows, error:employeeError } = await supabase
     .from('employees')
     .select('id,employee_code,full_name,position,department,contact_number,bank_name,bank_account_name,bank_account_number')
     .in('id', employeeIds)
    if (employeeError) throw employeeError
    employeeLookup = Object.fromEntries((employeeRows || []).map(row => [String(row.id), row]))
   }

   const results = (records || []).map(record => {
    const emp = employeeLookup[String(record.employee_id || '')] || {}
    return {
     employeeId:record.employee_id,
     employeeName:record.employee_name || emp.full_name || '',
     employeeCode:record.employee_code || emp.employee_code || '',
     position:emp.position || emp.department || '',
     workedDays:safeNum(record.worked_days, 0),
     netPay:safeNum(record.net_pay, 0),
     basicPay:safeNum(record.basic_pay, 0),
     birthdayPay:safeNum(record.birthday_pay, 0),
     overtimePay:safeNum(record.overtime_pay, 0),
     totalEarnings:safeNum(record.total_earnings, 0),
     totalDeductions:safeNum(record.total_deductions, 0),
     bankName:normalizePayrollBankName(emp.bank_name || ''),
     bankAccount:String(emp.bank_account_number || '').trim(),
     bankAccountName:String(emp.bank_account_name || emp.full_name || record.employee_name || '').trim(),
     mobileNumber:String(emp.contact_number || '').trim(),
     payrollApproved:record.payroll_approved === true || !!record.approved_at
    }
   })

   setPayrollResults(results)
   const missingCount = results.filter(row => safeNum(row.netPay, 0) > 0 && !normalizeBankAccountForExport(row.bankAccount)).length
   showToast(`Loaded ${results.length} payroll row(s). ${missingCount} positive-pay employee(s) still have no bank account number.`, missingCount > 0 ? 'orange' : 'green')
  } catch(error) {
   console.error('Bank disbursement payroll load failed:', error)
   setPayrollResults([])
   showToast('Failed to load bank disbursement payroll: ' + (error?.message || error), 'red')
  }
 }

 function getPayrollRowsForBank(bank = '') {
  const normalizedBank = normalizePayrollBankName(bank)
  const positiveRows = (payrollResults || []).filter(row => safeNum(row.netPay, 0) > 0)
  if (normalizedBank === 'Generic') return positiveRows
  return positiveRows.filter(row => normalizePayrollBankName(row.bankName) === normalizedBank)
 }

 async function downloadPayrollBankCSV(bank = '') {
  const normalizedBank = normalizePayrollBankName(bank)
  if (normalizedBank === 'RCBC') {
   await downloadRCBCGeneratorExcel()
   return
  }
  const assignedRows = getPayrollRowsForBank(normalizedBank)
  if (assignedRows.length === 0) {
   showToast(`No positive-net-pay employee is assigned to ${normalizedBank}. Save employee bank assignments first.`, 'red')
   return
  }

  // Incomplete account details no longer block the whole payroll file.
  // Export only complete employees and report the skipped names afterward.
  const skippedRows = assignedRows.filter(row => {
   if (normalizedBank === 'GCash') return !normalizeBankAccountForExport(row.mobileNumber || row.bankAccount)
   return !normalizeBankAccountForExport(row.bankAccount)
  })
  const selectedRows = assignedRows.filter(row => !skippedRows.includes(row))

  if (selectedRows.length === 0) {
   showToast(`${normalizedBank} file not created: all ${assignedRows.length} assigned employee(s) have incomplete account details.`, 'red')
   return
  }

  const accountOwners = {}
  const duplicateNames = new Set()
  selectedRows.forEach(row => {
   const account = normalizeBankAccountForExport(normalizedBank === 'GCash' ? (row.mobileNumber || row.bankAccount) : row.bankAccount)
   if (!account) return
   if (accountOwners[account] && String(accountOwners[account].employeeId) !== String(row.employeeId)) {
    duplicateNames.add(accountOwners[account].employeeName)
    duplicateNames.add(row.employeeName)
   } else {
    accountOwners[account] = row
   }
  })
  if (duplicateNames.size > 0) {
   showToast(`${normalizedBank} download blocked: duplicate account number detected for ${[...duplicateNames].join(', ')}.`, 'red')
   return
  }

  const periodText = `${payrollStart} to ${payrollEnd}`
  const rows = []
  if (normalizedBank === 'RCBC') {
   rows.push(['Account Number','Account Name','Amount'])
   selectedRows.forEach(row => rows.push([
    normalizeBankAccountForExport(row.bankAccount),
    row.bankAccountName || row.employeeName,
    safeNum(row.netPay, 0).toFixed(2)
   ]))
  } else if (normalizedBank === 'BDO') {
   rows.push(['AccountNo','BeneficiaryName','Amount','Currency','Remarks'])
   selectedRows.forEach(row => rows.push([
    normalizeBankAccountForExport(row.bankAccount),
    row.bankAccountName || row.employeeName,
    safeNum(row.netPay, 0).toFixed(2),
    'PHP',
    `Payroll ${periodText}`
   ]))
  } else if (normalizedBank === 'BPI') {
   rows.push(['Account Number','Name','Amount','Remarks'])
   selectedRows.forEach(row => rows.push([
    normalizeBankAccountForExport(row.bankAccount),
    row.bankAccountName || row.employeeName,
    safeNum(row.netPay, 0).toFixed(2),
    `Payroll ${periodText}`
   ]))
  } else if (normalizedBank === 'UnionBank') {
   rows.push(['AccountNo','BeneficiaryName','Amount','Particulars'])
   selectedRows.forEach(row => rows.push([
    normalizeBankAccountForExport(row.bankAccount),
    row.bankAccountName || row.employeeName,
    safeNum(row.netPay, 0).toFixed(2),
    `Salary ${payrollEnd}`
   ]))
  } else if (normalizedBank === 'Landbank') {
   rows.push(['Account','Name','Amount','Description'])
   selectedRows.forEach(row => rows.push([
    normalizeBankAccountForExport(row.bankAccount),
    row.bankAccountName || row.employeeName,
    safeNum(row.netPay, 0).toFixed(2),
    `Payroll ${payrollStart}-${payrollEnd}`
   ]))
  } else if (normalizedBank === 'GCash') {
   rows.push(['Mobile Number','Name','Amount','Reference'])
   selectedRows.forEach(row => rows.push([
    normalizeBankAccountForExport(row.mobileNumber || row.bankAccount),
    row.bankAccountName || row.employeeName,
    safeNum(row.netPay, 0).toFixed(2),
    `${row.employeeCode}-${payrollEnd}`
   ]))
  } else {
   rows.push(['Employee Code','Name','Bank','Account No','Net Pay'])
   selectedRows.forEach(row => rows.push([
    row.employeeCode,
    row.bankAccountName || row.employeeName,
    row.bankName || '',
    normalizeBankAccountForExport(row.bankAccount),
    safeNum(row.netPay, 0).toFixed(2)
   ]))
  }

  const csv = rows.map(row => row.map(value => `"${String(value ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n')
  const blob = new Blob(['\uFEFF' + csv], { type:'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = `${normalizedBank}_Payroll_${payrollStart}_to_${payrollEnd}.csv`
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  URL.revokeObjectURL(url)

  const totalAmount = selectedRows.reduce((sum, row) => sum + safeNum(row.netPay, 0), 0)
  const skippedNames = skippedRows.map(row => row.employeeName).filter(Boolean)
  await logAudit(
   'BANK PAYROLL CSV EXPORTED',
   currentAdminLabel,
   normalizedBank,
   `Period: ${periodText} | Exported: ${selectedRows.length} | Skipped incomplete: ${skippedRows.length} | Total: ${moneyRound(totalAmount).toFixed(2)}${skippedNames.length ? ` | Skipped names: ${skippedNames.join(', ')}` : ''}`
  )
  showToast(
   `${normalizedBank} payroll CSV downloaded: ${selectedRows.length} employee(s), ${php(totalAmount)}.${skippedRows.length ? ` Skipped ${skippedRows.length} incomplete employee(s): ${skippedNames.join(', ')}.` : ''}`,
   skippedRows.length ? 'orange' : 'green'
  )
 }


 function escapeSpreadsheetXml(value = '') {
  return String(value ?? '')
   .replace(/&/g, '&amp;')
   .replace(/</g, '&lt;')
   .replace(/>/g, '&gt;')
   .replace(/"/g, '&quot;')
   .replace(/'/g, '&apos;')
 }

 function getCompleteBankExportRows(bank = '') {
  const normalizedBank = normalizePayrollBankName(bank)
  const assignedRows = getPayrollRowsForBank(normalizedBank)
  const skippedRows = assignedRows.filter(row => {
   if (normalizedBank === 'GCash') return !normalizeBankAccountForExport(row.mobileNumber || row.bankAccount)
   return !normalizeBankAccountForExport(row.bankAccount)
  })
  const selectedRows = assignedRows.filter(row => !skippedRows.includes(row))
  return { normalizedBank, assignedRows, skippedRows, selectedRows }
 }

 function getDuplicateBankAccountNames(rows = [], bank = '') {
  const normalizedBank = normalizePayrollBankName(bank)
  const accountOwners = {}
  const duplicateNames = new Set()
  ;(rows || []).forEach(row => {
   const account = normalizeBankAccountForExport(
    normalizedBank === 'GCash' ? (row.mobileNumber || row.bankAccount) : row.bankAccount
   )
   if (!account) return
   if (accountOwners[account] && String(accountOwners[account].employeeId) !== String(row.employeeId)) {
    duplicateNames.add(accountOwners[account].employeeName)
    duplicateNames.add(row.employeeName)
   } else {
    accountOwners[account] = row
   }
  })
  return [...duplicateNames]
 }


 async function ensureXLSXLibrary() {
  if (window['XLSX']) return window['XLSX']
  await new Promise((resolve, reject) => {
   const existing = document.querySelector('script[data-romas-xlsx-library="true"]')
   if (existing) {
    existing.addEventListener('load', resolve, { once:true })
    existing.addEventListener('error', reject, { once:true })
    return
   }
   const script = document.createElement('script')
   script.src = 'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js'
   script.async = true
   script.dataset.romasXlsxLibrary = 'true'
   script.onload = resolve
   script.onerror = () => reject(new Error('Excel library failed to load. Check the internet connection and try again.'))
   document.head.appendChild(script)
  })
  if (!window['XLSX']) throw new Error('Excel library failed to initialize.')
  return window['XLSX']
 }

 async function downloadRCBCGeneratorExcel() {
  const assignedRows = getPayrollRowsForBank('RCBC')
  if (assignedRows.length === 0) {
   showToast('No positive-net-pay employee is assigned to RCBC.', 'red')
   return
  }

  const validation = getRCBCExportReadiness(assignedRows)
  if (validation.blockingInvalidRows.length > 0) {
   const invalidSummary = validation.blockingInvalidRows
    .slice(0, 5)
    .map(({ row, error }) => `${row.employeeName || row.employeeCode || 'Employee'} (${error})`)
    .join(', ')
   const remainingCount = Math.max(0, validation.blockingInvalidRows.length - 5)
   showToast(`RCBC generator Excel blocked. Correct ${validation.blockingInvalidRows.length} invalid employee row(s): ${invalidSummary}${remainingCount ? `, plus ${remainingCount} more` : ''}.`, 'red')
   return
  }

  if (validation.duplicateNames.length > 0) {
   showToast(`RCBC generator Excel blocked: duplicate account number detected for ${validation.duplicateNames.join(', ')}.`, 'red')
   return
  }

  if (validation.validRows.length === 0) {
   showToast('RCBC generator Excel not created: no employee has a complete, valid RCBC account yet.', 'red')
   return
  }

  if (!confirmRCBCMissingAccountExclusions(validation.missingAccountRows)) return

  try {
   const selectedRows = validation.validRows
   const XLSX = await ensureXLSXLibrary()
   const totalAmount = selectedRows.reduce((sum, row) => sum + safeNum(row.netPay, 0), 0)
   const periodText = `${payrollStart} to ${payrollEnd}`

   // This Excel workbook is the INPUT for RCBC's Employee Payments Client
   // Program. Do not upload this XLSX directly to RCBC Online Corporate.
   // The RCBC program must convert it into the bank payroll/credit text file.
   const worksheetData = [
    ['Account Number', 'Amount', 'Name'],
    ...selectedRows.map(row => [
     normalizeBankAccountForExport(row.bankAccount),
     Number(safeNum(row.netPay, 0).toFixed(2)),
     row.bankAccountName || row.employeeName
    ])
   ]

   const worksheet = XLSX.utils.aoa_to_sheet(worksheetData)

   // Force every account number cell to a true text/string cell so leading
   // zeroes remain intact when opened by Excel or RCBC's generator.
   for (let rowIndex = 2; rowIndex <= selectedRows.length + 1; rowIndex += 1) {
    const cellAddress = `A${rowIndex}`
    const accountValue = normalizeBankAccountForExport(selectedRows[rowIndex - 2].bankAccount)
    worksheet[cellAddress] = {
     t:'s',
     v:accountValue,
     z:'@'
    }
   }

   // Keep salary amounts numeric with two decimal places.
   for (let rowIndex = 2; rowIndex <= selectedRows.length + 1; rowIndex += 1) {
    const cellAddress = `B${rowIndex}`
    if (worksheet[cellAddress]) worksheet[cellAddress].z = '#,##0.00'
   }

   worksheet['!cols'] = [
    { wch:22 },
    { wch:16 },
    { wch:34 }
   ]
   worksheet['!autofilter'] = { ref:`A1:C${selectedRows.length + 1}` }
   worksheet['!freeze'] = { xSplit:0, ySplit:1, topLeftCell:'A2', activePane:'bottomLeft', state:'frozen' }

   const workbook = XLSX.utils.book_new()
   workbook.Props = {
    Title:`RCBC Generator Input ${periodText}`,
    Subject:'Excel input for the RCBC Employee Payments Client Program',
    Author:"Roma's Donuts",
    Company:"Roma's Donuts",
    CreatedDate:new Date()
   }
   XLSX.utils.book_append_sheet(workbook, worksheet, 'RCBC Generator Input')

   const filename = `RCBC_Generator_Input_${payrollStart}_to_${payrollEnd}.xlsx`
   XLSX.writeFile(workbook, filename, {
    bookType:'xlsx',
    compression:true,
    cellStyles:true
   })

   await logAudit(
    'RCBC GENERATOR EXCEL EXPORTED',
    currentAdminLabel,
    'RCBC',
    `Period: ${periodText} | Purpose: input for RCBC Employee Payments Client Program | Fields: Account Number, Amount, Name | Validated and exported: ${selectedRows.length} | Missing-account employees excluded for separate payment: ${validation.missingAccountRows.length} | Total: ${moneyRound(totalAmount).toFixed(2)}`
   )
   showToast(
    `RCBC generator Excel downloaded with ${selectedRows.length} employee row(s). ${validation.missingAccountRows.length} employee(s) without accounts were excluded and must be paid separately. Import this XLSX into the RCBC Employee Payments Client Program first.`,
    validation.missingAccountRows.length ? 'orange' : 'green'
   )
  } catch(error) {
   console.error('RCBC generator Excel export failed:', error)
   showToast(`RCBC generator Excel failed: ${error?.message || error}`, 'red')
  }
 }


 function getDefaultWeatherGuardDraft(dateValue = forecastDate) {
  return {
   weather_level:'no_warning',
   weather_source_type:'none',
   weather_location:'Pangasinan',
   weather_issued_at:'',
   weather_reference:'',
   class_status:'unverified',
   class_scope:'',
   class_source_type:'none',
   class_verified_by:'',
   class_verified_at:'',
   class_reference:'',
   route_status:'unverified',
   route_source_type:'none',
   route_verified_by:'',
   route_verified_at:'',
   route_reference:'',
   decision_cutoff_time:String(weatherGuardSettings?.decision_cutoff_time || '20:00').slice(0,5),
   decision_notes:'',
   delivery_date:dateValue
  }
 }

 function toWeatherGuardDateTimeLocal(value = '') {
  if (!value) return ''
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return String(value).slice(0,16)
  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000)
  return local.toISOString().slice(0,16)
 }

 function weatherGuardNowLocalInput() {
  const date = new Date()
  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000)
  return local.toISOString().slice(0,16)
 }

 function normalizeWeatherGuardTime(value = '20:00') {
  return String(value || '20:00').slice(0,5)
 }

 function getWeatherGuardFactors(draft = weatherGuardDraft) {
  const weatherFactorMap = {
   no_warning:1,
   watch:0.95,
   moderate_rain:0.85,
   heavy_rain:0.65,
   severe_weather:0.40
  }
  const classFactorMap = {
   normal:1,
   partial_suspension:0.50,
   fully_suspended:0,
   unverified:1
  }
  const unverifiedBaseSchoolFactorMap = {
   no_warning:1,
   watch:0.75,
   moderate_rain:0.50,
   heavy_rain:0.25,
   severe_weather:0
  }
  const weatherLevel = String(draft?.weather_level || 'no_warning')
  const classStatus = String(draft?.class_status || 'unverified')
  const nonSchoolFactor = weatherFactorMap[weatherLevel] ?? 1
  const schoolFactor = classFactorMap[classStatus] ?? 1
  const baseSchoolFactor = classStatus === 'unverified'
   ? (unverifiedBaseSchoolFactorMap[weatherLevel] ?? 1)
   : schoolFactor
  return { weatherLevel, classStatus, nonSchoolFactor, schoolFactor, baseSchoolFactor }
 }

 function getWeatherGuardProfileDraft(reseller = {}) {
  const key = String(reseller?.id || '')
  const saved = weatherGuardProfiles.find(row => String(row.reseller_id) === key)
  return weatherGuardProfileDrafts[key] || {
   reseller_id:key,
   municipality:saved?.municipality || reseller?.area || '',
   outlet_category:saved?.outlet_category || 'mixed',
   school_type:saved?.school_type || 'mixed',
   grade_level_market:saved?.grade_level_market || '',
   school_demand_pct:String(saved?.school_demand_pct ?? 50),
   route_name:saved?.route_name || reseller?.area || '',
   route_risk_level:saved?.route_risk_level || 'green',
   route_notes:saved?.route_notes || '',
   is_active:saved?.is_active !== false
  }
 }

 function updateWeatherGuardProfileDraft(resellerId = '', field = '', value = '') {
  const reseller = resellers.find(row => String(row.id) === String(resellerId)) || {}
  setWeatherGuardProfileDrafts(prev => ({
   ...prev,
   [String(resellerId)]:{
    ...getWeatherGuardProfileDraft(reseller),
    ...(prev[String(resellerId)] || {}),
    [field]:value
   }
  }))
 }

 function getWeatherGuardProfileForReseller(resellerId = '') {
  const reseller = resellers.find(row => String(row.id) === String(resellerId)) || {}
  return getWeatherGuardProfileDraft(reseller)
 }

 function getWeatherGuardDecisionKey(row = {}) {
  if (row?.reseller_id) return `reseller:${row.reseller_id}`
  const name = String(row?.reseller_name || row?.customer_name || row?.name || 'direct').trim().toLowerCase().replace(/[^a-z0-9]+/g,'-')
  return `direct:${name}`
 }

 function getWeatherGuardInvoiceQuantity(invoice = {}) {
  return Math.max(0, Math.round((invoice?.delivery_invoice_items || []).reduce((sum, item) => sum + safeNum(item?.quantity, 0), 0)))
 }

 function getWeatherGuardSavedDecision(row = {}) {
  const rowKey = getWeatherGuardDecisionKey(row)
  return weatherGuardDecisions.find(decision => {
   if (row?.reseller_id && decision?.reseller_id) return String(decision.reseller_id) === String(row.reseller_id)
   return getWeatherGuardDecisionKey(decision) === rowKey
  }) || null
 }

 function buildWeatherGuardRows(invoices = deliveryInvoices, dateValue = forecastDate) {
  const invoiceRows = (invoices || []).filter(invoice => String(invoice?.delivery_date || '').slice(0,10) === String(dateValue || '').slice(0,10))
  const grouped = {}

  invoiceRows.forEach(invoice => {
   const resellerId = invoice?.reseller_id || ''
   const resellerName = invoice?.reseller_name || invoice?.customer_name || 'Direct / Other Customer'
   const key = resellerId ? `reseller:${resellerId}` : getWeatherGuardDecisionKey({ reseller_name:resellerName })
   if (!grouped[key]) {
    grouped[key] = {
     key,
     reseller_id:resellerId || null,
     reseller_name:resellerName,
     municipality:invoice?.customer_address || '',
     invoice_qty:0,
     invoice_count:0
    }
   }
   grouped[key].invoice_qty += getWeatherGuardInvoiceQuantity(invoice)
   grouped[key].invoice_count += 1
  })

  const factors = getWeatherGuardFactors(weatherGuardDraft)
  return Object.values(grouped).map(row => {
   const isDirect = !row.reseller_id
   const profile = isDirect
    ? {
       municipality:row.municipality || '',
       outlet_category:'non_school',
       school_type:'none',
       school_demand_pct:0,
       route_name:'',
       route_risk_level:'green',
       route_notes:''
      }
    : getWeatherGuardProfileForReseller(row.reseller_id)

   const schoolDemandPct = Math.max(0, Math.min(100, safeNum(profile?.school_demand_pct, 50)))
   const schoolDemand = row.invoice_qty * schoolDemandPct / 100
   const nonSchoolDemand = row.invoice_qty - schoolDemand
   const routeUnsafe = weatherGuardDraft.route_status === 'unsafe'
   const recommendedQty = routeUnsafe
    ? 0
    : Math.max(0, Math.round((schoolDemand * factors.schoolFactor) + (nonSchoolDemand * factors.nonSchoolFactor)))
   const baseQty = routeUnsafe
    ? 0
    : Math.max(0, Math.round((schoolDemand * factors.baseSchoolFactor) + (nonSchoolDemand * factors.nonSchoolFactor)))
   const conditionalQty = Math.max(0, recommendedQty - baseQty)
   const savedDecision = getWeatherGuardSavedDecision(row)
   const overrideKey = getWeatherGuardDecisionKey(row)
   const hasOverride = Object.prototype.hasOwnProperty.call(weatherGuardDecisionOverrides, overrideKey)
   const defaultFinal = weatherGuardDraft.class_status === 'unverified' && weatherGuardDraft.weather_level !== 'no_warning'
    ? baseQty
    : recommendedQty
   const finalQty = routeUnsafe
    ? 0
    : Math.max(0, Math.round(hasOverride
      ? safeNum(weatherGuardDecisionOverrides[overrideKey], defaultFinal)
      : safeNum(savedDecision?.final_qty, defaultFinal)))

   let riskLevel = 'green'
   if (routeUnsafe || weatherGuardDraft.class_status === 'fully_suspended' || weatherGuardDraft.weather_level === 'severe_weather' || safeNum(profile?.route_risk_level === 'red' ? 1 : 0,0)) riskLevel = 'red'
   else if (
    weatherGuardDraft.route_status === 'caution'
    || weatherGuardDraft.class_status === 'partial_suspension'
    || weatherGuardDraft.class_status === 'unverified' && weatherGuardDraft.weather_level !== 'no_warning'
    || weatherGuardDraft.weather_level === 'heavy_rain'
    || profile?.route_risk_level === 'amber'
    || recommendedQty < row.invoice_qty
   ) riskLevel = 'amber'

   const dispatchStatus = routeUnsafe ? 'blocked' : riskLevel === 'green' ? 'allowed' : 'caution'
   return {
    ...row,
    municipality:profile?.municipality || row.municipality || '',
    outlet_category:profile?.outlet_category || (isDirect ? 'non_school' : 'mixed'),
    school_type:profile?.school_type || (isDirect ? 'none' : 'mixed'),
    school_demand_pct:schoolDemandPct,
    route_name:profile?.route_name || '',
    route_risk_level:profile?.route_risk_level || 'green',
    school_factor:factors.schoolFactor,
    non_school_factor:factors.nonSchoolFactor,
    base_qty:baseQty,
    conditional_qty:conditionalQty,
    recommended_qty:recommendedQty,
    final_qty:finalQty,
    risk_level:riskLevel,
    dispatch_status:dispatchStatus,
    reallocation_qty:Math.max(0, row.invoice_qty - finalQty),
    notes:savedDecision?.notes || ''
   }
  }).sort((a,b) => String(a.reseller_name || '').localeCompare(String(b.reseller_name || '')))
 }

 function getWeatherGuardSummary(rows = buildWeatherGuardRows()) {
  return (rows || []).reduce((summary, row) => {
   summary.normal += safeNum(row.invoice_qty,0)
   summary.base += safeNum(row.base_qty,0)
   summary.conditional += safeNum(row.conditional_qty,0)
   summary.recommended += safeNum(row.recommended_qty,0)
   summary.final += safeNum(row.final_qty,0)
   summary.reallocation += safeNum(row.reallocation_qty,0)
   if (row.risk_level === 'red') summary.red += 1
   else if (row.risk_level === 'amber') summary.amber += 1
   else summary.green += 1
   if (row.dispatch_status === 'blocked') summary.blocked += 1
   return summary
  }, { normal:0, base:0, conditional:0, recommended:0, final:0, reallocation:0, green:0, amber:0, red:0, blocked:0 })
 }

 function getWeatherGuardErrorMessage(error) {
  const message = String(error?.message || error || '')
  const mappings = [
   ['WEATHER_GUARD_ACCESS_DENIED','Your admin role is not allowed to manage this guard.'],
   ['WEATHER_GUARD_DELIVERY_DATE_REQUIRED','Select a delivery date.'],
   ['WEATHER_GUARD_CLASS_VERIFICATION_REQUIRED','Verified class suspension requires a DepEd/LGU/school source, verifier, and reference link or screenshot note.'],
   ['WEATHER_GUARD_UNVERIFIED_CLASS_CANNOT_REDUCE_DEMAND','Unverified class information cannot reduce school demand.'],
   ['WEATHER_GUARD_ROUTE_VERIFICATION_REQUIRED','An unsafe route requires an official/field source, verifier, and reference.'],
   ['WEATHER_GUARD_UNSAFE_ROUTE_FINAL_QTY_MUST_BE_ZERO','Unsafe route: final released quantity must be zero.'],
   ['WEATHER_GUARD_FINALIZE_OWNER_MANAGER_ONLY','Only the Owner or Manager may lock and release the final plan.'],
   ['WEATHER_GUARD_PLAN_NOT_FOUND','Save the guard draft before finalizing it.']
  ]
  return mappings.find(([code]) => message.includes(code))?.[1] || message
 }

 async function loadWeatherGuardData(dateValue = forecastDate, options = {}) {
  if (!dateValue) return
  setWeatherGuardLoading(true)
  try {
   const [profilesResult, settingsResult, planResult] = await Promise.all([
    supabase.from('weather_guard_outlet_profiles').select('*').eq('is_active', true).order('municipality'),
    supabase.from('weather_guard_settings').select('*').eq('id', 1).maybeSingle(),
    supabase.from('weather_guard_daily_plans').select('*').eq('delivery_date', dateValue).maybeSingle()
   ])
   if (profilesResult.error) throw profilesResult.error
   if (settingsResult.error) throw settingsResult.error
   if (planResult.error) throw planResult.error

   const profiles = profilesResult.data || []
   setWeatherGuardProfiles(profiles)
   setWeatherGuardProfileDrafts(Object.fromEntries(profiles.map(row => [
    String(row.reseller_id),
    {
     reseller_id:String(row.reseller_id),
     municipality:row.municipality || '',
     outlet_category:row.outlet_category || 'mixed',
     school_type:row.school_type || 'mixed',
     grade_level_market:row.grade_level_market || '',
     school_demand_pct:String(row.school_demand_pct ?? 50),
     route_name:row.route_name || '',
     route_risk_level:row.route_risk_level || 'green',
     route_notes:row.route_notes || '',
     is_active:row.is_active !== false
    }
   ])))

   const settings = settingsResult.data || weatherGuardSettings
   setWeatherGuardSettings({
    ...weatherGuardSettings,
    ...settings,
    decision_cutoff_time:normalizeWeatherGuardTime(settings?.decision_cutoff_time || '20:00')
   })

   const plan = planResult.data || null
   setWeatherGuardPlan(plan)
   let loadedDecisions = []
   let loadedOutcome = null

   if (plan) {
    const [decisionsResult, outcomeResult] = await Promise.all([
     supabase.from('weather_guard_outlet_decisions').select('*').eq('plan_id', plan.id).order('reseller_name'),
     supabase.from('weather_guard_outcomes').select('*').eq('plan_id', plan.id).maybeSingle()
    ])
    if (decisionsResult.error) throw decisionsResult.error
    if (outcomeResult.error) throw outcomeResult.error

    const decisions = decisionsResult.data || []
    loadedDecisions = decisions
    setWeatherGuardDecisions(decisions)
    setWeatherGuardDecisionOverrides(Object.fromEntries(decisions.map(row => [getWeatherGuardDecisionKey(row), String(row.final_qty ?? 0)])))
    setWeatherGuardDraft({
     weather_level:plan.weather_level || 'no_warning',
     weather_source_type:plan.weather_source_type || 'none',
     weather_location:plan.weather_location || 'Pangasinan',
     weather_issued_at:toWeatherGuardDateTimeLocal(plan.weather_issued_at),
     weather_reference:plan.weather_reference || '',
     class_status:plan.class_status || 'unverified',
     class_scope:plan.class_scope || '',
     class_source_type:plan.class_source_type || 'none',
     class_verified_by:plan.class_verified_by || '',
     class_verified_at:toWeatherGuardDateTimeLocal(plan.class_verified_at),
     class_reference:plan.class_reference || '',
     route_status:plan.route_status || 'unverified',
     route_source_type:plan.route_source_type || 'none',
     route_verified_by:plan.route_verified_by || '',
     route_verified_at:toWeatherGuardDateTimeLocal(plan.route_verified_at),
     route_reference:plan.route_reference || '',
     decision_cutoff_time:normalizeWeatherGuardTime(plan.decision_cutoff_time || settings?.decision_cutoff_time || '20:00'),
     decision_notes:plan.decision_notes || ''
    })
    const outcome = outcomeResult.data || {}
    loadedOutcome = outcomeResult.data || null
    setWeatherGuardOutcome({
     actual_delivered_qty:String(outcome.actual_delivered_qty ?? ''),
     returned_qty:String(outcome.returned_qty ?? ''),
     sold_qty:String(outcome.sold_qty ?? ''),
     stockout_qty:String(outcome.stockout_qty ?? ''),
     lost_sales_qty:String(outcome.lost_sales_qty ?? ''),
     disposal_qty:String(outcome.disposal_qty ?? ''),
     avoided_production_qty:String(outcome.avoided_production_qty ?? ''),
     notes:outcome.notes || ''
    })
   } else {
    setWeatherGuardDecisions([])
    setWeatherGuardDecisionOverrides({})
    setWeatherGuardDraft({
     ...getDefaultWeatherGuardDraft(dateValue),
     decision_cutoff_time:normalizeWeatherGuardTime(settings?.decision_cutoff_time || '20:00')
    })
    setWeatherGuardOutcome({
     actual_delivered_qty:'',
     returned_qty:'',
     sold_qty:'',
     stockout_qty:'',
     lost_sales_qty:'',
     disposal_qty:'',
     avoided_production_qty:'',
     notes:''
    })
   }

   if (!options.silent) showToast(`Weather and Class Suspension Guard loaded for ${dateValue}.`)
   return { profiles, settings, plan, decisions:loadedDecisions, outcome:loadedOutcome }
  } catch(error) {
   console.error('Weather guard load failed:', error)
   if (!options.silent) showToast(`Weather guard load failed: ${getWeatherGuardErrorMessage(error)}`, 'red')
   return null
  } finally {
   setWeatherGuardLoading(false)
  }
 }

 function getTomorrowForecastPagasaView(data = pagasaRegion1Data, targetDate = forecastDate) {
  if (!data || !targetDate) return null
  return getPagasaForecastDateViews(data).find(view => view?.update_date === targetDate && !view?.disabled) || null
 }

 async function prepareTomorrowOperationsForecast(options = {}) {
  const targetDate = getPHDateOffsetString(1)
  const forceWeather = options.forceWeather !== false
  setTomorrowForecastPreparing(true)
  setForecastDate(targetDate)
  setSalesView('deliveries')
  setDeliveriesSubTab('operations')
  setShowWeatherGuard(true)
  try {
   const [guardSnapshot, weatherData] = await Promise.all([
    loadWeatherGuardData(targetDate, { silent:true }),
    loadPagasaRegion1Weather({ force:forceWeather, silent:true }),
    loadResellers(),
    loadDeliveryInvoices(),
    loadDonutVariants()
   ])
   const targetView = getTomorrowForecastPagasaView(weatherData, targetDate)
   if (targetView) setPagasaSelectedUpdateKey(targetView.id)

   const lockedPlan = String(guardSnapshot?.plan?.status || '').toLowerCase() === 'locked'
   if (weatherData && targetView && !lockedPlan) {
    applyPagasaDataToWeatherGuard({
     data:weatherData,
     updateKey:targetView.id,
     municipalityName:pagasaSelectedMunicipality || 'Dagupan City',
     targetDate,
     silent:true
    })
   }

   if (!weatherData) {
    showToast(`Tomorrow's forecast workspace opened for ${targetDate}, but live PAGASA refresh failed. Review the official source before saving.`, 'orange')
   } else if (!targetView) {
    showToast(`Tomorrow's workspace opened for ${targetDate}. The target-date PAGASA regional outlook is not available yet, so weather remains for manual review.`, 'orange')
   } else if (lockedPlan) {
    showToast(`Locked plan loaded for ${targetDate}. PAGASA was refreshed for rechecking but did not overwrite the locked forecast.`, 'green')
   } else {
    showToast(`Tomorrow's operations forecast is prepared for ${targetDate}. Review classes, routes, quantities, then save the draft.`, 'green')
   }
   setTimeout(() => document.getElementById('tomorrow-operations-forecast')?.scrollIntoView({ behavior:'smooth', block:'start' }), 150)
   return { targetDate, guardSnapshot, weatherData, targetView }
  } catch(error) {
   console.error('Tomorrow operations forecast preparation failed:', error)
   showToast(`Tomorrow's forecast could not be fully prepared: ${getWeatherGuardErrorMessage(error)}`, 'red')
   return null
  } finally {
   setTomorrowForecastPreparing(false)
  }
 }

 async function openTomorrowForecastPagasaSource() {
  const targetDate = forecastDate || getPHDateOffsetString(1)
  let data = pagasaRegion1Data
  if (!data) data = await loadPagasaRegion1Weather({ force:true, silent:false })
  const targetView = getTomorrowForecastPagasaView(data, targetDate)
  if (targetView) setPagasaSelectedUpdateKey(targetView.id)
  setDeliveriesSubTab('pagasa')
  if (!targetView && data) showToast(`The official PAGASA outlook does not yet include ${targetDate}. Use the latest bulletin and recheck later.`, 'orange')
 }

 function printTomorrowOperationsForecast() {
  const rows = buildWeatherGuardRows(deliveryInvoices, forecastDate)
  const summary = getWeatherGuardSummary(rows)
  const selectedPlanMatches = String(weatherGuardPlan?.delivery_date || '').slice(0,10) === String(forecastDate || '').slice(0,10)
  const planStatus = selectedPlanMatches ? String(weatherGuardPlan?.status || 'draft').toUpperCase() : 'UNSAVED DRAFT'
  const targetView = getTomorrowForecastPagasaView(pagasaRegion1Data, forecastDate)
  const targetMunicipality = targetView?.pangasinan?.municipalities?.find(row => String(row?.name || '').toLowerCase() === String(pagasaSelectedMunicipality || '').toLowerCase())
   || targetView?.pangasinan?.municipalities?.[0]
   || null
  const weatherVisual = getPagasaAlertVisual(targetMunicipality || {})
  const generatedAt = new Date().toLocaleString('en-PH', { timeZone:PH_TIME_ZONE, year:'numeric', month:'short', day:'numeric', hour:'numeric', minute:'2-digit' })
  const classVerified = weatherGuardDraft.class_status !== 'unverified'
  const routeVerified = weatherGuardDraft.route_status !== 'unverified'
  const invoiceCount = (deliveryInvoices || []).filter(invoice => String(invoice?.delivery_date || '').slice(0,10) === String(forecastDate || '').slice(0,10)).length
  const profiledCount = rows.filter(row => !row.reseller_id || weatherGuardProfiles.some(profile => String(profile.reseller_id) === String(row.reseller_id))).length
  const readiness = [
   ['Tomorrow invoices / orders', rows.length > 0 && summary.normal > 0, `${invoiceCount} invoice(s), ${summary.normal.toLocaleString()} pcs`],
   ['Official target-date PAGASA outlook', !!targetView && !pagasaRegion1Data?.stale, targetView ? weatherVisual.label : 'Not available'],
   ['Class status checked', classVerified, String(weatherGuardDraft.class_status || 'unverified').replaceAll('_',' ')],
   ['Route status checked', routeVerified, String(weatherGuardDraft.route_status || 'unverified').replaceAll('_',' ')],
   ['Relevant outlet profiles', rows.length > 0 && profiledCount === rows.length, `${profiledCount}/${rows.length}`],
   ['Plan saved / locked', selectedPlanMatches, planStatus]
  ]
  const pw = window.open('', '_blank', 'width=980,height=900')
  if (!pw) { showToast('Allow pop-ups to print the operations forecast.', 'red'); return }
  const esc = value => escapePrintHTML(value)
  pw.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Tomorrow Operations Forecast - ${esc(forecastDate)}</title>
  <style>
  *{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#1a1a2e;margin:0;background:#f4f4f4}.sheet{width:210mm;min-height:297mm;margin:0 auto;background:#fff;padding:11mm}.head{display:flex;justify-content:space-between;gap:18px;border-bottom:4px solid #ca1b1b;padding-bottom:10px}.brand{color:#ca1b1b;font-weight:900;font-size:22px}.title{text-align:right}.title h1{font-size:20px;margin:0 0 4px}.meta{font-size:10px;color:#666}.status{display:inline-block;margin-top:7px;padding:5px 10px;border-radius:16px;background:#1a1a2e;color:#fff;font-size:10px;font-weight:900}.timeline,.summary,.checks{display:grid;gap:7px;margin-top:12px}.timeline{grid-template-columns:repeat(4,1fr)}.summary{grid-template-columns:repeat(5,1fr)}.checks{grid-template-columns:repeat(2,1fr)}.card{border:1px solid #ddd;border-radius:8px;padding:8px}.card small{display:block;color:#777;font-size:8px;text-transform:uppercase;font-weight:900;margin-bottom:4px}.card b{font-size:13px}.weather{margin-top:12px;border:1px solid ${weatherVisual.border};background:${weatherVisual.background};border-radius:9px;padding:10px}.weather h3{margin:0 0 5px;color:${weatherVisual.color};font-size:13px}.weather p{font-size:9px;line-height:1.45;margin:3px 0}.check{display:flex;justify-content:space-between;gap:10px;border:1px solid #e5e5e5;border-radius:7px;padding:7px;font-size:9px}.ok{color:#2d8a4e;font-weight:900}.pending{color:#b45309;font-weight:900}table{width:100%;border-collapse:collapse;margin-top:12px;font-size:9px}th{background:#1a1a2e;color:#fff;padding:6px;text-align:center}th:first-child,td:first-child{text-align:left}td{padding:6px;border-bottom:1px solid #e8e8e8;text-align:center}.totals{background:#fff8dc;font-weight:900}.notes{margin-top:12px;border:1px solid #ddd;border-radius:8px;padding:9px;font-size:9px;line-height:1.5;white-space:pre-wrap}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:35px;margin-top:28px}.line{border-top:1px solid #222;padding-top:4px;text-align:center;font-size:9px}.footer{margin-top:16px;padding-top:7px;border-top:1px solid #ddd;font-size:8px;color:#777;text-align:center}.no-print{text-align:center;margin:15px}.no-print button{background:#ca1b1b;color:#fff;border:0;border-radius:8px;padding:10px 22px;font-weight:900;cursor:pointer}@media print{@page{size:A4;margin:0}body{background:#fff}.sheet{margin:0}.no-print{display:none}}
  </style></head><body><div class="sheet">
  <div class="head"><div><div class="brand">Roma's Donuts</div><div class="meta">Tomorrow-first production and delivery control</div></div><div class="title"><h1>TOMORROW'S OPERATIONS FORECAST</h1><div class="meta">Delivery date: <strong>${esc(formatDateForDisplay(forecastDate))}</strong> · Starts ${TOMORROW_DELIVERY_START_LABEL}</div><span class="status">${esc(planStatus)}</span></div></div>
  <div class="timeline"><div class="card"><small>Morning Start</small><b>8:00 AM</b></div><div class="card"><small>Forecast Complete</small><b>11:00 AM</b></div><div class="card"><small>Final Risk Recheck</small><b>${esc(normalizeWeatherGuardTime(weatherGuardDraft.decision_cutoff_time || '20:00'))}</b></div><div class="card"><small>Delivery Start</small><b>${TOMORROW_DELIVERY_START_LABEL}</b></div></div>
  <div class="summary">${[
   ['Normal Forecast',summary.normal],['Base Production',summary.base],['Conditional Hold',summary.conditional],['Risk-Adjusted',summary.recommended],['Final Release',summary.final]
  ].map(([label,value])=>`<div class="card"><small>${esc(label)}</small><b>${safeNum(value,0).toLocaleString()} pcs</b></div>`).join('')}</div>
  <div class="weather"><h3>${weatherVisual.icon} ${esc(weatherVisual.label)}</h3><p><strong>Weather:</strong> ${esc(targetView?.forecast_day?.condition || weatherGuardDraft.weather_level || 'Not loaded')}</p><p><strong>Class status:</strong> ${esc(String(weatherGuardDraft.class_status || 'unverified').replaceAll('_',' '))} · <strong>Route:</strong> ${esc(String(weatherGuardDraft.route_status || 'unverified').replaceAll('_',' '))}</p><p><strong>Official reference:</strong> ${esc(weatherGuardDraft.weather_reference || targetView?.source_url || 'Official source not yet attached')}</p></div>
  <div class="checks">${readiness.map(([label,ok,note])=>`<div class="check"><span><strong>${esc(label)}</strong><br>${esc(note)}</span><span class="${ok?'ok':'pending'}">${ok?'READY':'CHECK'}</span></div>`).join('')}</div>
  <table><thead><tr><th>Outlet / Route</th><th>Normal</th><th>Base</th><th>Recommended</th><th>Final</th><th>Risk</th><th>Dispatch</th></tr></thead><tbody>
  ${rows.length ? rows.map(row=>`<tr><td><strong>${esc(row.reseller_name)}</strong><br><span style="color:#777">${esc(row.municipality || 'Municipality not set')}</span></td><td>${row.invoice_qty}</td><td>${row.base_qty}</td><td>${row.recommended_qty}</td><td><strong>${row.final_qty}</strong></td><td>${esc(String(row.risk_level || '').toUpperCase())}</td><td>${esc(String(row.dispatch_status || '').toUpperCase())}</td></tr>`).join('') : '<tr><td colspan="7" style="text-align:center;padding:18px;color:#777">No delivery invoices are loaded for this date.</td></tr>'}
  <tr class="totals"><td>TOTAL</td><td>${summary.normal}</td><td>${summary.base}</td><td>${summary.recommended}</td><td>${summary.final}</td><td colspan="2"></td></tr></tbody></table>
  <div class="notes"><strong>Decision / reallocation notes</strong><br>${esc(weatherGuardDraft.decision_notes || 'No notes entered.')}</div>
  <div class="signatures"><div class="line">Prepared by: ${esc(currentAdminLabel || 'Admin')}</div><div class="line">Owner / Manager approval</div></div>
  <div class="footer">Generated ${esc(generatedAt)} · Official weather is a planning input only. Recheck PAGASA, class announcements, and routes before production lock, loading, and dispatch.</div>
  </div><div class="no-print"><button onclick="window.print()">PRINT OPERATIONS FORECAST</button></div></body></html>`)
  pw.document.close()
  setTimeout(() => { pw.focus(); pw.print() }, 500)
 }

 async function saveWeatherGuardProfiles() {
  if (!['owner','manager','admin','supervisor','asst_supervisor'].includes(normalizedAdminRole)) {
   showToast('Your role is not allowed to update outlet risk profiles.', 'red')
   return
  }
  const payload = (resellers || []).map(reseller => {
   const draft = getWeatherGuardProfileDraft(reseller)
   return {
    reseller_id:reseller.id,
    municipality:String(draft.municipality || reseller.area || '').trim(),
    outlet_category:draft.outlet_category || 'mixed',
    school_type:draft.school_type || 'mixed',
    grade_level_market:String(draft.grade_level_market || '').trim() || null,
    school_demand_pct:Math.max(0, Math.min(100, safeNum(draft.school_demand_pct,50))),
    route_name:String(draft.route_name || reseller.area || '').trim() || null,
    route_risk_level:draft.route_risk_level || 'green',
    route_notes:String(draft.route_notes || '').trim() || null,
    is_active:true,
    created_by:currentAdminLabel,
    updated_by:currentAdminLabel
   }
  })
  if (!payload.length) {
   showToast('No active reseller outlets are loaded.', 'red')
   return
  }
  setWeatherGuardSaving(true)
  try {
   const { error } = await supabase.from('weather_guard_outlet_profiles').upsert(payload, { onConflict:'reseller_id' })
   if (error) throw error
   await logAudit('WEATHER GUARD OUTLET PROFILES SAVED', currentAdminLabel, 'Production Forecast', `${payload.length} outlet profile(s) updated`)
   showToast(`${payload.length} outlet risk profile(s) saved.`)
   await loadWeatherGuardData(forecastDate, { silent:true })
  } catch(error) {
   showToast(`Outlet profiles failed: ${getWeatherGuardErrorMessage(error)}`, 'red')
  } finally {
   setWeatherGuardSaving(false)
  }
 }

 async function saveWeatherGuardSettings() {
  if (!['owner','manager'].includes(normalizedAdminRole)) {
   showToast('Only the Owner or Manager may change the production cutoff settings.', 'red')
   return
  }
  const payload = {
   decision_cutoff_time:normalizeWeatherGuardTime(weatherGuardSettings.decision_cutoff_time || '20:00'),
   mixing_minutes:Math.max(0, Math.round(safeNum(weatherGuardSettings.mixing_minutes,0))),
   proofing_minutes:Math.max(0, Math.round(safeNum(weatherGuardSettings.proofing_minutes,0))),
   frying_minutes:Math.max(0, Math.round(safeNum(weatherGuardSettings.frying_minutes,0))),
   decorating_minutes:Math.max(0, Math.round(safeNum(weatherGuardSettings.decorating_minutes,0))),
   packing_minutes:Math.max(0, Math.round(safeNum(weatherGuardSettings.packing_minutes,0))),
   loading_minutes:Math.max(0, Math.round(safeNum(weatherGuardSettings.loading_minutes,0))),
   travel_buffer_minutes:Math.max(0, Math.round(safeNum(weatherGuardSettings.travel_buffer_minutes,0))),
   approval_threshold_pct:Math.max(0, Math.min(100, safeNum(weatherGuardSettings.approval_threshold_pct,0))),
   updated_by:currentAdminLabel
  }
  setWeatherGuardSaving(true)
  try {
   const { error } = await supabase.from('weather_guard_settings').update(payload).eq('id',1)
   if (error) throw error
   await logAudit('WEATHER GUARD SETTINGS UPDATED', currentAdminLabel, 'Production Forecast', `Decision cutoff ${payload.decision_cutoff_time}`)
   setWeatherGuardSettings(prev => ({ ...prev, ...payload }))
   setWeatherGuardDraft(prev => ({ ...prev, decision_cutoff_time:payload.decision_cutoff_time }))
   showToast('Weather guard production cutoff settings saved.')
  } catch(error) {
   showToast(`Weather guard settings failed: ${getWeatherGuardErrorMessage(error)}`, 'red')
  } finally {
   setWeatherGuardSaving(false)
  }
 }

 function validateWeatherGuardDraft(rows = buildWeatherGuardRows()) {
  if (!(rows || []).length) return 'Create delivery invoices for the selected date before saving a guard plan.'
  if (weatherGuardDraft.weather_level !== 'no_warning') {
   if (weatherGuardDraft.weather_source_type === 'none' || !String(weatherGuardDraft.weather_reference || '').trim()) {
    return 'A weather warning requires an official source and reference link, bulletin number, or screenshot note.'
   }
  }
  if (['partial_suspension','fully_suspended'].includes(weatherGuardDraft.class_status)) {
   if (
    weatherGuardDraft.class_source_type === 'none'
    || !String(weatherGuardDraft.class_verified_by || '').trim()
    || !String(weatherGuardDraft.class_reference || '').trim()
   ) return 'A class suspension must be verified through DepEd, LGU, or the school, with verifier and reference.'
  }
  if (weatherGuardDraft.route_status === 'unsafe') {
   if (
    weatherGuardDraft.route_source_type === 'none'
    || !String(weatherGuardDraft.route_verified_by || '').trim()
    || !String(weatherGuardDraft.route_reference || '').trim()
   ) return 'An unsafe route requires a source, verifier, and official/field reference.'
   if (rows.some(row => safeNum(row.final_qty,0) > 0)) return 'Unsafe route: every final outlet quantity must be zero.'
  }
  return ''
 }

 async function saveWeatherGuardPlan() {
  const rows = buildWeatherGuardRows()
  const validationMessage = validateWeatherGuardDraft(rows)
  if (validationMessage) {
   showToast(validationMessage, 'red')
   return null
  }
  const summary = getWeatherGuardSummary(rows)
  const factors = getWeatherGuardFactors(weatherGuardDraft)
  const planPayload = {
   delivery_date:forecastDate,
   weather_level:weatherGuardDraft.weather_level,
   weather_source_type:weatherGuardDraft.weather_source_type,
   weather_location:String(weatherGuardDraft.weather_location || '').trim(),
   weather_issued_at:weatherGuardDraft.weather_issued_at ? new Date(weatherGuardDraft.weather_issued_at).toISOString() : null,
   weather_reference:String(weatherGuardDraft.weather_reference || '').trim(),
   class_status:weatherGuardDraft.class_status,
   class_scope:String(weatherGuardDraft.class_scope || '').trim(),
   class_source_type:weatherGuardDraft.class_source_type,
   class_verified_by:String(weatherGuardDraft.class_verified_by || '').trim(),
   class_verified_at:weatherGuardDraft.class_verified_at ? new Date(weatherGuardDraft.class_verified_at).toISOString() : null,
   class_reference:String(weatherGuardDraft.class_reference || '').trim(),
   route_status:weatherGuardDraft.route_status,
   route_source_type:weatherGuardDraft.route_source_type,
   route_verified_by:String(weatherGuardDraft.route_verified_by || '').trim(),
   route_verified_at:weatherGuardDraft.route_verified_at ? new Date(weatherGuardDraft.route_verified_at).toISOString() : null,
   route_reference:String(weatherGuardDraft.route_reference || '').trim(),
   decision_cutoff_time:normalizeWeatherGuardTime(weatherGuardDraft.decision_cutoff_time || weatherGuardSettings.decision_cutoff_time),
   school_factor:factors.schoolFactor,
   non_school_factor:factors.nonSchoolFactor,
   normal_forecast_qty:summary.normal,
   base_production_qty:summary.base,
   conditional_production_qty:summary.conditional,
   risk_adjusted_qty:summary.recommended,
   final_released_qty:summary.final,
   decision_notes:String(weatherGuardDraft.decision_notes || '').trim()
  }
  const decisions = rows.map(row => ({
   reseller_id:row.reseller_id,
   reseller_name:row.reseller_name,
   municipality:row.municipality,
   outlet_category:row.outlet_category,
   invoice_qty:row.invoice_qty,
   school_demand_pct:row.school_demand_pct,
   school_factor:row.school_factor,
   non_school_factor:row.non_school_factor,
   recommended_qty:row.recommended_qty,
   final_qty:row.final_qty,
   risk_level:row.risk_level,
   dispatch_status:row.dispatch_status,
   reallocation_qty:row.reallocation_qty,
   notes:row.notes || ''
  }))
  setWeatherGuardSaving(true)
  try {
   const { data, error } = await supabase.rpc('save_weather_guard_plan', { p_plan:planPayload, p_decisions:decisions })
   if (error) throw error
   showToast(summary.final > summary.recommended
    ? 'Guard draft saved. Final quantity exceeds the recommendation and now requires Owner/Manager approval.'
    : 'Weather and class guard draft saved.')
   await loadWeatherGuardData(forecastDate, { silent:true })
   return data
  } catch(error) {
   showToast(`Weather guard save failed: ${getWeatherGuardErrorMessage(error)}`, 'red')
   return null
  } finally {
   setWeatherGuardSaving(false)
  }
 }

 async function finalizeWeatherGuardPlan() {
  if (!['owner','manager'].includes(normalizedAdminRole)) {
   showToast('Only the Owner or Manager may lock and release the production guard plan.', 'red')
   return
  }
  let planId = weatherGuardPlan?.id
  if (!planId || weatherGuardPlan?.status === 'locked') {
   planId = await saveWeatherGuardPlan()
   if (!planId) return
  }
  setWeatherGuardFinalizing(true)
  try {
   const { error } = await supabase.rpc('finalize_weather_guard_plan', {
    p_plan_id:planId,
    p_notes:`Locked from Production Forecast by ${currentAdminLabel}`
   })
   if (error) throw error
   await loadWeatherGuardData(forecastDate, { silent:true })
   showToast('Weather and class suspension guard plan locked and released.')
  } catch(error) {
   showToast(`Plan finalization failed: ${getWeatherGuardErrorMessage(error)}`, 'red')
  } finally {
   setWeatherGuardFinalizing(false)
  }
 }

 function updateWeatherGuardFinalQty(row = {}, value = '') {
  const key = getWeatherGuardDecisionKey(row)
  setWeatherGuardDecisionOverrides(prev => ({ ...prev, [key]:value }))
 }

 function applyWeatherGuardRecommendations(mode = 'recommended') {
  const rows = buildWeatherGuardRows()
  setWeatherGuardDecisionOverrides(Object.fromEntries(rows.map(row => [
   getWeatherGuardDecisionKey(row),
   String(mode === 'base' ? row.base_qty : row.recommended_qty)
  ])))
 }

 function prefillWeatherGuardOutcomeFromInvoices() {
  const rows = buildWeatherGuardRows()
  const delivered = rows.reduce((sum,row)=>sum+safeNum(row.invoice_qty,0),0)
  const returns = (deliveryInvoices || [])
   .filter(invoice => String(invoice?.delivery_date || '').slice(0,10) === String(forecastDate || '').slice(0,10))
   .reduce((sum, invoice) => sum + Math.max(0, safeNum(invoice?.returns_qty,0)), 0)
  const finalReleased = getWeatherGuardSummary(rows).final
  const disposal = Math.max(0, safeNum(weatherGuardOutcome.disposal_qty,0))
  setWeatherGuardOutcome(prev => ({
   ...prev,
   actual_delivered_qty:String(delivered),
   returned_qty:String(returns),
   sold_qty:String(Math.max(0, delivered - returns - disposal)),
   avoided_production_qty:String(Math.max(0, getWeatherGuardSummary(rows).normal - finalReleased))
  }))
 }

 async function saveWeatherGuardOutcome() {
  if (!weatherGuardPlan?.id) {
   showToast('Save the weather guard plan before recording the outcome.', 'red')
   return
  }
  const delivered = Math.max(0, Math.round(safeNum(weatherGuardOutcome.actual_delivered_qty,0)))
  const returned = Math.max(0, Math.round(safeNum(weatherGuardOutcome.returned_qty,0)))
  const disposal = Math.max(0, Math.round(safeNum(weatherGuardOutcome.disposal_qty,0)))
  const sold = weatherGuardOutcome.sold_qty === ''
   ? Math.max(0, delivered - returned - disposal)
   : Math.max(0, Math.round(safeNum(weatherGuardOutcome.sold_qty,0)))
  const payload = {
   plan_id:weatherGuardPlan.id,
   actual_delivered_qty:delivered,
   returned_qty:returned,
   sold_qty:sold,
   stockout_qty:Math.max(0, Math.round(safeNum(weatherGuardOutcome.stockout_qty,0))),
   lost_sales_qty:Math.max(0, Math.round(safeNum(weatherGuardOutcome.lost_sales_qty,0))),
   disposal_qty:disposal,
   avoided_production_qty:Math.max(0, Math.round(safeNum(weatherGuardOutcome.avoided_production_qty,0))),
   notes:String(weatherGuardOutcome.notes || '').trim() || null,
   recorded_by:currentAdminLabel,
   recorded_at:new Date().toISOString()
  }
  setWeatherGuardSaving(true)
  try {
   const { error } = await supabase.from('weather_guard_outcomes').upsert(payload, { onConflict:'plan_id' })
   if (error) throw error
   await logAudit('WEATHER GUARD OUTCOME SAVED', currentAdminLabel, forecastDate, `Delivered ${delivered} | Returned ${returned} | Sold ${sold} | Avoided ${payload.avoided_production_qty}`)
   showToast('Weather guard outcome and loss metrics saved.')
   await loadWeatherGuardData(forecastDate, { silent:true })
  } catch(error) {
   showToast(`Outcome save failed: ${getWeatherGuardErrorMessage(error)}`, 'red')
  } finally {
   setWeatherGuardSaving(false)
  }
 }

 function getWeatherGuardTotalLeadMinutes(settings = weatherGuardSettings) {
  return ['mixing_minutes','proofing_minutes','frying_minutes','decorating_minutes','packing_minutes','loading_minutes','travel_buffer_minutes']
   .reduce((sum,key)=>sum+Math.max(0, safeNum(settings?.[key],0)),0)
 }



 function getPangasinanProvinceZoneDashboard(rows = []) {
  const zoneDefinitions = [
   {
    key:'western_coast',
    label:'Western Coast & Islands',
    icon:'🌊',
    towns:['Agno','Alaminos City','Anda','Bani','Bolinao','Burgos','Dasol','Infanta','Labrador','Mabini','Sual']
   },
   {
    key:'central_coast',
    label:'Central Coast & Metro Dagupan',
    icon:'🏙️',
    towns:['Binmaley','Calasiao','Dagupan City','Lingayen','Mangaldan','Mapandan','San Fabian','San Jacinto']
   },
   {
    key:'central_plains',
    label:'Central Plains & Southern Pangasinan',
    icon:'🌾',
    towns:['Aguilar','Basista','Bayambang','Bugallon','Malasiqui','Mangatarem','San Carlos City','Santa Barbara','Urbiztondo']
   },
   {
    key:'eastern_pangasinan',
    label:'Eastern & Northeastern Pangasinan',
    icon:'⛰️',
    towns:['Alcala','Asingan','Balungao','Bautista','Binalonan','Laoac','Manaoag','Natividad','Pozorrubio','Rosales','San Manuel','San Nicolas','San Quintin','Santa Maria','Santo Tomas','Sison','Tayug','Umingan','Urdaneta City','Villasis']
   }
  ]
  const byName = new Map((Array.isArray(rows) ? rows : []).map(row => [String(row?.name || '').trim().toLowerCase(), row]))
  const riskPriority = { green:0, yellow:1, red:2 }
  return zoneDefinitions.map(zone => {
   const zoneRows = zone.towns.map(name => byName.get(name.toLowerCase())).filter(Boolean)
   const counts = zoneRows.reduce((result,row) => {
    const risk = getPagasaAlertVisual(row).risk
    result[risk] = safeNum(result[risk],0) + 1
    return result
   }, { green:0, yellow:0, red:0 })
   const sorted = [...zoneRows].sort((a,b) => {
    const riskA = getPagasaAlertVisual(a).risk
    const riskB = getPagasaAlertVisual(b).risk
    return (riskPriority[riskB] || 0) - (riskPriority[riskA] || 0) || safeNum(b?.score,0) - safeNum(a?.score,0)
   })
   const priorityRow = sorted[0] || null
   const visual = getPagasaAlertVisual(priorityRow || {})
   return {
    ...zone,
    rows:zoneRows,
    counts,
    total:zoneRows.length,
    affected:zoneRows.filter(row => getPagasaAlertVisual(row).risk !== 'green').length,
    priorityRow,
    visual
   }
  })
 }

 function getPangasinanProvinceSummaryVisual(rows = []) {
  const municipalityRows = Array.isArray(rows) ? rows : []
  const riskPriority = { green:0, yellow:1, red:2 }
  const sorted = [...municipalityRows].sort((a,b) => {
   const riskA = getPagasaAlertVisual(a).risk
   const riskB = getPagasaAlertVisual(b).risk
   return (riskPriority[riskB] || 0) - (riskPriority[riskA] || 0) || safeNum(b?.score,0) - safeNum(a?.score,0)
  })
  const priorityRow = sorted[0] || null
  const visual = getPagasaAlertVisual(priorityRow || {})
  const affectedRows = municipalityRows.filter(row => getPagasaAlertVisual(row).risk !== 'green')
  const redRows = municipalityRows.filter(row => getPagasaAlertVisual(row).risk === 'red')
  const yellowRows = municipalityRows.filter(row => getPagasaAlertVisual(row).risk === 'yellow')
  const statusLabel = redRows.length > 0
   ? 'HIGH PROVINCE-WIDE CAUTION'
   : yellowRows.length > 0
    ? 'PROVINCE-WIDE MONITORING'
    : 'ROUTINE PROVINCE WATCH'
  const decisionText = redRows.length > 0
   ? 'Review production lock, dispatch routes, coastal travel, and flood-prone delivery areas before release.'
   : yellowRows.length > 0
    ? 'Continue operations with active monitoring. Recheck PAGASA before loading and dispatch.'
    : 'Normal operations may continue, subject to the latest official PAGASA update before dispatch.'
  return { visual, priorityRow, affectedRows, redRows, yellowRows, statusLabel, decisionText }
 }

