 function getPagasaBulletinViews(data = pagasaRegion1Data) {
  const views = data?.official_update?.bulletin_views
  return Array.isArray(views) ? views.filter(view => view?.id) : []
 }

 function getPagasaForecastDateViews(data = pagasaRegion1Data) {
  const sourceDays = Array.isArray(data?.regional?.days) ? data.regional.days.slice(0,5) : []
  const sourceCalendar = getPagasaForecastCalendar(sourceDays, data)
  const sourceRows = Array.isArray(data?.pangasinan?.municipalities) ? data.pangasinan.municipalities : []
  const today = getPHDateTimeParts().date
  const sourceUrl = data?.official_update?.source_url || data?.source_urls?.regional || 'https://pagasa.dost.gov.ph/regional-forecast/nlprsd'
  const issueText = data?.regional?.extended_issued_at_text || data?.regional?.issued_at_text || ''

  return Array.from({ length:5 }, (_,offset) => {
   const targetDate = addDaysToDateString(today, offset)
   const sourceIndex = sourceCalendar.findIndex(item => item?.date === targetDate)
   const relativeLabel = offset === 0 ? 'TODAY' : offset === 1 ? 'TOMORROW' : `+${offset} DAYS`

   if (sourceIndex < 0 || !sourceDays[sourceIndex]) {
    return {
     id:`forecast-date|${targetDate}`,
     value:`forecast-date|${targetDate}`,
     source_mode:'regional_forecast_date',
     update_date:targetDate,
     relative_label:relativeLabel,
     title:`${formatDateForDisplay(targetDate)} — PAGASA regional outlook not yet available`,
     label:`${formatDateForDisplay(targetDate)} (${relativeLabel}) — Official regional outlook not available`,
     issued_at_text:issueText,
     source_url:sourceUrl,
     disabled:true,
     unavailable:true
    }
   }

   const day = sourceDays[sourceIndex]
   const visual = getPagasaForecastOperationalVisual(day)
   const risk = visual.risk === 'red' ? 'red' : visual.risk === 'green' ? 'green' : 'yellow'
   const score = risk === 'red' ? 5 : risk === 'yellow' ? 2 : 0
   const conditionText = String(day?.condition || '').trim() || 'Condition text unavailable from the official source'
   const temperatureText = `${day?.min_c ?? '—'}–${day?.max_c ?? '—'}°C`
   const detailText = [
    conditionText,
    `Temperature ${temperatureText}`,
    day?.wind_speed ? `Wind ${day.wind_speed}` : '',
    day?.wind_direction ? `Direction ${day.wind_direction}` : '',
    day?.coastal_condition ? `Coast ${day.coastal_condition}` : ''
   ].filter(Boolean).join(' | ')
   const officialText = day?.official_text || detailText
   const operationalLabel = risk === 'red'
    ? 'REGIONAL HIGH CAUTION'
    : risk === 'yellow'
     ? 'REGIONAL MONITOR'
     : 'REGIONAL NORMAL WATCH'
   const statusLabel = `${day?.day || formatDateForDisplay(targetDate)} regional outlook — province planning baseline`
   const basis = `Official PAGASA Northern Luzon / Region 1 extended outlook for ${formatDateForDisplay(targetDate)}. This date view is a province-wide planning baseline and is not a municipality-specific forecast or warning.`
   const municipalityRows = sourceRows.map(row => ({
    ...row,
    risk_level:risk,
    operational_label:operationalLabel,
    status:'regional_forecast_date',
    status_label:statusLabel,
    warning_type:'PAGASA Extended Weather Outlook',
    warning_color:null,
    score,
    basis,
    context:detailText,
    province_wide:true,
    forecast_date:targetDate,
    source_mode:'regional_forecast_date'
   }))
   const riskCounts = {
    green:risk === 'green' ? municipalityRows.length : 0,
    yellow:risk === 'yellow' ? municipalityRows.length : 0,
    red:risk === 'red' ? municipalityRows.length : 0
   }

   return {
    id:`forecast-date|${targetDate}`,
    value:`forecast-date|${targetDate}`,
    source_mode:'regional_forecast_date',
    update_date:targetDate,
    relative_label:relativeLabel,
    title:`${day?.day || formatDateForDisplay(targetDate)}, ${formatDateForDisplay(targetDate)} — PAGASA regional outlook`,
    label:`${formatDateForDisplay(targetDate)} (${relativeLabel}) — ${day?.day || 'PAGASA regional outlook'}`,
    issued_at_text:issueText,
    next_update_at_text:'',
    text:detailText,
    official_text:officialText,
    hazard_key:'regional_extended_outlook',
    source_url:sourceUrl,
    forecast_day:day,
    pangasinan:{
     municipalities:municipalityRows,
     risk_counts:riskCounts,
     affected_count:municipalityRows.filter(row => row.risk_level !== 'green').length,
     total_municipalities:municipalityRows.length,
     note:'This date view applies the official PAGASA regional outlook equally as a province planning baseline. It is not a separate municipality forecast.'
    }
   }
  })
 }

 function getPagasaUpdateOptions(data = pagasaRegion1Data) {
  const views = getPagasaBulletinViews(data)
  const forecastDateViews = getPagasaForecastDateViews(data)
  const latestIssued = views.find(view => view?.issued_at_text)?.issued_at_text
   || data?.official_update?.latest_bulletins?.find(row => row?.issued_at_text)?.issued_at_text
   || data?.regional?.issued_at_text
   || ''
  return [
   {
    value:'latest',
    group:'latest',
    label:`Latest applicable PAGASA updates${latestIssued ? ` — ${latestIssued}` : ''}`,
    title:'Latest applicable PAGASA updates (combined)',
    issued_at_text:latestIssued,
    update_date:getPagasaDateString(latestIssued),
    source_url:data?.official_update?.source_url || data?.source_urls?.regional || ''
   },
   ...forecastDateViews.map(view => ({
    ...view,
    group:'forecast_dates'
   })),
   ...views.map(view => ({
    value:String(view.id),
    group:'bulletins',
    label:`${view.update_date ? formatDateForDisplay(view.update_date) : (view.issued_at_text || 'Official update')} — ${view.title || 'PAGASA Bulletin'}`,
    ...view
   }))
  ]
 }

 function getPagasaSelectedUpdateView(data = pagasaRegion1Data, updateKey = pagasaSelectedUpdateKey) {
  if (!data || !updateKey || updateKey === 'latest') return null
  const forecastDateView = getPagasaForecastDateViews(data).find(view => String(view?.id || '') === String(updateKey))
  if (forecastDateView && !forecastDateView.disabled) return forecastDateView
  return getPagasaBulletinViews(data).find(view => String(view?.id || '') === String(updateKey)) || null
 }

 function getPagasaActivePangasinanData(data = pagasaRegion1Data, updateKey = pagasaSelectedUpdateKey) {
  const selectedView = getPagasaSelectedUpdateView(data, updateKey)
  return selectedView?.pangasinan || data?.pangasinan || {}
 }

 function getPagasaMunicipalityRows(data = pagasaRegion1Data, updateKey = pagasaSelectedUpdateKey) {
  const activePangasinan = getPagasaActivePangasinanData(data, updateKey)
  return Array.isArray(activePangasinan?.municipalities) ? activePangasinan.municipalities : []
 }

 function getPagasaSelectedMunicipalityAlert(name = pagasaSelectedMunicipality, data = pagasaRegion1Data, updateKey = pagasaSelectedUpdateKey) {
  const normalized = String(name || '').trim().toLowerCase()
  return getPagasaMunicipalityRows(data, updateKey).find(row => String(row?.name || '').trim().toLowerCase() === normalized) || null
 }

 function getPagasaAlertVisual(alert = {}) {
  const riskLevel = String(alert?.risk_level || '').toLowerCase()
  const score = Math.max(0, safeNum(alert?.score, 0))
  const resolvedRisk = riskLevel || (score >= 4 ? 'red' : score >= 1 ? 'yellow' : 'green')
  if (resolvedRisk === 'red') return {
   risk:'red',
   color:'#b91c1c',
   background:'#fff1f1',
   border:'#ef4444',
   badgeBackground:'#b91c1c',
   label:alert?.operational_label || 'CRITICAL / HIGH RISK',
   icon:'🔴'
  }
  if (resolvedRisk === 'yellow') return {
   risk:'yellow',
   color:'#9a6700',
   background:'#fffbea',
   border:'#f5c518',
   badgeBackground:'#eab308',
   label:alert?.operational_label || 'MODERATE / MONITOR',
   icon:'🟡'
  }
  return {
   risk:'green',
   color:'#166534',
   background:'#f0fdf4',
   border:'#4ade80',
   badgeBackground:'#16a34a',
   label:alert?.operational_label || 'GOOD / NO ACTIVE ALERT',
   icon:'🟢'
  }
 }

 function formatPagasaFetchedAt(value = '') {
  if (!value) return 'Not yet loaded'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return String(value)
  return date.toLocaleString('en-PH', {
   timeZone:'Asia/Manila',
   year:'numeric',
   month:'short',
   day:'numeric',
   hour:'numeric',
   minute:'2-digit'
  })
 }


 function getPagasaDateString(value = '') {
  if (!value) return ''
  const raw = String(value || '').trim()
  const isoMatch = raw.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/)
  if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`

  const monthNames = {
   january:1, february:2, march:3, april:4, may:5, june:6,
   july:7, august:8, september:9, october:10, november:11, december:12,
   jan:1, feb:2, mar:3, apr:4, jun:6, jul:7, aug:8, sep:9, sept:9, oct:10, nov:11, dec:12
  }
  const namedDate = raw.match(/\b(\d{1,2})\s+(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(20\d{2})\b/i)
   || raw.match(/\b(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{1,2}),?\s+(20\d{2})\b/i)
  if (namedDate) {
   const startsWithNumber = /^\d/.test(namedDate[1])
   const day = Number(startsWithNumber ? namedDate[1] : namedDate[2])
   const monthName = String(startsWithNumber ? namedDate[2] : namedDate[1]).toLowerCase()
   const year = Number(namedDate[3])
   const month = monthNames[monthName]
   if (year && month && day) return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`
  }

  const parsed = new Date(raw)
  if (Number.isNaN(parsed.getTime())) return ''
  const parts = new Intl.DateTimeFormat('en-CA', {
   timeZone:PH_TIME_ZONE,
   year:'numeric', month:'2-digit', day:'2-digit'
  }).formatToParts(parsed).reduce((acc, part) => {
   if (part.type !== 'literal') acc[part.type] = part.value
   return acc
  }, {})
  return parts.year && parts.month && parts.day ? `${parts.year}-${parts.month}-${parts.day}` : ''
 }

 function getPagasaDayExplicitDate(day = {}) {
  return getPagasaDateString(
   day?.date
   || day?.forecast_date
   || day?.valid_date
   || day?.target_date
   || day?.local_date
   || day?.date_iso
   || ''
  )
 }

 function getPagasaWeekdayIndex(value = '') {
  const key = String(value || '').trim().toLowerCase().replace(/[^a-z]/g, '')
  const weekdayMap = {
   sunday:0, sun:0,
   monday:1, mon:1,
   tuesday:2, tue:2, tues:2,
   wednesday:3, wed:3,
   thursday:4, thu:4, thur:4, thurs:4,
   friday:5, fri:5,
   saturday:6, sat:6
  }
  return Object.prototype.hasOwnProperty.call(weekdayMap, key) ? weekdayMap[key] : null
 }

 function getPagasaReferenceDate(data = pagasaRegion1Data) {
  const directCandidates = [
   data?.regional?.coverage_start_date,
   data?.regional?.forecast_start_date,
   data?.regional?.valid_from,
   data?.regional?.extended_issued_at,
   data?.regional?.issued_at,
   data?.fetched_at
  ]
  for (const candidate of directCandidates) {
   const date = getPagasaDateString(candidate)
   if (date) return date
  }
  const textCandidates = [
   data?.regional?.extended_issued_at_text,
   data?.regional?.issued_at_text
  ]
  for (const candidate of textCandidates) {
   const date = getPagasaDateString(candidate)
   if (date) return date
  }
  return getPHDateTimeParts().date
 }

 function getPagasaForecastCalendar(days = [], data = pagasaRegion1Data) {
  const rows = Array.isArray(days) ? days : []
  if (!rows.length) return []

  const explicitDates = rows.map(day => getPagasaDayExplicitDate(day))
  const firstExplicitIndex = explicitDates.findIndex(Boolean)
  let startDate = ''

  if (firstExplicitIndex >= 0) {
   startDate = addDaysToDateString(explicitDates[firstExplicitIndex], -firstExplicitIndex)
  } else {
   const referenceDate = getPagasaReferenceDate(data)
   const reference = parseLocalDate(referenceDate)
   const firstWeekday = getPagasaWeekdayIndex(rows[0]?.day || rows[0]?.weekday || '')
   if (reference && firstWeekday !== null) {
    const offset = (firstWeekday - reference.getDay() + 7) % 7
    startDate = addDaysToDateString(referenceDate, offset)
   } else {
    startDate = referenceDate
   }
  }

  const todayDate = getPHDateTimeParts().date
  return rows.map((day, index) => {
   const date = explicitDates[index] || addDaysToDateString(startDate, index)
   const dayDiff = dateStringDiffDays(todayDate, date)
   const relativeLabel = dayDiff === 0
    ? 'TODAY'
    : dayDiff === 1
     ? 'TOMORROW'
     : dayDiff > 1
      ? `+${dayDiff} DAYS`
      : dayDiff === -1
       ? 'YESTERDAY'
       : dayDiff < -1
        ? `${Math.abs(dayDiff)} DAYS AGO`
        : ''
   return {
    date,
    exactDateLabel:date ? formatDateForDisplay(date) : 'Date unavailable',
    compactDateLabel:date ? parseLocalDate(date)?.toLocaleDateString('en-US', { month:'short', day:'numeric' }) || date : '—',
    relativeLabel,
    derived:!explicitDates[index]
   }
  })
 }

 function getPagasaCoverageLabel(calendar = []) {
  const dates = (calendar || []).map(item => item?.date).filter(Boolean)
  if (!dates.length) return 'Coverage dates unavailable'
  const start = parseLocalDate(dates[0])
  const end = parseLocalDate(dates[dates.length - 1])
  if (!start || !end) return `${formatDateForDisplay(dates[0])} – ${formatDateForDisplay(dates[dates.length - 1])}`
  const sameYear = start.getFullYear() === end.getFullYear()
  const sameMonth = sameYear && start.getMonth() === end.getMonth()
  if (sameMonth) {
   return `${start.toLocaleDateString('en-US', { month:'short' })} ${start.getDate()}–${end.getDate()}, ${end.getFullYear()}`
  }
  if (sameYear) {
   return `${start.toLocaleDateString('en-US', { month:'short', day:'numeric' })} – ${end.toLocaleDateString('en-US', { month:'short', day:'numeric' })}, ${end.getFullYear()}`
  }
  return `${start.toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' })} – ${end.toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' })}`
 }

 function getPagasaWeatherIcon(condition = '') {
  const text = String(condition || '').toLowerCase()
  if (text.includes('storm') || text.includes('thunder')) return '⛈️'
  if (text.includes('rain') || text.includes('shower')) return '🌧️'
  if (text.includes('cloud')) return '☁️'
  if (text.includes('sun') || text.includes('fair')) return '☀️'
  return '🌦️'
 }

 function isOfficialPagasaUrl(value = '') {
  try {
   const host = new URL(String(value || '')).hostname.toLowerCase()
   return host === 'pagasa.dost.gov.ph' || host.endsWith('.pagasa.dost.gov.ph')
  } catch(error) {
   return false
  }
 }

 function getPagasaForecastOperationalVisual(day = {}) {
  const condition = String(day?.condition || '').trim().toLowerCase()
  const wind = String(day?.wind_speed || '').trim().toLowerCase()
  const coast = String(day?.coastal_condition || '').trim().toLowerCase()
  const conditionParsed = day?.condition_parsed !== false
   && !!condition
   && !condition.includes('could not be parsed')
   && !condition.includes('forecast condition available on the official pagasa page')

  // These colors are an internal delivery/production planning aid derived from
  // official PAGASA condition, wind, and coastal wording. They are not a
  // replacement for PAGASA rainfall-warning colors or municipality warnings.
  const severeCondition = /(stormy|heavy rain|heavy rains|intense rain|torrential|widespread rain|continuous rain|severe thunderstorm)/.test(condition)
  const strongWind = /(strong|gale|stormy)/.test(wind)
  const roughCoast = /(rough|very rough|high seas)/.test(coast)
  if (severeCondition || strongWind || roughCoast) {
   return {
    risk:'red',
    label:conditionParsed?'HIGH CAUTION':'HIGH CAUTION · PARTIAL',
    icon:'🔴',
    color:'#991b1b',
    background:'#fff1f2',
    border:'#ef4444',
    badgeBackground:'#dc2626',
    note:conditionParsed
     ? 'High operational caution. Recheck the latest PAGASA warning before production lock and dispatch.'
     : 'Strong wind or rough-sea wording was parsed, but the forecast condition text needs source review before a final decision.'
   }
  }

  const rainyCondition = /(rain|shower|thunder|storm|overcast|cloudy skies)/.test(condition)
  const moderateWind = /moderate/.test(wind)
  const moderateCoast = /moderate/.test(coast)
  if (rainyCondition || moderateWind || moderateCoast) {
   return {
    risk:'yellow',
    label:conditionParsed?'MONITOR':'MONITOR · PARTIAL',
    icon:'🟡',
    color:'#854d0e',
    background:'#fffbeb',
    border:'#f5c518',
    badgeBackground:'#d99a00',
    note:conditionParsed
     ? 'Monitor conditions and confirm again near the delivery or production decision cutoff.'
     : 'Wind or coastal fields indicate monitoring, but the condition text needs source review before a final decision.'
   }
  }

  if (!conditionParsed) {
   return {
    risk:'review',
    label:'DATA REVIEW',
    icon:'⚪',
    color:'#475569',
    background:'#f8fafc',
    border:'#94a3b8',
    badgeBackground:'#64748b',
    note:'Forecast condition was not completely parsed. Open the official PAGASA page before making a final decision.'
   }
  }

  return {
   risk:'green',
   label:'NORMAL WATCH',
   icon:'🟢',
   color:'#166534',
   background:'#f0fdf4',
   border:'#4ade80',
   badgeBackground:'#16a34a',
   note:'Favorable regional baseline. Continue routine monitoring because local weather can still change.'
  }
 }

 function derivePagasaGuardLevel(data = pagasaRegion1Data, municipalityName = pagasaSelectedMunicipality, updateKey = pagasaSelectedUpdateKey) {
  const alert = getPagasaSelectedMunicipalityAlert(municipalityName, data, updateKey)
  const riskLevel = String(alert?.risk_level || '').toLowerCase()
  const score = Math.max(0, safeNum(alert?.score, 0))
  if (riskLevel === 'red' || score >= 4) return 'heavy_rain'
  if (riskLevel === 'yellow' || score >= 1) return 'moderate_rain'
  const regionalConditions = (data?.regional?.days || []).slice(0,3).map(day => String(day?.condition || '')).join(' ').toLowerCase()
  if (regionalConditions.includes('rain') || regionalConditions.includes('thunder') || (data?.announcements || []).length > 0) return 'watch'
  return 'no_warning'
 }

 function getPagasaOperationalSummary(data = pagasaRegion1Data, municipalityName = pagasaSelectedMunicipality, updateKey = pagasaSelectedUpdateKey) {
  const alert = getPagasaSelectedMunicipalityAlert(municipalityName, data, updateKey)
  const selectedUpdate = getPagasaSelectedUpdateView(data, updateKey)
  const forecastDays = selectedUpdate?.forecast_day ? [selectedUpdate.forecast_day] : (data?.regional?.days || []).slice(0,3)
  const conditions = forecastDays.map(day => `${day.day}: ${day.condition}`).join(' | ')
  const updateBasis = selectedUpdate
   ? `${selectedUpdate.title || 'PAGASA bulletin'}${selectedUpdate.issued_at_text ? ` (${selectedUpdate.issued_at_text})` : ''}`
   : 'latest applicable PAGASA updates (combined)'
  return `${municipalityName}: ${alert?.status_label || 'No active municipality mention found'}. Display basis: ${updateBasis}. Region 1 outlook: ${conditions || 'No parsed forecast available.'}`
 }

 async function loadPagasaRegion1Weather(options = {}) {
  const force = options.force === true
  const silent = options.silent === true
  setPagasaRegion1Loading(true)
  if (!silent) setPagasaRegion1Error('')
  try {
   const { data, error } = await supabase.functions.invoke('pagasa-region1-weather-v6', {
    body:{ force }
   })
   if (error) throw error
   if (data?.error) throw new Error(data?.details || data.error)
   if (!Array.isArray(data?.regional?.days) || data.regional.days.length < 3) {
    throw new Error('PAGASA returned an incomplete regional outlook.')
   }
   const sourceUrls = Object.values(data?.source_urls || {}).filter(Boolean)
   if (String(data?.provider || '').trim() !== 'DOST-PAGASA' || !sourceUrls.length || !sourceUrls.every(isOfficialPagasaUrl)) {
    throw new Error('PAGASA source verification failed. One or more returned sources are not official PAGASA domains.')
   }
   const qualityWarning = data?.data_quality && data.data_quality.status !== 'verified_live_parse'
    ? `Official PAGASA data loaded, but ${Math.max(0, safeNum(data?.data_quality?.regional_days_count, data?.regional?.days?.length || 0) - safeNum(data?.data_quality?.complete_conditions, 0))} forecast condition field(s) require review.`
    : ''
   setPagasaRegion1Data(data)
   const refreshedUpdateOptions = getPagasaUpdateOptions(data)
   if (!refreshedUpdateOptions.some(option => String(option.value) === String(pagasaSelectedUpdateKey))) {
    setPagasaSelectedUpdateKey('latest')
   }
   setPagasaRegion1Error(data?.stale
    ? `Live PAGASA retrieval failed. Showing the last successful cached snapshot${data?.cache_age_minutes != null ? ` from ${data.cache_age_minutes} minute(s) ago` : ''}.`
    : qualityWarning)
   if (!getPagasaSelectedMunicipalityAlert(pagasaSelectedMunicipality, data)) {
    const defaultTown = getPagasaMunicipalityRows(data).find(row => row.name === 'Dagupan City')?.name
     || getPagasaMunicipalityRows(data)[0]?.name
     || 'Dagupan City'
    setPagasaSelectedMunicipality(defaultTown)
   }
   if (force) setPagasaLastManualRefresh(new Date().toISOString())
   if (!silent) {
    showToast(data?.stale
     ? 'PAGASA live source was unavailable. The last successful official snapshot is displayed.'
     : 'Official PAGASA Region 1 weather and Pangasinan advisories refreshed.',
     data?.stale ? 'orange' : 'green')
   }
   return data
  } catch(error) {
   console.error('PAGASA Region 1 load failed:', error)
   const message = String(error?.message || error || 'Unknown PAGASA error')
   // Preserve the last usable snapshot for continuity, but visibly downgrade it
   // to cached/stale so a failed refresh can never keep a misleading LIVE label.
   setPagasaRegion1Data(previous => previous
    ? { ...previous, stale:true, cached:true, live_error:message }
    : previous
   )
   setPagasaRegion1Error(`Live PAGASA refresh failed. ${message}${pagasaRegion1Data ? ' The last displayed snapshot is retained and marked stale.' : ''}`)
   if (!silent) showToast(`PAGASA weather failed: ${message}`, 'red')
   return null
  } finally {
   setPagasaRegion1Loading(false)
  }
 }

 function applyPagasaDataToWeatherGuard(options = {}) {
  const data = options.data || pagasaRegion1Data
  const updateKey = options.updateKey || pagasaSelectedUpdateKey
  const municipalityName = options.municipalityName || pagasaSelectedMunicipality || 'Dagupan City'
  const targetDate = options.targetDate || forecastDate
  if (!data) {
   showToast('Load PAGASA data first.', 'red')
   return false
  }
  const alert = getPagasaSelectedMunicipalityAlert(municipalityName, data, updateKey)
  const selectedUpdate = getPagasaSelectedUpdateView(data, updateKey)
  const weatherLevel = derivePagasaGuardLevel(data, municipalityName, updateKey)
  const sourceUrl = selectedUpdate?.source_url || data?.source_urls?.regional || 'https://pagasa.dost.gov.ph/regional-forecast/nlprsd'
  const issuedText = selectedUpdate?.issued_at_text || data?.regional?.extended_issued_at_text || data?.regional?.issued_at_text || ''
  const summary = getPagasaOperationalSummary(data, municipalityName, updateKey)
  setWeatherGuardDraft(prev => ({
   ...prev,
   weather_level:weatherLevel,
   weather_source_type:'pagasa',
   weather_location:`${municipalityName}, Pangasinan / Region 1${targetDate ? ` · Delivery ${targetDate}` : ''}`,
   weather_issued_at:toWeatherGuardDateTimeLocal(data?.fetched_at || new Date().toISOString()),
   weather_reference:[
    `Official PAGASA Northern Luzon source: ${sourceUrl}`,
    selectedUpdate?.title ? `Displayed update: ${selectedUpdate.title}` : 'Displayed update: latest applicable PAGASA updates (combined)',
    issuedText ? `PAGASA issue: ${issuedText}` : '',
    alert?.warning_type ? `${alert.warning_type}: ${alert.status_label}` : '',
    data?.stale ? 'Displayed from last successful cached PAGASA snapshot.' : 'Retrieved live through the secured PAGASA Region 1 function.'
   ].filter(Boolean).join(' | '),
   decision_notes:[prev.decision_notes, `PAGASA import — ${summary}`].filter(Boolean).join(' | ')
  }))
  if (options.switchToOperations !== false) setDeliveriesSubTab('operations')
  setShowWeatherGuard(true)
  if (!options.silent) {
   showToast('PAGASA condition copied to the operations forecast draft. Review it before saving or locking production.')
   setTimeout(() => {
    const guard = document.getElementById('weather-class-suspension-guard')
    if (guard) guard.scrollIntoView({ behavior:'smooth', block:'start' })
   }, 150)
  }
  return true
 }

 function applyPagasaToWeatherGuard() {
  return applyPagasaDataToWeatherGuard({
   data:pagasaRegion1Data,
   updateKey:pagasaSelectedUpdateKey,
   municipalityName:pagasaSelectedMunicipality,
   targetDate:forecastDate,
   switchToOperations:true,
   silent:false
  })
 }

 function openPagasaOfficialSource(url = '') {
  const safeUrl = String(url || '').trim()
  if (!safeUrl.startsWith('https://pagasa.dost.gov.ph/') && !safeUrl.startsWith('https://origin.pagasa.dost.gov.ph/')) {
   showToast('Official PAGASA source link is unavailable.', 'red')
   return
  }
  window.open(safeUrl, '_blank', 'noopener,noreferrer')
 }

 async function printDTR(empId, empName, empCode, startOrMonth, endDateArg = null, periodLabelArg = '') {
 let startDate = startOrMonth
 let endDate = endDateArg
 let periodLabel = periodLabelArg

 // Backward compatible: old callers pass month format YYYY-MM.
 if (!endDate && /^\d{4}-\d{2}$/.test(String(startOrMonth || ''))) {
  const [y, m] = String(startOrMonth).split('-').map(Number)
  startDate = `${startOrMonth}-01`
  endDate = `${y}-${pad2(m)}-${pad2(new Date(y, m, 0).getDate())}`
  periodLabel = new Date(`${startOrMonth}-01`).toLocaleString('default', { month:'long', year:'numeric' })
 }
 if (!startDate || !endDate) { showToast('Please select a valid DTR cutoff period.', 'red'); return }
 if (!periodLabel) periodLabel = `${formatDateForDisplay(startDate)} – ${formatDateForDisplay(endDate)}`

 const { data: logs } = await supabase.from('attendance_logs').select('*')
.eq('employee_id', empId).gte('attendance_date', startDate).lte('attendance_date', endDate)
.order('attendance_date')
 const { data: emp } = await supabase.from('employees').select(EMPLOYEE_SELECT_FIELDS).eq('id', empId).single()
 const scheduledLogs = await hydrateAttendanceLogsWithScheduleFallback(logs || [], emp, startDate, endDate)
 const enrichedLogs = await enrichAttendanceLogsWithBreakRows(scheduledLogs)
 const policyLogs = attachAttendanceEmployeePolicy(enrichedLogs, emp || { id:empId, employee_code:empCode, full_name:empName })
 const grouped = groupDTRLogsByDate(policyLogs)
 const mergedLogs = Object.values(grouped).map(dayLogs => mergeDTRDayLogs(dayLogs)).filter(Boolean)
 const totalDaysWorked = new Set(mergedLogs.filter(l=>getAttendanceDayIntegrity(getDTRDayLogs(l)).isValidCompleted).map(l=>String(l.attendance_date || '').slice(0,10))).size
 const totalAbsent = new Set(mergedLogs.filter(l=>l.status==='Absent').map(l=>String(l.attendance_date || '').slice(0,10))).size
 const totalLate = mergedLogs.reduce((s,l)=>s+getDTRLateMinutes(l),0) || 0
 const totalOT = mergedLogs.reduce((s,l)=>s+getDTRApprovedOvertimeMinutes(l),0) || 0
 const totalUT = mergedLogs.reduce((s,l)=>s+getDTRUndertimeMinutes(l),0) || 0
 const totalBreak = mergedLogs.reduce((s,l)=>s+getDTRBreakMinutes(l),0) || 0
 const totalOverbreak = mergedLogs.reduce((s,l)=>s+getDTROverbreakMinutes(l),0) || 0
 const totalDutyMinutes = mergedLogs.reduce((s,l)=>s+getDTRDutyMinutes(l),0) || 0
 const duplicateDays = Object.values(grouped).filter(dayLogs => dayLogs.length > 1).length

 const rows = buildDateRangeRows(startDate, endDate, ({ dateStr, day, dayName }) => {
 const log = mergeDTRDayLogs(grouped[dateStr] || [])
 return `<tr style="border-bottom:1px solid #eee;">
 <td style="padding:5px 8px;font-size:10px;color:#888;">${dayName}</td>
 <td style="padding:5px 8px;font-size:10px;text-align:center;">${formatDateForDisplay(dateStr)}</td>
 <td style="padding:5px 8px;font-size:10px;text-align:center;color:${log?.time_in?'#000':'#ccc'}">${log?.time_in||' '}</td>
 <td style="padding:5px 8px;font-size:10px;text-align:center;color:${log?.time_out?'#000':'#ccc'}">${log?.time_out||' '}</td>
 <td style="padding:5px 8px;font-size:10px;text-align:center;">${log?getDTRBreakMinutes(log):0}</td>
 <td style="padding:5px 8px;font-size:10px;text-align:center;color:${getDTROverbreakMinutes(log)>0?'#ca1b1b':'#777'};font-weight:${getDTROverbreakMinutes(log)>0?'bold':'normal'};">${getDTROverbreakMinutes(log)}</td>
 <td style="padding:5px 8px;font-size:10px;text-align:center;font-weight:bold;color:${getDTRDutyMinutes(log)>0?'#1a1a2e':'#ccc'}">${log?formatDutyHours(getDTRDutyMinutes(log)):' '}</td>
 <td style="padding:5px 8px;font-size:10px;text-align:center;color:${getDTRLateMinutes(log)>0?'#ca1b1b':'#000'}">${getDTRLateMinutes(log)}</td>
 <td style="padding:5px 8px;font-size:10px;text-align:center;color:${getDTRUndertimeMinutes(log)>0?'#ca1b1b':'#000'}">${getDTRUndertimeMinutes(log)}</td>
 <td style="padding:5px 8px;font-size:10px;text-align:center;color:${getDTRApprovedOvertimeMinutes(log)>0?'#2d8a4e':'#000'}">${getDTRApprovedOvertimeMinutes(log)}</td>
 <td style="padding:5px 8px;font-size:10px;text-align:center;">
 ${!log?'':`<span style="color:${getDTRStatusInfo(log).color==='red'?'#ca1b1b':getDTRStatusInfo(log).color==='orange'?'#f5a623':getDTRStatusInfo(log).color==='blue'?'#4a90d9':'#2d8a4e'};font-weight:bold;">${getDTRStatusInfo(log).label}</span>`}
 </td>
 </tr>`
 }).join('')

 const pw = window.open('','_blank','width=420,height=660')
 pw.document.write(`<!DOCTYPE html><html><head><title>DTR - ${empName} - ${periodLabel}</title>
 <style>
 *{margin:0;padding:0;box-sizing:border-box;}
 body{font-family:Arial,sans-serif;padding:15mm;font-size:12px;color:#000;}
 table{width:100%;border-collapse:collapse;}
 th{background:#ca1b1b;color:white;padding:6px 8px;font-size:10px;}
 @media print{@page{size:A4 portrait;margin:10mm;}body{padding:5mm;}}
 </style></head><body>
 <div style="text-align:center;margin-bottom:16px;border-bottom:2px solid #ca1b1b;padding-bottom:10px;">
 <div style="font-size:20px;font-weight:bold;color:#ca1b1b;">Roma's Donuts</div>
 <div style="font-size:11px;color:#666;">Payroll &amp; Attendance System</div>
 <div style="font-size:15px;font-weight:bold;margin-top:6px;">DAILY TIME RECORD (DTR)</div>
 <div style="font-size:12px;margin-top:2px;">${periodLabel}</div>
 <div style="font-size:10px;color:#666;margin-top:2px;">Cutoff Period: ${startDate} to ${endDate}</div>
 </div>
 <div style="background:#fff8dc;border:1px solid #ca1b1b;border-radius:6px;padding:10px;margin-bottom:14px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;">
 <div>
 <div style="font-size:15px;font-weight:bold;color:#ca1b1b;">${empName}</div>
 <div style="font-size:11px;color:#555;">Employee Code: ${empCode}</div>
 <div style="font-size:11px;color:#555;">Position: ${emp?.position||' '} | Department: ${emp?.department||' '}</div>
 ${duplicateDays>0?`<div style="font-size:10px;color:#f5a623;font-weight:bold;margin-top:4px;">Warning: ${duplicateDays} day(s) have duplicate attendance logs.</div>`:''}
 </div>
 <div style="text-align:right;">
 <div style="font-size:11px;">Days Worked: <strong>${totalDaysWorked}</strong></div>
 <div style="font-size:11px;">Absences: <strong style="color:#ca1b1b;">${totalAbsent}</strong></div>
 <div style="font-size:11px;">Total Late: <strong style="color:#f5a623;">${totalLate} min</strong></div>
 <div style="font-size:11px;">Total OT: <strong style="color:#2d8a4e;">${totalOT} min</strong></div>
 <div style="font-size:11px;">Total UT: <strong style="color:#ca1b1b;">${totalUT} min</strong></div>
 <div style="font-size:11px;">Automatic / Actual Break Deducted: <strong>${totalBreak} min</strong></div>
 <div style="font-size:11px;">Total Overbreak: <strong style="color:#ca1b1b;">${totalOverbreak} min</strong></div>
 <div style="font-size:11px;">Duty Hours: <strong>${formatDutyHours(totalDutyMinutes)}</strong></div>
 </div>
 </div>
 <table>
 <thead><tr>
 <th>Day</th><th>Date</th><th>Time In</th><th>Time Out</th>
 <th>Break (min)</th><th>Overbreak</th><th>Duty Hours</th><th>Late (min)</th><th>UT (min)</th><th>OT (min)</th><th>Status</th>
 </tr></thead>
 <tbody>${rows}</tbody>
 <tfoot>
 <tr style="background:#f5f5f5;font-weight:bold;">
 <td colspan="2" style="padding:6px 8px;font-size:10px;">TOTALS</td>
 <td style="padding:6px 8px;font-size:10px;text-align:center;">${totalDaysWorked} day(s)</td><td></td>
 <td style="padding:6px 8px;font-size:10px;text-align:center;">${totalBreak}</td>
 <td style="padding:6px 8px;font-size:10px;text-align:center;color:#ca1b1b;">${totalOverbreak}</td>
 <td style="padding:6px 8px;font-size:10px;text-align:center;color:#1a1a2e;">${formatDutyHours(totalDutyMinutes)}</td>
 <td style="padding:6px 8px;font-size:10px;text-align:center;color:#ca1b1b;">${totalLate}</td>
 <td style="padding:6px 8px;font-size:10px;text-align:center;color:#ca1b1b;">${totalUT}</td>
 <td style="padding:6px 8px;font-size:10px;text-align:center;color:#2d8a4e;">${totalOT}</td>
 <td></td>
 </tr>
 </tfoot>
 </table>
 <div style="margin-top:30px;display:flex;justify-content:space-between;">
 <div style="text-align:center;"><div style="border-top:1px solid #000;width:150px;padding-top:4px;font-size:10px;">Employee Signature</div></div>
 <div style="text-align:center;"><div style="border-top:1px solid #000;width:150px;padding-top:4px;font-size:10px;">Verified by</div></div>
 </div>
 <p style="text-align:center;font-size:9px;color:#aaa;margin-top:15px;">Generated by Roma's Donuts Payroll System</p>
 </body></html>`)
 pw.document.close()
 setTimeout(()=>{ pw.focus(); pw.print() },800)
 }

